css:
@property --dlo-docket-ring {
  syntax: "<percentage>";
  inherits: false;
  initial-value: 0%;
}

.dlo-docket {
  /* re-theme with these four */
  --dlo-docket-paper: oklch(0.975 0.009 84);
  --dlo-docket-ink: oklch(0.255 0.022 52);
  --dlo-docket-accent: oklch(0.47 0.145 26);
  --dlo-docket-gold: oklch(0.76 0.115 78);
  /* matter hues share one lightness and chroma so no matter shouts */
  --dlo-docket-m0: oklch(0.56 0.1 196);
  --dlo-docket-m1: oklch(0.58 0.11 140);
  --dlo-docket-m2: oklch(0.6 0.12 62);
  --dlo-docket-m3: oklch(0.55 0.12 340);
  --dlo-docket-m4: oklch(0.54 0.1 262);
  /* derived */
  --dlo-docket-side: color-mix(in oklch, var(--dlo-docket-paper) 93%, var(--dlo-docket-ink));
  --dlo-docket-card: color-mix(in oklch, var(--dlo-docket-paper) 55%, white);
  --dlo-docket-line: color-mix(in oklch, var(--dlo-docket-ink) 13%, transparent);
  --dlo-docket-hair: color-mix(in oklch, var(--dlo-docket-ink) 7%, transparent);
  --dlo-docket-wash: color-mix(in oklch, var(--dlo-docket-ink) 4.5%, transparent);
  --dlo-docket-mute: color-mix(in oklch, var(--dlo-docket-ink) 64%, var(--dlo-docket-paper));
  --dlo-docket-faint: color-mix(in oklch, var(--dlo-docket-ink) 42%, var(--dlo-docket-paper));
  --dlo-docket-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dlo-docket-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dlo-docket-out: cubic-bezier(.19, 1, .22, 1);
  --dlo-docket-in-out: cubic-bezier(.65, 0, .35, 1);
  --dlo-docket-spring: linear(0, 0.009, 0.035 2.1%, 0.141 4.4%, 0.723 12.9%, 0.938 16.7%, 1.017 19.4%, 1.067, 1.099 24.3%, 1.104 26.9%, 1.097 29.7%, 1.051 34.8%, 0.987 44.4%, 0.98 47.4%, 0.985 54.3%, 1.002 66.7%, 1);

  width: 100%;
  height: var(--dlo-docket-h, 680px);
  container-type: inline-size; container-name: dlo-docket;
  position: relative;
  isolation: isolate;
  overflow: hidden;
  border-radius: 14px;
  background: var(--dlo-docket-paper);
  color: var(--dlo-docket-ink);
  font: 13px/1.45 var(--dlo-docket-sans);
  accent-color: var(--dlo-docket-accent);
  color-scheme: light;
  box-shadow: inset 0 0 0 1px var(--dlo-docket-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, p, ol, fieldset, legend) { margin: 0; padding: 0; }
  & :where(ol) { list-style: none; }
  & :where(fieldset) { border: 0; min-width: 0; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
  & :where(svg) { display: block; }
  & :focus-visible { outline: 2px solid var(--dlo-docket-accent); outline-offset: 2px; border-radius: 6px; }
  & .dlo-docket__scroll {
    overflow: auto; overscroll-behavior: contain;
    scrollbar-width: thin; scrollbar-color: color-mix(in oklch, var(--dlo-docket-ink) 22%, transparent) transparent;
  }
}

.dlo-docket__shell {
  height: 100%;
  display: grid;
  grid-template-columns: 232px minmax(0, 1fr);
  grid-template-areas: "side main";
}

/* ---------- side */
.dlo-docket__side {
  grid-area: side; min-height: 0;
  display: flex; flex-direction: column; gap: 18px;
  padding: 18px 14px 14px;
  background: var(--dlo-docket-side);
  border-right: 1px solid var(--dlo-docket-line);
  overflow: auto; scrollbar-width: none;
}
.dlo-docket__brand {
  display: flex; align-items: center; gap: 10px; padding: 0 4px;
  & svg { width: 32px; height: 32px; flex: none; padding: 5px; border-radius: 8px; background: var(--dlo-docket-ink); fill: none; stroke: var(--dlo-docket-paper); stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
  & b { display: block; font-size: 15px; font-weight: 720; letter-spacing: -.015em; line-height: 1.1; font-family: ui-serif, "New York", Georgia, serif; }
  & small { display: block; font-size: 11px; color: var(--dlo-docket-mute); letter-spacing: .02em; }
}
.dlo-docket__nav {
  display: grid; gap: 2px;
  & button {
    display: flex; align-items: center; gap: 10px; padding: 7px 10px; border-radius: 8px;
    color: var(--dlo-docket-mute); font-weight: 560;
    transition: background-color .2s, color .2s;
  }
  & button:hover { background: var(--dlo-docket-wash); color: var(--dlo-docket-ink); }
  & button[aria-current=page] { background: var(--dlo-docket-card); color: var(--dlo-docket-ink); box-shadow: 0 0 0 1px var(--dlo-docket-line), 0 1px 2px var(--dlo-docket-hair); }
  & svg { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  & button[aria-current=page] svg { stroke: var(--dlo-docket-accent); }
}
.dlo-docket__filters {
  display: grid; gap: 1px;
  & legend { font-size: 10.5px; font-weight: 650; letter-spacing: .09em; text-transform: uppercase; color: var(--dlo-docket-faint); padding: 0 6px 6px; }
  & label {
    display: grid; grid-template-columns: 16px minmax(0, 1fr) auto; align-items: center; gap: 8px;
    padding: 5px 6px; border-radius: 7px; cursor: pointer; transition: background-color .2s;
  }
  & label:hover { background: var(--dlo-docket-wash); }
  & input { width: 14px; height: 14px; margin: 0; accent-color: var(--c, var(--dlo-docket-accent)); }
  & span { min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-size: 12.5px; }
  & small { font: 500 11px var(--dlo-docket-mono); color: var(--dlo-docket-faint); font-variant-numeric: tabular-nums; }
  & label:has(input:not(:checked)) span { color: var(--dlo-docket-faint); text-decoration: line-through; text-decoration-color: var(--dlo-docket-line); }
}
.dlo-docket__kinds label { grid-template-columns: 16px minmax(0, 1fr); }

.dlo-docket__load {
  margin-top: auto;
  & h3 { font-size: 10.5px; font-weight: 650; letter-spacing: .09em; text-transform: uppercase; color: var(--dlo-docket-faint); padding: 0 6px 8px; }
}
.dlo-docket__loadchart {
  width: 100%; height: 118px; overflow: visible;
  & .ax { font: 500 9.5px var(--dlo-docket-mono); fill: var(--dlo-docket-faint); font-variant-numeric: tabular-nums; }
  & .gl { stroke: var(--dlo-docket-hair); }
  & .wk { cursor: pointer; outline: none; }
  & .wk .hit { fill: transparent; }
  & .wk:hover .hit, & .wk:focus-visible .hit { fill: var(--dlo-docket-wash); }
  & .wk:focus-visible .hit { stroke: var(--dlo-docket-accent); stroke-width: 1.5; }
  & .seg { transform-box: fill-box; transform-origin: 50% 100%; }
  & .now { fill: var(--dlo-docket-accent); }
}
.dlo-docket.is-enter .dlo-docket__loadchart .seg {
  animation: dlo-docket-grow .7s var(--dlo-docket-out) both;
  animation-delay: calc(var(--i) * 40ms + 120ms);
}

/* ---------- main */
.dlo-docket__main {
  grid-area: main; min-width: 0; min-height: 0;
  display: grid; grid-template-rows: auto minmax(0, 1fr);
}
.dlo-docket__head {
  display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: end; gap: 6px 20px;
  padding: 16px 20px 12px;
  border-bottom: 1px solid var(--dlo-docket-line);
}
.dlo-docket__eyebrow { font-size: 11px; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; color: var(--dlo-docket-accent); }
.dlo-docket__title h2 {
  font-family: ui-serif, "New York", Georgia, serif;
  font-size: clamp(22px, 2.6cqi, 30px); font-weight: 600; letter-spacing: -.02em; line-height: 1.05;
  text-wrap: balance; font-variant-numeric: lining-nums;
}
.dlo-docket__summary {
  justify-self: end; text-align: right; color: var(--dlo-docket-mute); font-size: 12px; text-wrap: pretty; max-width: 46ch;
  & b { color: var(--dlo-docket-ink); font-weight: 650; font-variant-numeric: tabular-nums; }
}
.dlo-docket__pager {
  display: flex; gap: 2px; padding: 3px; border-radius: 10px; background: var(--dlo-docket-wash);
  & button { display: grid; place-items: center; min-width: 30px; height: 28px; padding: 0 8px; border-radius: 7px; font-weight: 600; font-size: 12px; color: var(--dlo-docket-mute); transition: background-color .2s, color .2s; }
  & button:hover { background: var(--dlo-docket-card); color: var(--dlo-docket-ink); }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
}

.dlo-docket__views { position: relative; min-height: 0; }
.dlo-docket__view { height: 100%; }
.dlo-docket__view[hidden] { display: none; }

/* ---------- month */
.dlo-docket__month { display: grid; grid-template-rows: auto minmax(0, 1fr); padding: 0 12px 12px; }
.dlo-docket__dow {
  display: grid; grid-template-columns: repeat(7, minmax(0, 1fr));
  & span { padding: 8px 8px 6px; font-size: 10.5px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase; color: var(--dlo-docket-faint); }
}
.dlo-docket__grid {
  container-type: inline-size; container-name: dlo-docket-cal;
  display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); grid-template-rows: repeat(var(--rows, 5), minmax(0, 1fr));
  min-height: 0; border-radius: 10px; overflow: hidden;
  background: var(--dlo-docket-line); gap: 1px; box-shadow: 0 0 0 1px var(--dlo-docket-line);
}
.dlo-docket__row { display: contents; }
.dlo-docket__cell {
  position: relative; min-width: 0; min-height: 0; overflow: hidden;
  display: flex; flex-direction: column; gap: 3px; padding: 5px 5px 4px;
  background: var(--dlo-docket-card);
  &.is-weekend { background: color-mix(in oklch, var(--dlo-docket-card) 70%, var(--dlo-docket-side)); }
  &.is-out { background: var(--dlo-docket-side); }
  &.is-out .dlo-docket__dnum { color: var(--dlo-docket-faint); opacity: .7; }
  &.is-holiday {
    background:
      repeating-linear-gradient(135deg, color-mix(in oklch, var(--dlo-docket-gold) 22%, transparent) 0 1px, transparent 1px 7px),
      color-mix(in oklab, var(--dlo-docket-card) 85%, var(--dlo-docket-gold));
  }
  &.is-flash { animation: dlo-docket-flash 1.4s var(--dlo-docket-in-out); }
  &:has(.is-urgent)::after {
    content: ""; position: absolute; top: 0; right: 0; border: 6px solid transparent;
    border-top-color: var(--dlo-docket-accent); border-right-color: var(--dlo-docket-accent);
  }
}
.dlo-docket__dhead { display: flex; align-items: baseline; gap: 6px; min-width: 0; }
.dlo-docket__dnum {
  flex: none; display: grid; place-items: center; min-width: 22px; height: 22px; padding: 0 4px; border-radius: 11px;
  font: 600 12px var(--dlo-docket-sans); font-variant-numeric: tabular-nums; color: var(--dlo-docket-mute);
  .is-today & { background: var(--dlo-docket-accent); color: var(--dlo-docket-paper); }
}
.dlo-docket__hol { min-width: 0; font-size: 10px; font-weight: 600; color: color-mix(in oklab, var(--dlo-docket-gold) 55%, var(--dlo-docket-ink)); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.dlo-docket__chip {
  --c: var(--dlo-docket-m0);
  position: relative; display: flex; align-items: center; gap: 5px; min-width: 0; width: 100%;
  padding: 2px 6px 2px 7px; border-radius: 5px;
  font-size: 11.25px; font-weight: 560; line-height: 1.35;
  background: color-mix(in oklab, var(--c) 13%, var(--dlo-docket-card));
  color: color-mix(in oklab, var(--c) 55%, var(--dlo-docket-ink));
  box-shadow: inset 2.5px 0 0 var(--c);
  transition: background-color .18s, transform .25s var(--dlo-docket-spring), box-shadow .18s;
  & span { min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & svg { width: 11px; height: 11px; flex: none; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
  &:hover { background: color-mix(in oklab, var(--c) 22%, var(--dlo-docket-card)); transform: translateX(1px); }
  &.is-event { background: var(--dlo-docket-card); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--c) 45%, transparent); }
  &.is-done { opacity: .55; & span { text-decoration: line-through; text-decoration-color: color-mix(in oklch, var(--c) 60%, transparent); } }
  &.is-urgent { box-shadow: inset 2.5px 0 0 var(--c), 0 0 0 1px color-mix(in oklch, var(--dlo-docket-accent) 55%, transparent); }
  &[aria-expanded=true] { background: var(--c); color: var(--dlo-docket-paper); }
  .dlo-docket.is-enter & { animation: dlo-docket-chip .55s var(--dlo-docket-out) both; animation-delay: calc(var(--i) * 22ms); }
}
.dlo-docket__more {
  align-self: flex-start; padding: 1px 6px; border-radius: 5px; font: 600 10.5px var(--dlo-docket-mono); color: var(--dlo-docket-mute);
  &:hover { background: var(--dlo-docket-wash); color: var(--dlo-docket-ink); }
}
/* narrow calendar: entries collapse to dots, the cell keeps the count */
@container dlo-docket-cal (width < 520px) {
  .dlo-docket__cell { flex-flow: row wrap; align-content: flex-start; gap: 3px; padding: 3px; }
  .dlo-docket__dhead { width: 100%; }
  .dlo-docket__hol { display: none; }
  .dlo-docket__chip { width: 9px; height: 9px; padding: 0; border-radius: 50%; background: var(--c); box-shadow: none; & span, & svg { display: none; } }
  .dlo-docket__chip.is-event { background: transparent; box-shadow: inset 0 0 0 2px var(--c); }
  .dlo-docket__chip.is-urgent { box-shadow: 0 0 0 1.5px var(--dlo-docket-accent); }
  .dlo-docket__chip:hover { transform: scale(1.25); }
  .dlo-docket__more { font-size: 9px; padding: 0 3px; }
  .dlo-docket__dnum { min-width: 18px; height: 18px; font-size: 11px; }
}

/* ---------- agenda */
.dlo-docket__agenda { padding: 4px 20px 20px; }
.dlo-docket__alist { display: grid; gap: 2px; max-width: 880px; }
.dlo-docket__wk {
  position: sticky; top: 0; z-index: 1;
  display: flex; justify-content: space-between; gap: 12px;
  padding: 14px 4px 6px; background: var(--dlo-docket-paper);
  font-size: 10.5px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase; color: var(--dlo-docket-faint);
  border-bottom: 1px solid var(--dlo-docket-line);
  & b { font-weight: 650; color: var(--dlo-docket-mute); font-variant-numeric: tabular-nums; }
}
.dlo-docket__opt {
  --c: var(--dlo-docket-m0);
  display: grid; grid-template-columns: 64px 10px minmax(0, 1fr) auto; align-items: center; gap: 2px 12px;
  padding: 9px 10px; border-radius: 9px; cursor: pointer;
  transition: background-color .18s;
  &:hover { background: var(--dlo-docket-wash); }
  &[aria-selected=true] { background: var(--dlo-docket-card); box-shadow: 0 0 0 1px var(--dlo-docket-line), 0 2px 6px var(--dlo-docket-hair); }
  &:focus-visible { outline-offset: -2px; }
  & .d { font: 600 12px var(--dlo-docket-mono); font-variant-numeric: tabular-nums; color: var(--dlo-docket-mute); line-height: 1.2; }
  & .d small { display: block; font: 500 10.5px var(--dlo-docket-sans); color: var(--dlo-docket-faint); text-transform: uppercase; letter-spacing: .06em; }
  & i { width: 10px; height: 10px; border-radius: 50%; background: var(--c); }
  &.is-event i { background: transparent; box-shadow: inset 0 0 0 2px var(--c); transform: rotate(45deg); border-radius: 2px; }
  & .t b { display: block; font-weight: 620; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .t small { display: block; color: var(--dlo-docket-mute); font-size: 11.5px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .cd { font: 600 11px var(--dlo-docket-mono); font-variant-numeric: tabular-nums; padding: 2px 7px; border-radius: 99px; background: var(--dlo-docket-wash); color: var(--dlo-docket-mute); white-space: nowrap; }
  & .cd.is-hot { background: color-mix(in oklch, var(--dlo-docket-accent) 14%, transparent); color: var(--dlo-docket-accent); }
  & .cd.is-done { text-decoration: line-through; }
  &.is-done .t b { color: var(--dlo-docket-faint); text-decoration: line-through; }
}
@supports (animation-timeline: view()) {
  .dlo-docket__opt {
    animation: dlo-docket-rise linear both;
    animation-timeline: view();
    animation-range: entry 0% entry 70%;
  }
}

/* ---------- chains */
.dlo-docket__chains { padding: 14px 20px 18px; }
.dlo-docket__chainhint { max-width: 70ch; color: var(--dlo-docket-mute); font-size: 12px; text-wrap: pretty; margin-bottom: 8px; }
.dlo-docket__chainsvg {
  min-width: 720px; width: 100%; overflow: visible;
  & .lane { fill: var(--dlo-docket-wash); }
  & .lname { font: 650 11.5px var(--dlo-docket-sans); fill: var(--dlo-docket-ink); }
  & .lsub { font: 500 10px var(--dlo-docket-mono); fill: var(--dlo-docket-faint); }
  & .ax { font: 500 10px var(--dlo-docket-mono); fill: var(--dlo-docket-faint); }
  & .gl { stroke: var(--dlo-docket-hair); }
  & .hol { fill: color-mix(in oklch, var(--dlo-docket-gold) 26%, transparent); }
  & .today { stroke: var(--dlo-docket-accent); stroke-width: 1.5; stroke-dasharray: 3 3; }
  & .todayl { font: 650 10px var(--dlo-docket-sans); fill: var(--dlo-docket-accent); letter-spacing: .06em; text-transform: uppercase; }
  & .arc { fill: none; stroke: var(--c); stroke-width: 1.4; opacity: .55; transition: opacity .2s, stroke-width .2s; }
  & .roll { fill: none; stroke: var(--dlo-docket-gold); stroke-width: 2; stroke-linecap: round; }
  & .node { cursor: pointer; outline: none; }
  & .node .dot { fill: var(--c); stroke: var(--dlo-docket-card); stroke-width: 2; transition: transform .3s var(--dlo-docket-spring); transform-box: fill-box; transform-origin: center; }
  & .node.is-trig .dot { fill: var(--dlo-docket-card); stroke: var(--c); stroke-width: 2.2; }
  & .node.is-done .dot { opacity: .45; }
  & .node:hover .dot, & .node:focus-visible .dot { transform: scale(1.45); }
  & .node:focus-visible .ring { stroke: var(--dlo-docket-accent); }
  & .ring { fill: none; stroke: transparent; stroke-width: 1.5; }
  & .nl { font: 560 10px var(--dlo-docket-sans); fill: var(--dlo-docket-mute); pointer-events: none; }
}
.dlo-docket__chains:has(.node:hover) .arc { opacity: .18; }
.dlo-docket__chains .dlo-docket__chainsvg .arc.is-lit { opacity: 1; stroke-width: 2.2; }
.dlo-docket.is-enter-chains .dlo-docket__chainsvg .arc { stroke-dasharray: 1; stroke-dashoffset: 1; animation: dlo-docket-draw .9s var(--dlo-docket-out) forwards; animation-delay: calc(var(--i) * 35ms + 150ms); }
.dlo-docket.is-enter-chains .dlo-docket__chainsvg .node { animation: dlo-docket-fade .5s var(--dlo-docket-out) both; animation-delay: calc(var(--i) * 25ms); }

/* ---------- drawer */
.dlo-docket__drawer {
  position: absolute; z-index: 5; inset: 10px 10px 10px auto; width: min(372px, calc(100% - 20px));
  display: flex; flex-direction: column;
  background: var(--dlo-docket-card); border-radius: 12px;
  box-shadow: 0 0 0 1px var(--dlo-docket-line), 0 24px 60px -18px color-mix(in oklch, var(--dlo-docket-ink) 40%, transparent);
  transform: translateX(calc(100% + 24px)); opacity: 0;
  transition: transform .5s var(--dlo-docket-out), opacity .3s, visibility 0s .5s; visibility: hidden;
  &[data-open] { transform: none; opacity: 1; visibility: visible; transition: transform .5s var(--dlo-docket-out), opacity .2s, visibility 0s; }
}
.dlo-docket__dbody {
  --c: var(--dlo-docket-m0);
  flex: 1; min-height: 0; overflow: auto; overscroll-behavior: contain; scrollbar-width: thin;
  padding: 16px 18px 18px;
  display: grid; align-content: start; gap: 14px;
}
.dlo-docket__dtop { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 10px; align-items: start; }
.dlo-docket__dmatter { font-size: 11.5px; font-weight: 600; color: color-mix(in oklab, var(--c) 70%, var(--dlo-docket-ink)); display: flex; gap: 6px; align-items: center; & i { width: 8px; height: 8px; border-radius: 50%; background: var(--c); flex: none; } }
.dlo-docket__dtitle { font-family: ui-serif, "New York", Georgia, serif; font-size: 20px; font-weight: 600; letter-spacing: -.015em; line-height: 1.15; text-wrap: balance; margin-top: 4px; }
.dlo-docket__x {
  display: grid; place-items: center; width: 30px; height: 30px; border-radius: 8px; color: var(--dlo-docket-mute);
  &:hover { background: var(--dlo-docket-wash); color: var(--dlo-docket-ink); }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; }
}
.dlo-docket__when {
