  & svg { width: 18px; height: 18px; margin: 0 auto; fill: none; stroke: currentColor; stroke-width: 2.4; stroke-linecap: round; stroke-linejoin: round; }
}
.dlo-docket__drawer[data-open] .dlo-docket__ring { --dlo-docket-ring: var(--p); }
