    display: grid; place-items: center; gap: 1px; padding: 5px 0 4px; border-radius: 6px;
    font: 600 11px var(--dlo-docket-mono); font-variant-numeric: tabular-nums; background: var(--dlo-docket-wash); color: var(--dlo-docket-mute);
