  if (step) {
    const s = +step.dataset.step;
    if (s === 0) {
      state.y = 2026; state.m = 9; renderHead(); renderMonth();
      const c = $(`[data-t="${TODAY}"]`, grid);
      if (c) { c.classList.remove('is-flash'); void c.offsetWidth; c.classList.add('is-flash'); }
    } else {
      state.m += s;
      if (state.m < 0) { state.m = 11; state.y--; } else if (state.m > 11) { state.m = 0; state.y++; }
      renderHead(); renderMonth();
      if (!reduce.matches) grid.animate([{ opacity: 0, transform: `translateX(${s * 14}px)` }, { opacity: 1, transform: 'none' }], { duration: 380, easing: 'cubic-bezier(.19,1,.22,1)' });
    }
    return;
  }
  const chip = t.closest('.' + P + '__chip');
  if (chip) { openDrawer(chip.dataset.id, chip); return; }
  const more = t.closest('.' + P + '__more');
  if (more) {
    const day = +more.dataset.day;
    const first = visible().find((e) => e.at === day);
    if (first) state.sel = first.id;
    setView('agenda');
    const o = first && $(`[data-id="${first.id}"]`, alist);
    if (o) { o.scrollIntoView({ block: 'center' }); o.focus({ preventScroll: true }); }
    return;
  }
  const opt = t.closest('[role=option]');
  if (opt) { openDrawer(opt.dataset.id, opt); return; }
  const node = t.closest('.node');
  if (node) { openDrawer(node.dataset.id, node); return; }
  const wk = t.closest('.wk');
  if (wk) { goWeek(+wk.dataset.w); return; }
  if (t.closest('.' + P + '__x')) { closeDrawer(); return; }
  const go = t.closest('[data-go]');
  if (go) { openDrawer(go.dataset.go); return; }
  const sh = t.closest('[data-shift]');
  if (sh) { shift(+sh.dataset.shift); return; }
  if (t.closest('[data-act=file]')) {
    const e = BY[state.open]; e.done = !e.done;
    render(); renderMatters(); renderDrawer();
    toast(e.done ? `Marked filed · ${e.s}` : `Reopened · ${e.s}`);
    const a = $('[data-act=file]', dbody); if (a) a.focus({ preventScroll: true });
  }
});
function goWeek(w) {
  const mid = new Date(w + 3 * DAY);
  closeDrawer();
  state.y = mid.getUTCFullYear(); state.m = mid.getUTCMonth();
  if (state.view !== 'month') setView('month'); else render({ skipLoad: true });
  for (let k = 0; k < 7; k++) {
    const c = $(`[data-t="${w + k * DAY}"]`, grid);
    if (c) { c.classList.remove('is-flash'); void c.offsetWidth; c.style.animationDelay = k * 40 + 'ms'; c.classList.add('is-flash'); }
  }
}
root.addEventListener('change', (ev) => {
  const t = ev.target;
  if (t.dataset.m !== undefined) {
    const m = +t.dataset.m;
    if (t.checked) state.off.delete(m); else state.off.add(m);
  } else if (t.dataset.kind) {
    const k = t.dataset.kind === 'hearing' ? 'event' : 'deadline';
    if (t.checked) state.kinds.add(k); else state.kinds.delete(k);
  } else return;
  if (state.open && !visible().some((e) => e.id === state.open)) closeDrawer();
  flip(() => render());
});

/* keyboard: chips move by entry (←/→) or by week (↑/↓); the agenda is a listbox */
root.addEventListener('keydown', (ev) => {
  if (ev.key === 'Escape' && state.open) { ev.preventDefault(); closeDrawer(); return; }
  const chip = ev.target.closest && ev.target.closest('.' + P + '__chip, .' + P + '__more');
  if (chip && grid.contains(chip) && /^Arrow|^Home$|^End$/.test(ev.key)) {
    const all = $$('.' + P + '__chip, .' + P + '__more', grid);
    const i = all.indexOf(chip);
    let n = i;
    const at = +chip.closest('[data-t]').dataset.t;
    if (ev.key === 'ArrowRight') n = Math.min(all.length - 1, i + 1);
    else if (ev.key === 'ArrowLeft') n = Math.max(0, i - 1);
    else if (ev.key === 'Home') n = 0;
    else if (ev.key === 'End') n = all.length - 1;
    else {
      const target = at + (ev.key === 'ArrowDown' ? 7 : -7) * DAY;
      const list = all.map((b, k) => [k, +b.closest('[data-t]').dataset.t]);
      const hit = ev.key === 'ArrowDown' ? list.find(([, t]) => t >= target) : list.filter(([, t]) => t <= target).pop();
      if (hit) n = hit[0];
    }
    if (n !== i) { ev.preventDefault(); all.forEach((b) => { b.tabIndex = -1; }); all[n].tabIndex = 0; all[n].focus(); }
    return;
  }
  const opt = ev.target.closest && ev.target.closest('[role=option]');
  if (opt) {
    const all = $$('[role=option]', alist), i = all.indexOf(opt);
    let n = i;
    if (ev.key === 'ArrowDown') n = Math.min(all.length - 1, i + 1);
    else if (ev.key === 'ArrowUp') n = Math.max(0, i - 1);
    else if (ev.key === 'Home') n = 0;
    else if (ev.key === 'End') n = all.length - 1;
    else if (ev.key === 'Enter' || ev.key === ' ') { ev.preventDefault(); openDrawer(opt.dataset.id, opt); return; }
    else return;
    ev.preventDefault();
    all.forEach((o) => { o.tabIndex = -1; o.setAttribute('aria-selected', 'false'); });
    all[n].tabIndex = 0; all[n].setAttribute('aria-selected', 'true'); state.sel = all[n].dataset.id;
    all[n].focus();
    return;
  }
  const g = ev.target.closest && ev.target.closest('.node, .wk');
  if (g && (ev.key === 'Enter' || ev.key === ' ')) { ev.preventDefault(); g.dispatchEvent(new MouseEvent('click', { bubbles: true })); }
});

/* tooltips */
function tipFor(el) {
  if (el.classList.contains('wk')) {
    const w = +el.dataset.w, vis = visible();
    const rows = MATTERS.map((m, i) => [m.short, vis.filter((e) => e.m === i && e.at >= w && e.at < w + 7 * DAY).length]).filter((r) => r[1]);
    const tot = rows.reduce((a, r) => a + r[1], 0);
    return `<b>Week of ${dm(w)}</b><small>${tot} entr${tot === 1 ? 'y' : 'ies'}</small>` + rows.map((r) => `<small>${esc(r[0])} · ${r[1]}</small>`).join('');
  }
  return entryTip(BY[el.dataset.id]);
}
root.addEventListener('pointerover', (ev) => {
  const el = ev.target.closest && ev.target.closest('.node');
  if (el) $$(`.arc[data-a="${el.dataset.id}"], .arc[data-b="${el.dataset.id}"]`, chainSvg).forEach((a) => a.classList.add('is-lit'));
});
root.addEventListener('pointermove', (ev) => {
  const el = ev.target.closest && ev.target.closest('.' + P + '__chip, .node, .wk');
  if (el) showTip(tipFor(el), ev.clientX, ev.clientY); else hideTip();
});
root.addEventListener('pointerout', (ev) => {
  const el = ev.target.closest && ev.target.closest('.' + P + '__chip, .node, .wk');
  if (el && !el.contains(ev.relatedTarget)) { hideTip(); $$('.arc.is-lit', chainSvg).forEach((a) => a.classList.remove('is-lit')); }
});

/* ---------- mount */
renderMatters();
if (!reduce.matches) root.classList.add('is-enter');
render();
setTimeout(() => root.classList.remove('is-enter'), 1600);

let raf = 0, lastW = root.clientWidth, lastH = root.clientHeight;
const ro = new ResizeObserver(() => {
  cancelAnimationFrame(raf);
  raf = requestAnimationFrame(() => {
    if (!root.isConnected) { ro.disconnect(); return; }
    const w = root.clientWidth, h = root.clientHeight;
    if (w === lastW && h === lastH) return;
    lastW = w; lastH = h;
    render();
  });
});
ro.observe(root);

css:
@property --dlo-spend-fill {
  syntax: "<percentage>";
  inherits: false;
  initial-value: 0%;
}

.dlo-spend {
  /* re-theme with these four */
  --dlo-spend-bg: oklch(0.205 0.013 62);
  --dlo-spend-ink: oklch(0.94 0.014 82);
  --dlo-spend-mint: oklch(0.82 0.105 168);
  --dlo-spend-coral: oklch(0.72 0.145 32);
  /* derived */
  --dlo-spend-sand: color-mix(in oklab, var(--dlo-spend-ink) 72%, oklch(0.75 0.09 80));
  --dlo-spend-side: color-mix(in oklch, var(--dlo-spend-bg) 84%, black);
  --dlo-spend-panel: color-mix(in oklch, var(--dlo-spend-bg) 94%, var(--dlo-spend-ink));
  --dlo-spend-raise: color-mix(in oklch, var(--dlo-spend-bg) 88%, var(--dlo-spend-ink));
  --dlo-spend-line: color-mix(in oklch, var(--dlo-spend-ink) 11%, transparent);
  --dlo-spend-soft: color-mix(in oklch, var(--dlo-spend-ink) 6%, transparent);
  --dlo-spend-mute: color-mix(in oklch, var(--dlo-spend-ink) 64%, var(--dlo-spend-bg));
  --dlo-spend-faint: color-mix(in oklch, var(--dlo-spend-ink) 42%, var(--dlo-spend-bg));
  --dlo-spend-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dlo-spend-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dlo-spend-out: cubic-bezier(.16, 1, .3, 1);
  --dlo-spend-spring: linear(0, 0.013, 0.05 2.4%, 0.21 5.3%, 0.744 14.4%, 0.931 18.9%, 1.035 23.6%, 1.071 27.4%, 1.075 31%, 1.054 36.4%, 1.006 46.5%, 0.993 52.6%, 0.996 63.7%, 1);

  width: 100%;
  height: var(--dlo-spend-h, 680px);
  container-type: inline-size; container-name: dlo-spend;
  position: relative; isolation: isolate; overflow: hidden;
  border-radius: 16px;
  background: var(--dlo-spend-bg); color: var(--dlo-spend-ink);
  font: 13px/1.45 var(--dlo-spend-sans);
  accent-color: var(--dlo-spend-mint);
  color-scheme: dark;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, h4, p, dl, dd, ul, table) { margin: 0; padding: 0; }
  & :where(ul) { list-style: none; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
  & :where(svg) { display: block; }
  & :focus-visible { outline: 2px solid var(--dlo-spend-mint); outline-offset: 2px; border-radius: 6px; }
  & .dlo-spend__scroll {
    overflow: auto; overscroll-behavior: contain;
    scrollbar-width: thin; scrollbar-color: color-mix(in oklch, var(--dlo-spend-ink) 20%, transparent) transparent;
  }
}

.dlo-spend__shell { height: 100%; display: grid; grid-template-columns: 208px minmax(0, 1fr); grid-template-areas: "side main"; }

/* ---------- side */
.dlo-spend__side {
  grid-area: side; min-height: 0; display: flex; flex-direction: column; gap: 20px;
  padding: 18px 12px 14px; background: var(--dlo-spend-side); border-right: 1px solid var(--dlo-spend-line);
  overflow: auto; scrollbar-width: none;
}
.dlo-spend__brand {
  display: flex; align-items: center; gap: 10px; padding: 0 6px;
  & svg { width: 32px; height: 32px; flex: none; padding: 6px; border-radius: 9px; background: var(--dlo-spend-mint); fill: none; stroke: var(--dlo-spend-bg); stroke-width: 2; stroke-linecap: round; }
  & b { display: block; font-size: 14px; font-weight: 720; letter-spacing: -.015em; line-height: 1.15; }
  & small { display: block; font-size: 11px; color: var(--dlo-spend-mute); }
}
.dlo-spend__nav {
  display: grid; gap: 2px;
  & button { position: relative; display: flex; align-items: center; gap: 10px; padding: 8px 10px; border-radius: 9px; color: var(--dlo-spend-mute); font-weight: 560; transition: background-color .2s, color .2s; }
  & button:hover { background: var(--dlo-spend-soft); color: var(--dlo-spend-ink); }
  & button[aria-current=page] { background: var(--dlo-spend-panel); color: var(--dlo-spend-ink); box-shadow: inset 0 0 0 1px var(--dlo-spend-line); }
  & button[aria-current=page]::before { content: ""; position: absolute; left: -12px; top: 9px; bottom: 9px; width: 3px; border-radius: 0 3px 3px 0; background: var(--dlo-spend-mint); }
  & svg { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  & span { flex: 1; }
}
.dlo-spend__badge { font: 650 10.5px var(--dlo-spend-mono); font-style: normal; padding: 1px 6px; border-radius: 99px; background: color-mix(in oklch, var(--dlo-spend-coral) 22%, transparent); color: var(--dlo-spend-coral); font-variant-numeric: tabular-nums; }
.dlo-spend__badge:empty { display: none; }
.dlo-spend__prac {
  display: flex; flex-wrap: wrap; gap: 5px; padding: 0 4px;
  & p { width: 100%; font-size: 10.5px; font-weight: 650; letter-spacing: .09em; text-transform: uppercase; color: var(--dlo-spend-faint); margin-bottom: 3px; }
  & button {
    display: inline-flex; align-items: center; gap: 6px; padding: 4px 9px 4px 7px; border-radius: 99px;
    font-size: 12px; font-weight: 560; color: var(--dlo-spend-mute); box-shadow: inset 0 0 0 1px var(--dlo-spend-line);
    transition: background-color .2s, color .2s, box-shadow .2s;
  }
  & button i { width: 7px; height: 7px; border-radius: 50%; background: var(--dlo-spend-faint); transition: background-color .2s, transform .3s var(--dlo-spend-spring); }
  & button:hover { color: var(--dlo-spend-ink); }
  & button[aria-pressed=true] { background: color-mix(in oklch, var(--dlo-spend-mint) 13%, transparent); color: var(--dlo-spend-ink); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dlo-spend-mint) 40%, transparent); }
  & button[aria-pressed=true] i { background: var(--dlo-spend-mint); transform: scale(1.15); }
  & button[aria-disabled=true] { cursor: not-allowed; }
}
.dlo-spend__foot { margin-top: auto; padding: 0 6px; font-size: 11px; line-height: 1.5; color: var(--dlo-spend-faint); text-wrap: pretty; }

/* ---------- main */
.dlo-spend__main { grid-area: main; min-width: 0; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); }
.dlo-spend__head {
  display: flex; align-items: flex-end; justify-content: space-between; gap: 16px; padding: 16px 20px 12px;
  & h2 { font-size: clamp(19px, 2.2cqi, 24px); font-weight: 680; letter-spacing: -.022em; line-height: 1.1; text-wrap: balance; }
}
.dlo-spend__eyebrow { font-size: 11px; font-weight: 600; letter-spacing: .07em; text-transform: uppercase; color: var(--dlo-spend-mint); margin-bottom: 3px; }
.dlo-spend__asof {
  display: grid; grid-template-columns: auto 160px; grid-template-rows: auto auto; column-gap: 12px; align-items: center;
  padding: 6px 12px 4px; border-radius: 10px; background: var(--dlo-spend-panel); box-shadow: inset 0 0 0 1px var(--dlo-spend-line);
  & > span { grid-row: span 2; font-size: 12px; color: var(--dlo-spend-mute); }
  & b { display: block; font: 650 15px var(--dlo-spend-mono); color: var(--dlo-spend-ink); min-width: 3.2ch; }
  & input { width: 100%; margin: 0; cursor: ew-resize; }
  & small { display: flex; justify-content: space-between; font: 500 9.5px var(--dlo-spend-mono); color: var(--dlo-spend-faint); & i { font-style: normal; } }
}
.dlo-spend__asof[hidden] { display: none; }
.dlo-spend__views { position: relative; min-height: 0; }
.dlo-spend__view { height: 100%; min-height: 0; }
.dlo-spend__view[hidden] { display: none; }

/* ---------- overview */
.dlo-spend__ov {
  display: grid; gap: 12px; padding: 0 20px 18px;
  grid-template-columns: minmax(0, 1fr) minmax(250px, 300px);
  grid-template-rows: auto minmax(0, 1fr);
  grid-template-areas: "kpis kpis" "chart rank";
}
.dlo-spend__kpis {
  grid-area: kpis; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 1px;
  border-radius: 12px; overflow: hidden; background: var(--dlo-spend-line); box-shadow: 0 0 0 1px var(--dlo-spend-line);
  & > div { padding: 11px 14px 12px; background: var(--dlo-spend-panel); min-width: 0; }
  & dt { font-size: 11px; font-weight: 600; color: var(--dlo-spend-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & dd { font-size: clamp(18px, 2.3cqi, 25px); font-weight: 680; letter-spacing: -.025em; font-variant-numeric: tabular-nums; line-height: 1.2; margin-top: 2px; }
  & small { display: block; font-size: 11.5px; color: var(--dlo-spend-faint); font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .up { color: var(--dlo-spend-coral); }
  & .dn { color: var(--dlo-spend-mint); }
}
.dlo-spend__chartcard {
  grid-area: chart; min-width: 0; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr) auto;
  padding: 12px 14px 10px; border-radius: 12px; background: var(--dlo-spend-panel); box-shadow: inset 0 0 0 1px var(--dlo-spend-line);
}
.dlo-spend__ch {
  display: flex; align-items: center; justify-content: space-between; gap: 10px;
  & h3 { font-size: 13px; font-weight: 650; letter-spacing: -.005em; min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
}
.dlo-spend__seg {
  display: flex; gap: 2px; padding: 2px; border-radius: 8px; background: var(--dlo-spend-soft); flex: none;
  & button { padding: 3px 10px; border-radius: 6px; font-size: 11.5px; font-weight: 600; color: var(--dlo-spend-mute); transition: background-color .2s, color .2s; }
  & button:hover { color: var(--dlo-spend-ink); }
  & button[aria-checked=true] { background: var(--dlo-spend-raise); color: var(--dlo-spend-ink); box-shadow: 0 1px 2px black; }
}
.dlo-spend__canvaswrap { position: relative; min-height: 180px; margin: 6px -4px 0; }
.dlo-spend__canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; cursor: crosshair; border-radius: 6px; }
.dlo-spend__legend {
  display: flex; flex-wrap: wrap; gap: 4px 16px; font-size: 11px; color: var(--dlo-spend-mute); padding-top: 6px;
  & span { display: inline-flex; align-items: center; gap: 6px; }
  & span::before { content: ""; width: 16px; height: 0; border-top: 2px solid; }
  & .a::before { border-color: var(--dlo-spend-mint); }
  & .b::before { border-top: 2px dashed var(--dlo-spend-sand); }
  & .f::before { border-top: 2px dotted var(--dlo-spend-mint); }
  & .c::before { height: 9px; border: 0; border-radius: 2px; background: color-mix(in oklch, var(--dlo-spend-mint) 22%, transparent); }
}

.dlo-spend__rank {
  grid-area: rank; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr);
  border-radius: 12px; background: var(--dlo-spend-panel); box-shadow: inset 0 0 0 1px var(--dlo-spend-line); overflow: hidden;
}
.dlo-spend__rh { padding: 12px 14px 8px; & h3 { font-size: 13px; font-weight: 650; } }
.dlo-spend__flist { padding: 0 6px 8px; display: grid; align-content: start; gap: 1px; }
.dlo-spend__fopt {
  --p: 0%;
  display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 5px 10px; padding: 8px 9px; border-radius: 9px; cursor: pointer;
  transition: background-color .2s;
  &:hover { background: var(--dlo-spend-soft); }
  &[aria-selected=true] { background: var(--dlo-spend-raise); box-shadow: inset 0 0 0 1px var(--dlo-spend-line), inset 3px 0 0 var(--dlo-spend-mint); }
  & b { font-size: 12.5px; font-weight: 620; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & b small { font-weight: 500; color: var(--dlo-spend-faint); font-size: 11px; margin-left: 4px; }
  & .v { font: 600 11.5px var(--dlo-spend-mono); font-variant-numeric: tabular-nums; }
  & .v.up { color: var(--dlo-spend-coral); }
  & .v.dn { color: var(--dlo-spend-mint); }
  &.is-all b { font-weight: 700; }
}
.dlo-spend__bullet {
  grid-column: 1 / -1; position: relative; height: 8px; border-radius: 4px; background: var(--dlo-spend-soft);
  & .bar {
    --dlo-spend-fill: var(--v);
    position: absolute; left: 0; top: 1px; bottom: 1px; width: var(--dlo-spend-fill); max-width: 100%; border-radius: 3px; background: var(--dlo-spend-mint);
    transition: --dlo-spend-fill .9s var(--dlo-spend-out);
    @starting-style { --dlo-spend-fill: 0%; }
  }
  & .bar.over { background: linear-gradient(90deg, var(--dlo-spend-mint) var(--split), var(--dlo-spend-coral) var(--split)); }
  & .tgt { position: absolute; top: -3px; bottom: -3px; width: 2px; border-radius: 1px; background: var(--dlo-spend-sand); left: var(--t); transition: left .6s var(--dlo-spend-out); }
}
@supports (animation-timeline: view()) {
  .dlo-spend__fopt { animation: dlo-spend-rise linear both; animation-timeline: view(); animation-range: entry 0% entry 80%; }
}

/* ---------- firms table */
.dlo-spend__firms { padding: 0 20px 18px; }
.dlo-spend__table {
  width: 100%; border-collapse: separate; border-spacing: 0; font-variant-numeric: tabular-nums;
  & th { position: sticky; top: 0; z-index: 1; background: var(--dlo-spend-bg); text-align: right; font-size: 11px; font-weight: 600; color: var(--dlo-spend-mute); padding: 0; border-bottom: 1px solid var(--dlo-spend-line); white-space: nowrap; }
  & th:first-child, & td:first-child { text-align: left; }
  & th button, & th > span { display: inline-flex; align-items: center; gap: 4px; padding: 10px 8px 8px; border-radius: 6px; }
  & th button:hover { color: var(--dlo-spend-ink); }
  & th button::after { content: ""; width: 7px; height: 7px; opacity: 0; border: solid currentColor; border-width: 0 1.5px 1.5px 0; transform: rotate(45deg) translateY(-2px); transition: transform .3s var(--dlo-spend-spring), opacity .2s; }
  & th[aria-sort=descending] button, & th[aria-sort=ascending] button { color: var(--dlo-spend-ink); }
  & th[aria-sort=descending] button::after { opacity: 1; }
  & th[aria-sort=ascending] button::after { opacity: 1; transform: rotate(-135deg) translateY(-2px); }
  & td { padding: 10px 8px; text-align: right; border-bottom: 1px solid var(--dlo-spend-soft); font-size: 12.5px; white-space: nowrap; }
  & tbody tr { cursor: pointer; transition: background-color .18s; }
  & tbody tr:hover { background: var(--dlo-spend-soft); }
