  & td small { display: block; color: var(--dlo-spend-faint); font-size: 11px; }
  & .up { color: var(--dlo-spend-coral); }
  & .dn { color: var(--dlo-spend-mint); }
  & tfoot td { font-weight: 700; border-bottom: 0; border-top: 1px solid var(--dlo-spend-line); position: sticky; bottom: 0; background: var(--dlo-spend-bg); }
