}

/* ---------- invoices */
.dlo-spend__inv { display: grid; grid-template-rows: auto minmax(0, 1fr); gap: 12px; padding: 0 20px 18px; }
.dlo-spend__ikpis { grid-area: auto; grid-template-columns: repeat(3, minmax(0, 1fr)); max-width: 980px; }
.dlo-spend__ilist { display: grid; align-content: start; gap: 6px; max-width: 980px; padding-bottom: 4px; }
.dlo-spend__invc {
