const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => Array.from(el.querySelectorAll(s));
const reduce = matchMedia('(prefers-reduced-motion: reduce)');
const P = 'dlo-spend';

/* ---------- data: FY2026, actuals Jan-Sep. Budgets in $k, phased by one seasonality curve */
const MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const PHASE = [0.07, 0.075, 0.085, 0.085, 0.08, 0.085, 0.08, 0.075, 0.09, 0.09, 0.09, 0.095];
const PRAC = { lit: 'Litigation', ip: 'IP', corp: 'Corporate', reg: 'Regulatory', emp: 'Employment' };
const FIRMS = [
  { id: 'at', name: 'Ashby Thorne LLP', prac: 'lit', rate: 985, budget: 3600, k: [0.95, 1.0, 1.05, 1.15, 1.25, 1.35, 1.5, 1.6, 1.7] },
  { id: 'pr', name: 'Pell Ranganathan LLP', prac: 'ip', rate: 1040, budget: 2400, k: [0.85, 0.8, 0.9, 0.85, 0.95, 0.9, 0.95, 1.0, 1.05] },
  { id: 'mc', name: 'Merriden & Cole', prac: 'corp', rate: 1120, budget: 2100, k: [0.6, 0.7, 0.9, 1.6, 1.9, 1.4, 0.6, 0.5, 0.7] },
  { id: 'sh', name: 'Strand Halley LLP', prac: 'reg', rate: 890, budget: 1500, k: [1.05, 1.1, 1.15, 1.2, 1.25, 1.2, 1.3, 1.35, 1.4] },
  { id: 'ov', name: 'Okonjo Varga LLP', prac: 'lit', rate: 760, budget: 1200, k: [0.7, 0.6, 0.75, 0.8, 0.7, 0.65, 0.8, 0.9, 0.85] },
  { id: 'wi', name: 'Whitcombe Ives', prac: 'emp', rate: 640, budget: 650, k: [1.0, 0.95, 1.05, 1.0, 0.9, 1.1, 1.0, 0.95, 1.05] },
  { id: 'bs', name: 'Brannock Sale LLP', prac: 'ip', rate: 920, budget: 900, k: [0.5, 0.6, 0.7, 0.6, 0.8, 0.7, 0.65, 0.75, 0.7] },
  { id: 'df', name: 'Delacroix Fenn', prac: 'corp', rate: 1010, budget: 750, k: [0.8, 0.9, 0.7, 0.8, 0.9, 1.0, 1.6, 2.4, 2.2] }
];
FIRMS.forEach((f) => {
  f.bud = PHASE.map((w) => Math.round(f.budget * w * 1000));
  f.act = f.k.map((k, i) => Math.round(f.bud[i] * k / 100) * 100);
});
const INV = [
  { id: 'AT-2609', firm: 'at', matter: 'Kestrel Pumps v. Larkfield', period: 'Sep', amt: 412380, flags: [['Block billing', '4 entries combine tasks', 18400], ['Over 12 hours in a day', '1 timekeeper, 14 Sep', 6250]] },
  { id: 'DF-0817', firm: 'df', matter: 'Acquisition of Corrin Diagnostics', period: 'Sep', amt: 268450, flags: [['Block billing', '2 entries', 9100], ['Rate above card', 'Partner $1,295 vs $1,180 card', 5480]] },
  { id: 'PR-0931', firm: 'pr', matter: 'Prosecution, LB-2207 patent family', period: 'Sep', amt: 186920, flags: [] },
  { id: 'SH-3302', firm: 'sh', matter: 'Clinical hold response', period: 'Sep', amt: 148750, flags: [['Vague descriptions', '“Review documents” ×9', 7820]] },
  { id: 'AT-2610', firm: 'at', matter: 'Larkfield adv. Vexley Labs (trade secrets)', period: 'Sep', amt: 131600, flags: [['Overstaffed deposition', '3 attorneys attended', 7350]] },
  { id: 'MC-7718', firm: 'mc', matter: 'Series C financing', period: 'Sep', amt: 95400, flags: [['Rate above card', 'Partner $1,295 vs $1,180 card', 3910]] },
  { id: 'OV-1145', firm: 'ov', matter: 'Distributor contract dispute', period: 'Sep', amt: 83200, flags: [['Travel at full rate', 'Card allows 50% for travel', 2640]] },
  { id: 'BS-2290', firm: 'bs', matter: 'Trademark oppositions, EU', period: 'Sep', amt: 57310, flags: [['Clerical work billed', 'Filing and copying, paralegal', 1960]] },
  { id: 'WI-0552', firm: 'wi', matter: 'Reduction-in-force advice', period: 'Sep', amt: 41880, flags: [] }
];
INV.forEach((v) => { v.status = 'pending'; v.cut = v.flags.reduce((a, f) => a + f[2], 0); });
const SAVED0 = 612300;
const FIRM = Object.fromEntries(FIRMS.map((f) => [f.id, f]));

/* ---------- formatting */
const sum = (a) => a.reduce((x, y) => x + y, 0);
const usd = (v) => '$' + Math.round(v).toLocaleString('en-US');
function short(v, d) {
  const a = Math.abs(v), s = v < 0 ? '−' : '';
  if (a >= 1e6) return s + '$' + (a / 1e6).toFixed(d == null ? 2 : d) + 'M';
  if (a >= 1e3) return s + '$' + Math.round(a / 1e3) + 'k';
  return s + '$' + Math.round(a);
}
const signed = (v) => (v > 0 ? '+' : v < 0 ? '−' : '') + short(Math.abs(v));
const pct = (v, d = 1) => (v > 0 ? '+' : v < 0 ? '−' : '') + Math.abs(v * 100).toFixed(d) + '%';
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

/* ---------- state */
const state = { view: 'overview', asof: 8, mode: 'cum', prac: new Set(Object.keys(PRAC)), focus: null, sort: 'spend', dir: -1, open: null, revised: new Set() };
const inScope = () => FIRMS.filter((f) => state.prac.has(f.prac));

/* Forecast for any set of firms as of month A: the trailing three-month run rate relative to
   plan, applied to the remaining phased budget; the band widens with monthly volatility. */
function model(firms, A) {
  const bud = PHASE.map((_, m) => sum(firms.map((f) => f.bud[m])));
  const act = PHASE.map((_, m) => (m <= 8 ? sum(firms.map((f) => f.act[m])) : 0));
  const ratios = act.slice(0, A + 1).map((a, i) => a / bud[i]);
  const mean = sum(ratios) / ratios.length;
  const sd = Math.sqrt(sum(ratios.map((r) => (r - mean) ** 2)) / Math.max(1, ratios.length - 1));
  const run = (act[A - 2] + act[A - 1] + act[A]) / (bud[A - 2] + bud[A - 1] + bud[A]);
  const cumBud = [], cumAct = [], proj = [], cumProj = [], lo = [], hi = [];
  let cb = 0, ca = 0, var2 = 0;
  for (let m = 0; m < 12; m++) {
    cb += bud[m]; cumBud.push(cb);
    if (m <= A) { ca += act[m]; cumAct.push(ca); proj.push(act[m]); cumProj.push(ca); lo.push(ca); hi.push(ca); }
    else {
      const p = bud[m] * run; proj.push(p);
      const prev = cumProj[m - 1] + p; cumProj.push(prev);
      var2 += (sd * bud[m]) ** 2;
      const half = 1.2816 * Math.sqrt(var2);
      lo.push(prev - half); hi.push(prev + half);
      cumAct.push(m <= 8 ? cumAct[m - 1] + act[m] : NaN);
    }
  }
  /* the real months after the as-of point, so a back-dated forecast can be checked */
  const later = act.map((a, m) => (m > A && m <= 8 ? a : NaN));
  const cumLater = []; let cl = cumAct[A];
  for (let m = 0; m < 12; m++) { if (m > A && m <= 8) { cl += act[m]; cumLater.push(cl); } else cumLater.push(m === A ? cl : NaN); }
  return { A, bud, act, cumBud, cumAct, proj, cumProj, lo, hi, run, sd, later, cumLater, landing: cumProj[11], fy: cumBud[11], ytd: cumAct[A], ytdBud: cumBud[A] };
}
const firmModel = (f) => model([f], state.asof);

/* ---------- elements */
const canvas = $('.' + P + '__canvas');
const wrap = $('.' + P + '__canvaswrap');
const ctx = canvas.getContext('2d');
const tip = $('.' + P + '__tip');
const toasts = $('.' + P + '__toasts');
const drawer = $('.' + P + '__drawer');
const dbody = $('.' + P + '__dbody');
const IC = {
  x: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 6l12 12M18 6 6 18"/></svg>',
  chev: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg>'
};

/* resolve theme colours once per draw: canvas needs concrete colours */
const probe = document.createElement('i');
probe.style.cssText = 'position:absolute;width:0;height:0;visibility:hidden';
root.append(probe);
function colour(v) { probe.style.color = `var(--${P}-${v})`; return getComputedStyle(probe).color; }

function toast(msg) {
  const t = document.createElement('div');
  t.className = P + '__toast'; t.textContent = msg;
  toasts.append(t);
  while (toasts.children.length > 3) toasts.firstChild.remove();
  setTimeout(() => { t.classList.add('is-out'); setTimeout(() => t.remove(), 350); }, 2600);
}
function placeTip(x, y) {
  const r = root.getBoundingClientRect(), w = tip.offsetWidth, h = tip.offsetHeight;
  let lx = x - r.left + 16, ly = y - r.top - h / 2;
  if (lx + w > r.width - 8) lx = x - r.left - w - 16;
  ly = Math.max(8, Math.min(r.height - h - 8, ly));
  tip.style.translate = lx + 'px ' + ly + 'px';
}

/* ---------- practice chips */
const pracBox = $('.' + P + '__prac');
pracBox.insertAdjacentHTML('beforeend', Object.entries(PRAC).map(([k, v]) => `<button type="button" data-prac="${k}" aria-pressed="true"><i></i>${v}</button>`).join(''));
function syncPrac() {
  $$('[data-prac]', pracBox).forEach((b) => {
    const on = state.prac.has(b.dataset.prac);
    b.setAttribute('aria-pressed', String(on));
    const last = on && state.prac.size === 1;
    if (last) { b.setAttribute('aria-disabled', 'true'); b.title = 'At least one practice area stays selected'; }
    else { b.removeAttribute('aria-disabled'); b.removeAttribute('title'); }
