/* ---------- KPIs */
function kpis() {
  const M = model(state.focus ? [state.focus] : inScope(), state.asof);
  const v = M.ytd - M.ytdBud, land = M.landing - M.fy;
  const band = [M.lo[11], M.hi[11]];
  const tiles = [
    ['Spend, Jan–' + MON[M.A], short(M.ytd), `${Math.round(M.ytd / M.fy * 100)}% of the FY budget used`],
    ['Phased budget to date', short(M.ytdBud), `<span class="${v > 0 ? 'up' : 'dn'}">${signed(v)} · ${pct(v / M.ytdBud)}</span> vs plan`],
    ['Projected FY landing', short(M.landing), `80% band ${short(band[0])} – ${short(band[1])}`],
    ['FY budget', short(M.fy), `<span class="${land > 0 ? 'up' : 'dn'}">${land > 0 ? 'Over' : 'Under'} by ${short(Math.abs(land))}</span> at ${M.run.toFixed(2)}× plan`]
  ];
  $('.' + P + '__ov .' + P + '__kpis').innerHTML = tiles.map((t, i) => `<div style="--i:${i}"><dt>${t[0]}</dt><dd>${t[1]}</dd><small>${t[2]}</small></div>`).join('');
}

/* ---------- firm ranking (listbox) */
function bullet(spend, bud) {
  const max = 1.4, f = Math.min(spend / bud, max) / max * 100, t = 1 / max * 100;
  const over = spend > bud;
  return `<span class="${P}__bullet" aria-hidden="true"><span class="bar${over ? ' over' : ''}" style="--v:${f.toFixed(1)}%;--split:${(bud / spend * 100).toFixed(1)}%"></span><span class="tgt" style="--t:${t.toFixed(1)}%"></span></span>`;
}
function renderRank() {
  const list = $('.' + P + '__flist');
  const firms = inScope().map((f) => ({ f, m: firmModel(f) })).sort((a, b) => (b.m.ytd / b.m.ytdBud) - (a.m.ytd / a.m.ytdBud));
  const all = model(inScope(), state.asof);
  const row = (id, name, sub, m, cls) => {
    const v = m.ytd - m.ytdBud;
    const sel = (state.focus ? state.focus.id : 'all') === id;
    return `<li class="${P}__fopt ${cls}" role="option" data-f="${id}" aria-selected="${sel}" tabindex="${sel ? 0 : -1}">` +
      `<b>${esc(name)}<small>${sub}</small></b><span class="v ${v > 0 ? 'up' : 'dn'}">${pct(v / m.ytdBud)}</span>${bullet(m.ytd, m.ytdBud)}</li>`;
  };
  list.innerHTML = row('all', 'All firms', inScope().length + ' firms', all, 'is-all') + firms.map(({ f, m }) => row(f.id, f.name, PRAC[f.prac], m, '')).join('');
}

/* ---------- canvas chart */
