  const C = pal || (pal = { ink: colour('ink'), mute: colour('mute'), faint: colour('faint'), line: colour('line'), mint: colour('mint'), coral: colour('coral'), sand: colour('sand'), bg: colour('panel') });
  const M = shown, narrow = w < 420;
  const padL = 46, padR = narrow ? 16 : 78, padT = 14, padB = 24;
  const { step, top } = nice(M.ymax);
  const X = (m) => padL + (m + 0.5) / 12 * (w - padL - padR);
  const Y = (v) => padT + (1 - v / top) * (h - padT - padB);
