      ctx.textAlign = 'left'; ctx.font = '650 11px ui-monospace, Menlo, monospace';
      ctx.fillStyle = over ? C.coral : C.mint; ctx.fillText(short(M.cumProj[11]), X(11) + 10, ly + 4 + sep);
      ctx.font = '500 9.5px system-ui, sans-serif'; ctx.fillStyle = C.mute; ctx.fillText('landing', X(11) + 10, ly + 15 + sep);
      ctx.font = '600 10.5px ui-monospace, Menlo, monospace'; ctx.fillStyle = C.sand; ctx.fillText(short(M.cumBud[11]), X(11) + 10, by + 4 - sep);
      ctx.font = '500 9.5px system-ui, sans-serif'; ctx.fillStyle = C.mute; ctx.fillText('budget', X(11) + 10, by + 15 - sep);
