function tipHTML(m) {
  const M = shown, rows = [];
  const fut = m > M.A;
  if (state.mode === 'cum') {
    rows.push([fut ? 'Forecast to date' : 'Spent to date', short(fut ? M.cumProj[m] : M.cumAct[m])]);
    rows.push(['Budget to date', short(M.cumBud[m])]);
    const v = (fut ? M.cumProj[m] : M.cumAct[m]) - M.cumBud[m];
    rows.push(['Variance', signed(v)]);
    if (fut) rows.push(['80% band', short(M.lo[m]) + '–' + short(M.hi[m])]);
    if (fut && !Number.isNaN(M.cumLater[m])) rows.push(['Actually spent', short(M.cumLater[m])]);
  } else {
    rows.push([fut ? 'Forecast' : 'Spent', usd(fut ? M.proj[m] : M.act[m])]);
    rows.push(['Budget', usd(M.bud[m])]);
    rows.push(['Variance', signed((fut ? M.proj[m] : M.act[m]) - M.bud[m])]);
    if (fut && !Number.isNaN(M.later[m])) rows.push(['Actually spent', usd(M.later[m])]);
  }
  return `<b>${MON[m]} 2026${fut ? ' · forecast' : ''}</b>` + rows.map((r) => `<div><span>${r[0]}</span><span>${r[1]}</span></div>`).join('');
}
function setHover(m, cx, cy) {
  hover = m; draw();
