  tip.innerHTML = tipHTML(m); tip.hidden = false; placeTip(cx, cy);
}
canvas.addEventListener('pointermove', (e) => {
  if (!geo) return;
  const r = canvas.getBoundingClientRect(), x = e.clientX - r.left;
  const m = Math.round((x - geo.padL) / (geo.w - geo.padL - geo.padR) * 12 - 0.5);
