canvas.addEventListener('blur', () => setHover(-1));
canvas.addEventListener('keydown', (e) => {
  if (!/^Arrow(Left|Right)$|^Home$|^End$|^Escape$/.test(e.key)) return;
  e.preventDefault();
  if (e.key === 'Escape') { setHover(-1); return; }
  let m = hover < 0 ? state.asof : hover;
  m = e.key === 'Home' ? 0 : e.key === 'End' ? 11 : Math.max(0, Math.min(11, m + (e.key === 'ArrowRight' ? 1 : -1)));
