  const max = Math.max(...M.bud, ...M.act.slice(0, 9), ...M.proj) * 1.1;
  const { step, top } = nice(max);
  const x = (m) => pl + m * (W - pl) / 12, bw = (W - pl) / 12;
  const y = (v) => pt + (1 - v / top) * (H - pt - pb);
  let s = '';
  for (let v = 0; v <= top + 1; v += step) s += `<line class="gl" x1="${pl}" x2="${W}" y1="${y(v)}" y2="${y(v)}"/><text class="ax" x="${pl - 5}" y="${y(v) + 3}" text-anchor="end">${v ? short(v, 1) : '$0'}</text>`;
  for (let m = 0; m < 12; m++) {
    const v = m <= M.A ? M.act[m] : M.proj[m];
    s += m <= M.A
      ? `<rect class="act${v > M.bud[m] ? ' over' : ''}" style="--i:${m}" x="${x(m) + bw * .18}" y="${y(v)}" width="${bw * .64}" height="${y(0) - y(v)}" rx="2"><title>${MON[m]}: ${usd(v)} vs ${usd(M.bud[m])} budget</title></rect>`
      : `<rect class="fc" x="${x(m) + bw * .18}" y="${y(v)}" width="${bw * .64}" height="${y(0) - y(v)}" rx="2"><title>${MON[m]} forecast: ${usd(v)}</title></rect>`;
    s += `<path class="bud" d="M${x(m) + bw * .08} ${y(M.bud[m])}h${bw * .84}"/>`;
    if (m % 2 === 0) s += `<text class="ax" x="${x(m) + bw / 2}" y="${H - 4}" text-anchor="middle">${MON[m]}</text>`;
  }
  return `<svg class="${P}__mbars" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(f.name)} monthly spend against budget">${s}</svg>`;
}
function renderDrawer() {
  const f = FIRM[state.open]; if (!f) return;
