  dbody.innerHTML =
    `<div class="${P}__dtop"><div><p>${PRAC[f.prac]} · $${f.rate.toLocaleString('en-US')}/h blended</p><h3 id="${P}-dt">${esc(f.name)}</h3></div><button type="button" class="${P}__x" aria-label="Close firm detail">${IC.x}</button></div>` +
    `<dl class="${P}__dstats"><div><dt>Spend YTD</dt><dd>${short(M.ytd)}</dd></div><div><dt>Budget YTD</dt><dd>${short(M.ytdBud)}</dd></div><div><dt>FY landing</dt><dd>${short(M.landing)}</dd></div></dl>` +
    monthBars(f) +
    `<p class="${P}__dnote">Running at <b>${M.run.toFixed(2)}× plan</b> over ${MON[M.A - 2]}–${MON[M.A]}. At that rate ${esc(f.name)} lands <b>${short(Math.abs(land))} ${land > 0 ? 'over' : 'under'}</b> its ${short(M.fy)} budget, about ${Math.round(M.ytd / f.rate).toLocaleString('en-US')} hours billed so far.</p>` +
    `<button type="button" class="${P}__dact" data-act="focus">Show on the burn-up</button>` +
    `<button type="button" class="${P}__dact is-ghost" data-act="revise" ${sent ? 'aria-disabled="true" title="A revision request is already with finance"' : ''}>${sent ? 'Revision requested · 6 Oct' : 'Request budget revision'}</button>`;
}
function openDrawer(id, from) {
