  drawer.setAttribute('data-open', ''); drawer.removeAttribute('inert'); drawer.setAttribute('aria-hidden', 'false');
  drawer.setAttribute('aria-labelledby', P + '-dt');
  $$('.' + P + '__table tbody tr').forEach((tr) => tr.setAttribute('aria-selected', String(tr.dataset.f === id)));
  $('.' + P + '__x', dbody).focus({ preventScroll: true });
}
function closeDrawer() {
  if (!state.open) return;
  state.open = null;
  drawer.removeAttribute('data-open'); drawer.setAttribute('inert', ''); drawer.setAttribute('aria-hidden', 'true');
  $$('.' + P + '__table tbody tr').forEach((tr) => tr.setAttribute('aria-selected', 'false'));
  if (lastFocus && lastFocus.isConnected) lastFocus.focus({ preventScroll: true });
  lastFocus = null;
}

/* ---------- invoices */
function renderInvoices(flipFrom) {
  const ul = $('.' + P + '__ilist');
  const before = new Map();
  if (flipFrom && !reduce.matches) $$('li', ul).forEach((li) => before.set(li.dataset.i, li.getBoundingClientRect().top));
  const order = INV.slice().sort((a, b) => (a.status === 'pending' ? 0 : 1) - (b.status === 'pending' ? 0 : 1));
  const openIds = new Set($$('[aria-expanded=true]', ul).map((b) => b.closest('li').dataset.i));
  if (flipFrom) openIds.delete(flipFrom);
  ul.innerHTML = order.map((v) => {
    const f = FIRM[v.firm], done = v.status !== 'pending', open = openIds.has(v.id);
    const chip = done ? `<span class="${P}__flag is-ok">${v.status === 'cut' ? 'Approved · −' + usd(v.cut) : v.status === 'ok' ? 'Approved' : 'Returned to firm'}</span>`
      : v.flags.length ? `<span class="${P}__flag">${v.flags.length} flag${v.flags.length > 1 ? 's' : ''} · ${usd(v.cut)}</span>` : `<span class="${P}__flag is-clean">Within guidelines</span>`;
    const amt = v.status === 'cut' ? `${usd(v.amt - v.cut)}<s>${usd(v.amt)}</s>` : usd(v.amt);
    const acts = done ? `<button type="button" data-inv="undo">Undo</button>`
      : (v.flags.length ? `<button type="button" class="pri" data-inv="cut">Approve with reductions · −${usd(v.cut)}</button><button type="button" data-inv="ok">Approve as billed</button>` : `<button type="button" class="pri" data-inv="ok">Approve</button>`) +
        `<button type="button" class="neg" data-inv="back">Return to firm</button>`;
    return `<li class="${P}__invc${done ? ' is-done' : ''}" data-i="${v.id}">` +
      `<button type="button" class="${P}__ihead" aria-expanded="${open}" aria-controls="${P}-b-${v.id}"><span><b>${esc(f.name)} · ${v.id}</b><small>${esc(v.matter)} · ${v.period} 2026</small></span>${chip}<span class="amt">${amt}</span>${IC.chev}</button>` +
      `<div class="${P}__ibody" id="${P}-b-${v.id}"><div><div class="${P}__iin">` +
      (v.flags.length ? `<ul class="${P}__lines">${v.flags.map((x) => `<li><span>${esc(x[0])}<small>${esc(x[1])}</small></span><span>−${usd(x[2])}</span></li>`).join('')}</ul>` : `<p class="${P}__dnote">Every entry is within the billing guidelines and rate card.</p>`) +
      `<div class="${P}__acts">${acts}</div></div></div></div></li>`;
  }).join('');
  const pend = INV.filter((v) => v.status === 'pending');
  const saved = SAVED0 + sum(INV.filter((v) => v.status === 'cut').map((v) => v.cut));
  $('.' + P + '__ikpis').innerHTML =
    `<div><dt>Awaiting review</dt><dd>${usd(sum(pend.map((v) => v.amt)))}</dd><small>${pend.length} invoice${pend.length === 1 ? '' : 's'} · September billing</small></div>` +
    `<div><dt>Flagged against guidelines</dt><dd class="up">${usd(sum(pend.map((v) => v.cut)))}</dd><small>${pend.filter((v) => v.flags.length).length} invoices with flags</small></div>` +
    `<div><dt>Saved by review, FY2026</dt><dd class="dn">${usd(saved)}</dd><small>${usd(SAVED0)} before this batch</small></div>`;
  $('[data-k=pendn]').textContent = pend.length ? String(pend.length) : '';
  if (before.size) $$('li', ul).forEach((li) => {
    const b = before.get(li.dataset.i); if (b == null) return;
    const dy = b - li.getBoundingClientRect().top;
    if (dy) li.animate([{ transform: `translateY(${dy}px)` }, { transform: 'none' }], { duration: 560, easing: 'cubic-bezier(.16,1,.3,1)' });
  });
}

/* ---------- render all */
function renderAll() {
  const focus = state.focus;
  pal = null;
  $('[data-k=eyebrow]').textContent = state.prac.size === 5 ? 'Outside counsel · all practices' : 'Outside counsel · ' + [...state.prac].map((k) => PRAC[k]).join(', ');
  $('[data-k=title]').textContent = state.view === 'invoices' ? 'Invoice review' : state.view === 'firms' ? 'Firms against budget' : 'Spend against budget';
  $('[data-k=charth]').textContent = (state.mode === 'cum' ? 'Cumulative spend · ' : 'Monthly spend · ') + (focus ? focus.name : 'all firms');
  $('[data-k=asof]').textContent = MON[state.asof];
  canvas.setAttribute('aria-label', `${state.mode === 'cum' ? 'Cumulative' : 'Monthly'} spend for ${focus ? focus.name : 'all firms in scope'} as of ${MON[state.asof]}. Arrow keys step through months.`);
  kpis(); renderRank(); setTarget();
  if (state.view === 'firms') renderTable();
}

/* ---------- events */
root.addEventListener('click', (e) => {
  const t = e.target;
  const nav = t.closest('.' + P + '__nav button');
  if (nav) {
    closeDrawer();
    state.view = nav.dataset.view;
    $$('.' + P + '__nav button').forEach((b) => (b === nav ? b.setAttribute('aria-current', 'page') : b.removeAttribute('aria-current')));
    $$('.' + P + '__view').forEach((v) => { v.hidden = v.dataset.view !== state.view; });
    $('.' + P + '__asof').hidden = state.view === 'invoices';
    renderAll();
    if (state.view === 'invoices') renderInvoices();
    if (state.view === 'overview') requestAnimationFrame(draw);
    return;
  }
  const pr = t.closest('[data-prac]');
  if (pr) {
    if (pr.getAttribute('aria-disabled') === 'true') { toast('Keep at least one practice area in view'); return; }
    const k = pr.dataset.prac;
    if (state.prac.has(k)) state.prac.delete(k); else state.prac.add(k);
    if (state.focus && !state.prac.has(state.focus.prac)) state.focus = null;
    syncPrac(); renderAll();
    return;
  }
  const mode = t.closest('[data-mode]');
  if (mode) {
    state.mode = mode.dataset.mode;
    $$('[data-mode]').forEach((b) => { const on = b === mode; b.setAttribute('aria-checked', String(on)); b.tabIndex = on ? 0 : -1; });
    shown = null; renderAll();
    return;
  }
  const opt = t.closest('.' + P + '__fopt');
  if (opt) { selectFocus(opt.dataset.f); return; }
  const sort = t.closest('[data-sort]');
  if (sort) {
    const k = sort.dataset.sort;
    if (state.sort === k) state.dir = -state.dir; else { state.sort = k; state.dir = k === 'name' ? 1 : -1; }
    renderTable(true);
    return;
  }
  const tr = t.closest('.' + P + '__table tbody tr');
  if (tr) { openDrawer(tr.dataset.f, tr); return; }
  if (t.closest('.' + P + '__x')) { closeDrawer(); return; }
  const act = t.closest('[data-act]');
  if (act) {
    const f = FIRM[state.open];
    if (act.dataset.act === 'focus') {
      closeDrawer();
      $('.' + P + '__nav [data-view=overview]').click();
      selectFocus(f.id);
    } else if (act.getAttribute('aria-disabled') === 'true') {
      toast('Already requested — finance replies within 3 business days');
    } else {
      state.revised.add(f.id); renderDrawer();
      toast(`Budget revision requested for ${f.name}`);
      const b = $('[data-act=revise]', dbody); if (b) b.focus({ preventScroll: true });
    }
    return;
  }
  const head = t.closest('.' + P + '__ihead');
  if (head) { head.setAttribute('aria-expanded', String(head.getAttribute('aria-expanded') !== 'true')); return; }
  const inv = t.closest('[data-inv]');
  if (inv) {
    const v = INV.find((x) => x.id === inv.closest('li').dataset.i);
    const was = v.status;
    v.status = inv.dataset.inv === 'undo' ? 'pending' : inv.dataset.inv;
    renderInvoices(v.id);
    const f = FIRM[v.firm];
    toast(v.status === 'cut' ? `${v.id} approved · ${usd(v.cut)} written off` : v.status === 'ok' ? `${v.id} approved as billed` : v.status === 'back' ? `${v.id} returned to ${f.name}` : `${v.id} back in the queue${was === 'cut' ? ', reductions reversed' : ''}`);
    const h = $(`[data-i="${v.id}"] .${P}__ihead`); if (h) h.focus({ preventScroll: true });
  }
});
function selectFocus(id) {
  state.focus = id === 'all' ? null : FIRM[id];
  renderAll();
  const o = $(`.${P}__fopt[data-f="${id}"]`); if (o) o.focus({ preventScroll: true });
}
root.addEventListener('input', (e) => {
  if (e.target.type !== 'range') return;
  state.asof = +e.target.value;
  renderAll();
});
root.addEventListener('keydown', (e) => {
  if (e.key === 'Escape' && state.open) { e.preventDefault(); closeDrawer(); return; }
  const opt = e.target.closest && e.target.closest('.' + P + '__fopt');
  if (opt) {
    const all = $$('.' + P + '__fopt'), i = all.indexOf(opt);
    let n = i;
    if (e.key === 'ArrowDown') n = Math.min(all.length - 1, i + 1);
    else if (e.key === 'ArrowUp') n = Math.max(0, i - 1);
    else if (e.key === 'Home') n = 0; else if (e.key === 'End') n = all.length - 1;
    else if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); selectFocus(opt.dataset.f); return; }
    else return;
    e.preventDefault(); all.forEach((o) => { o.tabIndex = -1; }); all[n].tabIndex = 0; all[n].focus();
    return;
  }
  const tr = e.target.closest && e.target.closest('.' + P + '__table tbody tr');
  if (tr) {
    const all = $$('.' + P + '__table tbody tr'), i = all.indexOf(tr);
    let n = i;
    if (e.key === 'ArrowDown') n = Math.min(all.length - 1, i + 1);
    else if (e.key === 'ArrowUp') n = Math.max(0, i - 1);
    else if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); openDrawer(tr.dataset.f, tr); return; }
    else return;
    e.preventDefault(); all.forEach((r) => { r.tabIndex = -1; }); all[n].tabIndex = 0; all[n].focus();
    return;
  }
  const seg = e.target.closest && e.target.closest('[data-mode]');
  if (seg && /^Arrow/.test(e.key)) {
    e.preventDefault();
    const other = $$('[data-mode]').find((b) => b !== seg);
    other.click(); other.focus();
  }
});

/* ---------- mount */
syncPrac();
renderAll();
renderInvoices();
if (!reduce.matches) {
  root.classList.add('is-enter');
  setTimeout(() => root.classList.remove('is-enter'), 1200);
  const t0 = performance.now();
  const grow = (now) => {
    if (!root.isConnected) return;
    if (!onScreen || document.hidden) { reveal = 1; draw(); return; }
    const k = Math.min(1, (now - t0) / 1300);
    reveal = 1 - Math.pow(1 - k, 4);
    draw();
    if (k < 1) requestAnimationFrame(grow);
  };
  requestAnimationFrame(grow);
}
const io = new IntersectionObserver((en) => { onScreen = en[0].isIntersecting; });
io.observe(root);
let rz = 0;
const ro = new ResizeObserver(() => {
  cancelAnimationFrame(rz);
  rz = requestAnimationFrame(() => {
    if (!root.isConnected) { ro.disconnect(); io.disconnect(); return; }
    draw();
  });
});
ro.observe(wrap);

css:
.dlo-hours {
  /* re-theme with these four */
  --dlo-hours-bg: oklch(0.975 0.005 235);
  --dlo-hours-ink: oklch(0.255 0.025 250);
  --dlo-hours-teal: oklch(0.47 0.085 196);
  --dlo-hours-rust: oklch(0.6 0.15 42);
  /* derived */
  --dlo-hours-card: color-mix(in oklch, var(--dlo-hours-bg) 30%, white);
  --dlo-hours-rail: color-mix(in oklab, var(--dlo-hours-ink) 92%, var(--dlo-hours-teal));
  --dlo-hours-line: color-mix(in oklch, var(--dlo-hours-ink) 11%, transparent);
  --dlo-hours-hair: color-mix(in oklch, var(--dlo-hours-ink) 6%, transparent);
  --dlo-hours-wash: color-mix(in oklch, var(--dlo-hours-ink) 4%, transparent);
  --dlo-hours-mute: color-mix(in oklch, var(--dlo-hours-ink) 62%, var(--dlo-hours-bg));
  --dlo-hours-faint: color-mix(in oklch, var(--dlo-hours-ink) 40%, var(--dlo-hours-bg));
  --dlo-hours-ochre: color-mix(in oklch, var(--dlo-hours-rust) 55%, oklch(0.8 0.13 85));
  --dlo-hours-l0: color-mix(in oklab, var(--dlo-hours-ochre) 80%, var(--dlo-hours-card));
  --dlo-hours-l1: color-mix(in oklch, var(--dlo-hours-ochre) 45%, var(--dlo-hours-rust));
  --dlo-hours-l2: var(--dlo-hours-rust);
  --dlo-hours-l3: color-mix(in oklab, var(--dlo-hours-rust) 70%, var(--dlo-hours-ink));
  --dlo-hours-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dlo-hours-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dlo-hours-out: cubic-bezier(.22, 1, .36, 1);
  --dlo-hours-spring: linear(0, 0.011, 0.045 2.3%, 0.183 5.1%, 0.695 13.6%, 0.904 18.4%, 1.012 22.8%, 1.06 26.6%, 1.073 30.2%, 1.062 34.4%, 1.012 44.6%, 0.995 51.4%, 0.996 64%, 1);

  width: 100%;
  height: var(--dlo-hours-h, 680px);
  container-type: inline-size; container-name: dlo-hours;
  position: relative; isolation: isolate; overflow: hidden;
  border-radius: 14px;
  background: var(--dlo-hours-bg); color: var(--dlo-hours-ink);
  font: 13px/1.45 var(--dlo-hours-sans);
  accent-color: var(--dlo-hours-teal);
  color-scheme: light;
  box-shadow: inset 0 0 0 1px var(--dlo-hours-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, p, dl, dd, ul, table) { margin: 0; padding: 0; }
  & :where(ul) { list-style: none; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
  & :where(svg) { display: block; }
  & :focus-visible { outline: 2px solid var(--dlo-hours-teal); outline-offset: 2px; border-radius: 6px; }
  & .dlo-hours__scroll {
    overflow: auto; overscroll-behavior: contain;
    scrollbar-width: thin; scrollbar-color: color-mix(in oklch, var(--dlo-hours-ink) 22%, transparent) transparent;
  }
}

.dlo-hours__shell { height: 100%; display: grid; grid-template-columns: 64px minmax(0, 1fr); grid-template-areas: "rail main"; }

/* ---------- rail */
.dlo-hours__rail {
  grid-area: rail; display: flex; flex-direction: column; align-items: center; gap: 6px; padding: 14px 0;
  background: var(--dlo-hours-rail); color: var(--dlo-hours-bg);
  & button {
    position: relative; display: grid; place-items: center; width: 42px; height: 42px; border-radius: 11px;
    color: color-mix(in oklch, var(--dlo-hours-bg) 60%, transparent); transition: background-color .2s, color .2s;
  }
  & button:hover { background: color-mix(in oklch, var(--dlo-hours-bg) 10%, transparent); color: var(--dlo-hours-bg); }
  & button[aria-current=page] { background: var(--dlo-hours-bg); color: var(--dlo-hours-ink); }
  & button::after {
    content: attr(data-tip); position: absolute; left: calc(100% + 10px); top: 50%; z-index: 6;
    padding: 4px 8px; border-radius: 6px; background: var(--dlo-hours-ink); color: var(--dlo-hours-bg);
    font-size: 11.5px; font-weight: 600; white-space: nowrap; pointer-events: none;
    opacity: 0; transform: translate(-4px, -50%); transition: opacity .15s, transform .25s var(--dlo-hours-out);
  }
  & button:hover::after, & button:focus-visible::after { opacity: 1; transform: translate(0, -50%); }
  & svg { width: 21px; height: 21px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
}
.dlo-hours__mark {
  display: grid; place-items: center; width: 38px; height: 38px; margin-bottom: 12px; border-radius: 50%;
  font: 700 12px var(--dlo-hours-sans); letter-spacing: .04em; color: var(--dlo-hours-rail); background: color-mix(in oklab, var(--dlo-hours-teal) 55%, var(--dlo-hours-bg));
}

/* ---------- main + header */
.dlo-hours__main { grid-area: main; min-width: 0; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); }
.dlo-hours__head {
  display: grid; grid-template-columns: minmax(0, 1fr) auto; grid-template-areas: "title ctrls" "groups groups"; gap: 10px 16px; align-items: end;
  padding: 16px 20px 12px;
}
.dlo-hours__title {
  grid-area: title; min-width: 0;
  & p { font-size: 11px; font-weight: 600; letter-spacing: .07em; text-transform: uppercase; color: var(--dlo-hours-teal); }
  & h2 { font-size: clamp(19px, 2.3cqi, 25px); font-weight: 700; letter-spacing: -.025em; line-height: 1.1; text-wrap: balance; }
}
.dlo-hours__ctrls { grid-area: ctrls; }
.dlo-hours__seg {
  display: flex; padding: 3px; gap: 2px; border-radius: 10px; background: var(--dlo-hours-wash); box-shadow: inset 0 0 0 1px var(--dlo-hours-hair);
  & button { min-width: 44px; padding: 5px 10px; border-radius: 7px; font: 600 12px var(--dlo-hours-mono); color: var(--dlo-hours-mute); text-align: center; transition: background-color .2s, color .2s, box-shadow .2s; }
  & button:hover { color: var(--dlo-hours-ink); }
  & button[aria-checked=true] { background: var(--dlo-hours-card); color: var(--dlo-hours-ink); box-shadow: 0 1px 3px var(--dlo-hours-line), 0 0 0 1px var(--dlo-hours-hair); }
}
.dlo-hours__groups {
  grid-area: groups; display: flex; flex-wrap: wrap; gap: 6px;
  & button {
    display: inline-flex; align-items: center; gap: 7px; padding: 5px 11px; border-radius: 99px; font-size: 12px; font-weight: 600;
    color: var(--dlo-hours-mute); background: var(--dlo-hours-card); box-shadow: inset 0 0 0 1px var(--dlo-hours-line);
    transition: background-color .2s, color .2s, box-shadow .2s;
  }
  & button:hover { color: var(--dlo-hours-ink); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dlo-hours-ink) 25%, transparent); }
  & button[aria-checked=true] { background: var(--dlo-hours-ink); color: var(--dlo-hours-bg); box-shadow: none; }
  & small { font: 600 10.5px var(--dlo-hours-mono); opacity: .7; font-variant-numeric: tabular-nums; }
}

.dlo-hours__views { position: relative; min-height: 0; }
.dlo-hours__view { height: 100%; min-height: 0; }
.dlo-hours__view[hidden] { display: none; }
.dlo-hours__card { border-radius: 12px; background: var(--dlo-hours-card); box-shadow: 0 0 0 1px var(--dlo-hours-line), 0 1px 2px var(--dlo-hours-hair); min-width: 0; min-height: 0; }
.dlo-hours__ch {
  display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 12px 16px 0;
  & h3 { font-size: 13px; font-weight: 680; letter-spacing: -.005em; text-wrap: balance; }
}
.dlo-hours__clear {
  display: inline-flex; align-items: center; gap: 6px; padding: 4px 10px; border-radius: 99px; font-size: 11.5px; font-weight: 650;
  background: color-mix(in oklch, var(--dlo-hours-teal) 12%, transparent); color: var(--dlo-hours-teal);
  &:hover { background: color-mix(in oklch, var(--dlo-hours-teal) 20%, transparent); }
  &::before { content: "←"; }
}
.dlo-hours__clear[hidden] { display: none; }

/* ---------- river view */
.dlo-hours__rv {
  display: grid; grid-template-rows: auto auto minmax(0, 1fr); gap: 10px; padding: 0 20px 16px;
}
.dlo-hours__kpis {
  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 10px;
  & > div { padding: 10px 14px; border-radius: 11px; background: var(--dlo-hours-card); box-shadow: 0 0 0 1px var(--dlo-hours-line); min-width: 0; }
  & dt { font-size: 11px; font-weight: 600; color: var(--dlo-hours-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & dd { display: flex; align-items: baseline; gap: 8px; font-size: clamp(18px, 2.2cqi, 24px); font-weight: 700; letter-spacing: -.03em; font-variant-numeric: tabular-nums; line-height: 1.2; }
  & dd small { font-size: 11.5px; font-weight: 600; letter-spacing: 0; color: var(--dlo-hours-faint); }
  & .bad { color: var(--dlo-hours-rust); }
  & .good { color: var(--dlo-hours-teal); }
}
.dlo-hours__riverwrap { padding: 4px 8px 6px; }
.dlo-hours__river {
  width: 100%; height: 252px; overflow: visible;
  & .rb { fill: none; stroke-linecap: butt; transition: opacity .25s, filter .25s; }
  & .rb.keep { stroke: var(--dlo-hours-teal); }
  & .rb.l0 { stroke: var(--dlo-hours-l0); }
  & .rb.l1 { stroke: var(--dlo-hours-l1); }
  & .rb.l2 { stroke: var(--dlo-hours-l2); }
  & .rb.l3 { stroke: var(--dlo-hours-l3); }
  & .seam { fill: none; stroke: var(--dlo-hours-card); stroke-width: 1; opacity: .7; pointer-events: none; }
  & .gate { stroke: var(--dlo-hours-card); stroke-width: 1.5; stroke-dasharray: 3 3; opacity: .9; }
  & .gl { font: 650 10.5px var(--dlo-hours-sans); letter-spacing: .07em; text-transform: uppercase; fill: var(--dlo-hours-mute); }
  & .gv { font: 700 15px var(--dlo-hours-sans); fill: var(--dlo-hours-ink); font-variant-numeric: tabular-nums; letter-spacing: -.02em; }
  & .gs { font: 500 11px var(--dlo-hours-mono); fill: var(--dlo-hours-faint); font-variant-numeric: tabular-nums; }
  & .gv.big { font-size: 22px; fill: var(--dlo-hours-teal); }
  & .sk { font: 600 11px var(--dlo-hours-sans); fill: var(--dlo-hours-ink); }
