const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => Array.from(el.querySelectorAll(s));
const reduce = matchMedia('(prefers-reduced-motion: reduce)');
const NS = 'http://www.w3.org/2000/svg';
const P = 'dlo-hours';

/* ---------- deterministic data: 16 timekeepers, 39 weeks (Q1-Q3 2026) */
let seed = 20260930;
const rnd = () => { seed |= 0; seed = (seed + 0x6D2B79F5) | 0; let t = Math.imul(seed ^ (seed >>> 15), 1 | seed); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
const GROUPS = { corp: ['Corporate', 196], lit: ['Litigation', 28], re: ['Real Estate', 120], emp: ['Employment', 300], ip: ['IP', 250] };
/* leak profile as a share of worked value: pre-bill write-off, discount, credit note, unpaid */
const LEAK = { corp: [0.04, 0.05, 0.01, 0.01], lit: [0.085, 0.03, 0.03, 0.02], re: [0.03, 0.08, 0.01, 0.005], emp: [0.05, 0.04, 0.02, 0.015], ip: [0.06, 0.02, 0.012, 0.01] };
const LEVEL = { P: ['Partner', 32, -0.012], C: ['Counsel', 34, 0], S: ['Senior associate', 36, 0.006], A: ['Associate', 38, 0.022], L: ['Paralegal', 30, 0.04] };
const TK = [
  ['Ingrid Halvorsen', 'P', 'corp', 1320, 1.04], ['Marcus Oyelaran', 'P', 'lit', 1280, 1.08], ['Teodora Vance', 'P', 're', 1180, 0.93], ['Callum Reyes', 'P', 'ip', 1240, 0.97],
  ['Priyanka Mehta', 'C', 'emp', 980, 1.02], ['Joachim Brandt', 'C', 'lit', 960, 0.9],
  ['Lena Fischer', 'S', 'corp', 840, 1.11], ['Daniel Achebe', 'S', 'lit', 820, 1.05], ['Sofia Marchetti', 'S', 'ip', 860, 0.95], ['Hugo Lambert', 'S', 're', 790, 0.86],
  ['Grace Nakamura', 'A', 'corp', 620, 1.07], ['Tomás Rivera', 'A', 'lit', 600, 0.99], ['Amara Diallo', 'A', 'emp', 610, 0.88], ['Owen Price', 'A', 'ip', 640, 0.92],
  ['Rosa Delgado', 'L', 'lit', 310, 1.0], ['Felix Hart', 'L', 'corp', 290, 0.84]
].map(([name, lv, g, rate, u], i) => {
  const target = LEVEL[lv][1];
  const vac = [0, 1, 2].map((q) => q * 13 + 2 + Math.floor(rnd() * 10));
  const h = Array.from({ length: 39 }, (_, w) => {
    let v = target * u * (1 + 0.2 * (rnd() - 0.5));
    if (w === 0) v *= 0.62;
    if (vac.includes(w)) v *= 0.22;
    return Math.round(v * 10) / 10;
  });
  const leak = [0, 1, 2].map(() => LEAK[g].map((b, k) => Math.max(0.002, b + (k === 0 ? LEVEL[lv][2] : 0) + 0.012 * (rnd() - 0.5))));
  return { i, name, lv, g, rate, target, h, leak, ini: name.split(' ').map((x) => x[0]).join('') };
});
const MATTERS = [
  ['m1', 'corp', 'Halden Biotech — Series B financing', 'Fixed-fee cap exceeded', 0.38], ['m2', 'corp', 'Mareva Foods — supply agreements', 'Over-staffed diligence', 0.24],
  ['m3', 'lit', 'Quarry Lane Homes v. Westmere Build', 'Budget overrun, client pushback', 0.36], ['m4', 'lit', 'Pemberton Freight — subpoena response', 'Junior training time', 0.26],
  ['m5', 're', 'Brindlecombe Estates — lease portfolio', 'Fixed-fee cap exceeded', 0.4], ['m6', 're', 'Ostler Retail Parks — title review', 'Duplicated review', 0.22],
  ['m7', 'emp', 'Corvid Telecom — restructuring advice', 'Courtesy discount', 0.33], ['m8', 'emp', 'Saltmarsh Hotels — tribunal claims', 'Budget overrun', 0.29],
  ['m9', 'ip', 'Fennick Audio — patent filings', 'Prosecution cap', 0.35], ['m10', 'ip', 'Lumen Grove — trademark watch', 'Non-chargeable research', 0.27]
].map(([id, g, name, why, w]) => ({ id, g, name, why, w, partner: TK.find((t) => t.g === g && t.lv === 'P') || TK.find((t) => t.g === g) }));
const QW = (q) => (q === 'ytd' ? [0, 39] : [q * 13, q * 13 + 13]);
const QN = (q) => (q === 'ytd' ? 'YTD' : 'Q' + (q + 1));
const DAY = 864e5, W0 = Date.UTC(2026, 0, 5);
const MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const wkLabel = (w) => { const d = new Date(W0 + w * 7 * DAY); return d.getUTCDate() + ' ' + MON[d.getUTCMonth()]; };

/* ---------- maths */
function tkStats(t, q) {
  const [a, b] = QW(q);
  let hours = 0, worked = 0;
  const L = [0, 0, 0, 0];
  for (let w = a; w < b; w++) {
    const v = t.h[w] * t.rate, lk = t.leak[Math.floor(w / 13)];
    hours += t.h[w]; worked += v;
    lk.forEach((r, k) => { L[k] += v * r; });
  }
  const billed = worked - L[0] - L[1], coll = billed - L[2] - L[3];
  return { hours, worked, L, billed, coll, util: hours / (t.target * (b - a)), real: coll / worked };
}
function scopeStats(list, q) {
  const s = { hours: 0, worked: 0, L: [0, 0, 0, 0], billed: 0, coll: 0, target: 0 };
  list.forEach((t) => {
    const x = tkStats(t, q), [a, b] = QW(q);
    s.hours += x.hours; s.worked += x.worked; s.billed += x.billed; s.coll += x.coll; s.target += t.target * (b - a);
    x.L.forEach((v, k) => { s.L[k] += v; });
  });
  s.util = s.hours / s.target; s.real = s.coll / s.worked;
  return s;
}

/* ---------- formatting */
const money = (v) => (Math.abs(v) >= 1e6 ? '$' + (v / 1e6).toFixed(2) + 'M' : '$' + Math.round(v / 1e3) + 'k');
const usd = (v) => '$' + Math.round(v).toLocaleString('en-US');
const pc = (v, d = 1) => (v * 100).toFixed(d) + '%';
const hrs = (v) => Math.round(v).toLocaleString('en-US') + '\u00a0h';
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const av = (t) => `oklch(0.52 0.075 ${GROUPS[t.g][1]})`;

/* ---------- state */
const state = { view: 'river', q: 2, g: 'all', tk: null, sort: 'real', dir: -1, wo: {} };
const people = () => TK.filter((t) => state.g === 'all' || t.g === state.g);
const scope = () => (state.tk ? [state.tk] : people());

const tip = $('.' + P + '__tip');
const toasts = $('.' + P + '__toasts');
function toast(msg) {
  const t = document.createElement('div');
  t.className = P + '__toast'; t.textContent = msg;
  toasts.append(t);
  while (toasts.children.length > 2) toasts.firstChild.remove();
  setTimeout(() => { t.classList.add('is-out'); setTimeout(() => t.remove(), 350); }, 2400);
}
function showTip(html, x, y) {
  tip.innerHTML = html; tip.hidden = false;
  const r = root.getBoundingClientRect(), w = tip.offsetWidth, h = tip.offsetHeight;
  let lx = x - r.left + 14, ly = y - r.top + 14;
  if (lx + w > r.width - 8) lx = x - r.left - w - 14;
  if (ly + h > r.height - 8) ly = y - r.top - h - 12;
  tip.style.translate = Math.max(8, lx) + 'px ' + Math.max(8, ly) + 'px';
}

/* ---------- groups */
const gBox = $('.' + P + '__groups');
function renderGroups() {
  const opts = [['all', 'Firm-wide', TK.length]].concat(Object.entries(GROUPS).map(([k, v]) => [k, v[0], TK.filter((t) => t.g === k).length]));
  gBox.innerHTML = opts.map(([k, n, c]) => `<button type="button" role="radio" data-g="${k}" aria-checked="${state.g === k}" tabindex="${state.g === k ? 0 : -1}">${n}<small>${c}</small></button>`).join('');
}

/* ---------- KPIs */
function renderKpis() {
  const s = scopeStats(scope(), state.q);
  const prev = state.q === 'ytd' || state.q === 0 ? null : scopeStats(scope(), state.q - 1);
  const d = (a, b) => { if (!prev) return ''; const x = (a - b) * 100; return `<small class="${x >= 0 ? 'good' : 'bad'}">${x >= 0 ? '+' : '−'}${Math.abs(x).toFixed(1)} pts</small>`; };
  const tiles = [
    ['Billable hours', hrs(s.hours), `<small>${pc(s.util, 0)} of target</small>`],
    ['Billing realisation', pc(s.billed / s.worked), d(s.billed / s.worked, prev && prev.billed / prev.worked)],
    ['Collection rate', pc(s.coll / s.billed), d(s.coll / s.billed, prev && prev.coll / prev.billed)],
    ['Overall realisation', pc(s.real), d(s.real, prev && prev.real)]
  ];
  $('.' + P + '__kpis').innerHTML = tiles.map((t) => `<div><dt>${t[0]}</dt><dd>${t[1]}${t[2]}</dd></div>`).join('');
}

/* ---------- the river: every leak is a constant-width ribbon peeling off the bottom */
const svgEl = $('.' + P + '__river');
const LEAKS = [['Pre-bill write-off', 'WIP written off before invoicing'], ['Discounts & caps', 'Agreed discounts and fee caps'], ['Credit notes', 'Reductions after the bill went out'], ['Unpaid > 180 days', 'Billed, not collected, aged out']];
let river = null, shownV = null, tweenId = 0;
function mk(tag, attrs, parent) { const el = document.createElementNS(NS, tag); for (const k in attrs) el.setAttribute(k, attrs[k]); if (parent) parent.append(el); return el; }
function buildRiver() {
  svgEl.innerHTML = '';
  /* each leak runs teal inside the river and turns its own colour through the bend:
