  const uid = P + '-' + Math.random().toString(36).slice(2, 8);
  const defs = mk('defs', {}, svgEl);
  const grads = ['l0', 'l1', 'l2', 'l3', 'keep'].map((c, i) => {
    const lg = mk('linearGradient', { id: uid + i, gradientUnits: 'userSpaceOnUse', y1: 0, y2: 0 }, defs);
    mk('stop', { offset: 0, style: `stop-color:var(--${P}-teal)` }, lg);
    mk('stop', { offset: 1, style: `stop-color:var(--${P}-${c === 'keep' ? 'teal' : c})` }, lg);
    return lg;
  });
  const g = mk('g', {}, svgEl);
  river = { g, rb: [], hit: [], txt: {}, grads };
  /* flows drawn bottom-most leak first so later ribbons sit on top at the seams */
  ['l0', 'l1', 'l2', 'l3', 'keep'].forEach((c, i) => {
    river.rb.push(mk('path', { class: 'rb ' + c, pathLength: 1, style: `--i:${i};stroke:url(#${uid + i})` }, g));
  });
  river.gates = [0, 1, 2].map(() => mk('line', { class: 'gate' }, g));
  const T = (cls, i) => mk('text', { class: cls, style: `--i:${i}` }, g);
  river.txt = {
    wl: T('gl', 0), wv: T('gv', 0), ws: T('gs', 0),
    bl: T('gl', 2), bv: T('gv', 2), bs: T('gs', 2),
    cl: T('gl', 4), cv: T('gv big', 4), cs: T('gs', 4),
    sk: [0, 1, 2, 3].map((i) => [T('sk', i), T('sv', i)])
  };
  river.hit = ['l0', 'l1', 'l2', 'l3', 'keep'].map((k, i) => mk('path', { class: 'hit', 'data-k': i, fill: 'none', stroke: 'transparent' }, g));
}
function layoutRiver(v) {
  const W = svgEl.clientWidth || 900, H = svgEl.clientHeight || 252;
  svgEl.setAttribute('viewBox', `0 0 ${W} ${H}`);
  const compact = W < 900;
  const padL = compact ? 6 : 128, padR = compact ? 6 : 150;
  const top = compact ? 46 : 30, band = compact ? 92 : 132;
  const x0 = padL, xE = W - padR, span = xE - x0;
  const s = band / v.worked;
  const parts = [v.L[0], v.L[1], v.L[2], v.L[3], v.coll];
  const th = parts.map((p) => Math.max(0.6, p * s));
  /* stacking top → bottom: keep, l3, l2, l1, l0 */
  const order = [4, 3, 2, 1, 0], yc = [];
  let y = top;
  order.forEach((k) => { yc[k] = y + th[k] / 2; y += th[k]; });
  const bendX = [0.12, 0.3, 0.6, 0.78].map((f) => x0 + f * span);
  const sinkY = top + band + (compact ? 36 : 54);
  const R = th.map((t) => Math.max(t / 2 + 12, compact ? 22 : 30));
  const dLeak = (k) => {
    const xb = bendX[k], r = R[k], c = 0.5523;
    return `M${x0} ${yc[k]}H${xb}C${xb + r * c} ${yc[k]} ${xb + r} ${yc[k] + r * (1 - c)} ${xb + r} ${yc[k] + r}V${sinkY}`;
  };
  river.rb.forEach((p, k) => {
    p.setAttribute('d', k < 4 ? dLeak(k) : `M${x0} ${yc[4]}H${xE}`);
    p.setAttribute('stroke-width', th[k]);
    const lg = river.grads[k];
    lg.setAttribute('x1', k < 4 ? bendX[k] + R[k] * 0.15 : x0);
    lg.setAttribute('x2', k < 4 ? bendX[k] + R[k] * 0.85 : xE);
  });
  river.hit.forEach((p, k) => {
    p.setAttribute('d', k < 4 ? dLeak(k) : `M${x0} ${yc[4]}H${xE}`);
    p.setAttribute('stroke-width', Math.max(th[k], 12));
  });
  const xB = x0 + 0.45 * span;
  [[x0, top - 4, top + band + 4], [xB, top - 4, top + th[4] + th[3] + th[2] + 4], [xE, top - 4, top + th[4] + 4]].forEach(([x, a, b], i) => {
    const l = river.gates[i]; l.setAttribute('x1', x); l.setAttribute('x2', x); l.setAttribute('y1', a); l.setAttribute('y2', b);
  });
  const t = river.txt;
  const put = (el, x, yy, str, anchor) => { el.setAttribute('x', x); el.setAttribute('y', yy); el.setAttribute('text-anchor', anchor || 'start'); el.textContent = str; };
  if (compact) {
    put(t.wl, x0, 12, 'Worked'); put(t.wv, x0, 28, money(v.worked)); put(t.ws, x0, 40, hrs(v.hours));
    put(t.bl, xB, 12, 'Billed', 'middle'); put(t.bv, xB, 28, money(v.billed), 'middle'); put(t.bs, xB, 40, pc(v.billed / v.worked), 'middle');
    put(t.cl, xE, 12, 'Collected', 'end'); put(t.cv, xE, 30, money(v.coll), 'end'); put(t.cs, xE, 42, pc(v.coll / v.worked) + ' realised', 'end');
  } else {
    put(t.wl, x0 - 14, top + 14, 'Worked', 'end'); put(t.wv, x0 - 14, top + 34, money(v.worked), 'end'); put(t.ws, x0 - 14, top + 50, hrs(v.hours), 'end');
    put(t.bl, xB + 8, 12, 'Billed'); put(t.bv, xB + 8, 27, money(v.billed)); put(t.bs, xB + 70, 27, pc(v.billed / v.worked) + ' of worked');
    put(t.cl, xE + 14, top + 12, 'Collected'); put(t.cv, xE + 14, top + 36, money(v.coll)); put(t.cs, xE + 14, top + 52, pc(v.coll / v.worked) + ' realised');
  }
  t.sk.forEach(([n, val], k) => {
    const x = bendX[k] + R[k];
    const row = compact && k % 2 ? 26 : 0;
    put(n, x, sinkY + 15 + row, compact ? ['Write-off', 'Discounts', 'Credit notes', 'Unpaid'][k] : LEAKS[k][0], 'middle');
    put(val, x, sinkY + 28 + row, '−' + money(v.L[k]) + ' · ' + pc(v.L[k] / v.worked), 'middle');
  });
  svgEl.setAttribute('aria-label', `Of ${money(v.worked)} worked, ${money(v.billed)} was billed and ${money(v.coll)} collected, ${pc(v.coll / v.worked)} realisation. Leaks: ` + LEAKS.map((l, k) => `${l[0]} ${money(v.L[k])}`).join(', '));
}
function renderRiver() {
  const to = scopeStats(scope(), state.q);
  if (!river) buildRiver();
  if (!shownV || reduce.matches) { shownV = to; layoutRiver(to); return; }
  const from = shownV, id = ++tweenId, t0 = performance.now(), dur = 620;
  const lerp = (a, b, e) => a + (b - a) * e;
  const step = (now) => {
    if (!root.isConnected || id !== tweenId) return;
    const k = Math.min(1, (now - t0) / dur), e = 1 - Math.pow(1 - k, 3);
    const v = { worked: lerp(from.worked, to.worked, e), hours: lerp(from.hours, to.hours, e), billed: lerp(from.billed, to.billed, e), coll: lerp(from.coll, to.coll, e), L: from.L.map((x, i) => lerp(x, to.L[i], e)) };
    shownV = k < 1 ? v : to;
    layoutRiver(shownV);
    if (k < 1) requestAnimationFrame(step);
  };
  requestAnimationFrame(step);
}
svgEl.addEventListener('pointermove', (e) => {
  const h = e.target.closest('.hit');
  river.rb.forEach((p, k) => { p.style.opacity = h && +h.dataset.k !== k ? '.32' : ''; });
  if (!h) { tip.hidden = true; return; }
  const k = +h.dataset.k, v = shownV;
  const val = k < 4 ? v.L[k] : v.coll;
  const name = k < 4 ? LEAKS[k][0] : 'Collected';
  const sub = k < 4 ? LEAKS[k][1] : 'Cash in the bank';
  const people = scope().map((t) => [t, tkStats(t, state.q)]).sort((a, b) => (k < 4 ? b[1].L[k] - a[1].L[k] : b[1].coll - a[1].coll)).slice(0, 2);
  showTip(`<b>${name} · ${usd(val)}</b><span>${sub}</span><span>${pc(val / v.worked)} of value worked · ≈${Math.round(val / (v.worked / v.hours)).toLocaleString('en-US')} h</span>` +
    (scope().length > 1 ? `<span>Largest: ${people.map(([t, s]) => esc(t.name.split(' ')[0]) + ' ' + money(k < 4 ? s.L[k] : s.coll)).join(', ')}</span>` : ''), e.clientX, e.clientY);
});
svgEl.addEventListener('pointerleave', () => { tip.hidden = true; river.rb.forEach((p) => { p.style.opacity = ''; }); });

/* ---------- timekeeper table */
function renderTable(flip) {
  const tb = $('.' + P + '__table tbody');
  const before = new Map();
  if (flip && !reduce.matches) $$('tr', tb).forEach((tr) => before.set(tr.dataset.t, tr.getBoundingClientRect().top));
  const rows = people().map((t) => ({ t, s: tkStats(t, state.q) }));
  const key = { name: (r) => r.t.name, hours: (r) => r.s.hours, util: (r) => r.s.util, real: (r) => r.s.real, coll: (r) => r.s.coll }[state.sort];
  rows.sort((a, b) => (state.sort === 'name' ? key(a).localeCompare(key(b)) * state.dir : (key(a) - key(b)) * state.dir));
  tb.innerHTML = rows.map(({ t, s }, i) => {
    const sel = state.tk === t;
    const uw = Math.min(1, s.util / 1.25), real = s.real;
    return `<tr data-t="${t.i}" tabindex="${sel || (!state.tk && i === 0) ? 0 : -1}" aria-selected="${sel}">` +
      `<td><span class="${P}__who"><i style="--av:${av(t)}">${t.ini}</i><span><b>${esc(t.name)}</b><small>${LEVEL[t.lv][0]} · ${GROUPS[t.g][0]}</small></span></span></td>` +
      `<td class="${P}__h1">${hrs(s.hours)}</td>` +
      `<td><span class="${P}__meter"><span><b style="--w:${(uw * 100).toFixed(1)}%;--c:${s.util >= 1 ? `var(--${P}-teal)` : `var(--${P}-ochre)`}"></b><i style="--t:${(100 / 1.25).toFixed(1)}%"></i></span>${pc(s.util, 0)}</span></td>` +
      `<td><span class="${P}__meter"><span><b style="--w:${(real * 100).toFixed(1)}%;--c:${real < 0.8 ? `var(--${P}-rust)` : `var(--${P}-teal)`}"></b></span>${pc(real)}</span></td>` +
      `<td class="${P}__h2">${money(s.coll)}</td></tr>`;
  }).join('');
  $$('.' + P + '__table th[aria-sort]').forEach((th) => {
    const k = th.querySelector('[data-sort]').dataset.sort;
    th.setAttribute('aria-sort', k === state.sort ? (state.dir < 0 ? 'descending' : 'ascending') : 'none');
  });
  if (before.size) $$('tr', tb).forEach((tr) => {
    const b = before.get(tr.dataset.t); if (b == null) return;
    const dy = b - tr.getBoundingClientRect().top;
    if (Math.abs(dy) > 1) tr.animate([{ transform: `translateY(${dy}px)` }, { transform: 'none' }], { duration: 560, easing: 'cubic-bezier(.22,1,.36,1)' });
  });
}

/* ---------- heat map */
function renderHeat() {
  const [a, b] = QW(state.q), n = b - a, list = people();
  const el = $('.' + P + '__heat');
  el.style.setProperty('--cols', n);
  el.style.setProperty('--cw', n > 13 ? '15px' : '34px');
  let s = `<div role="row" style="display:contents"><div class="hh" role="columnheader">Timekeeper</div>`;
  for (let w = a; w < b; w++) s += `<div class="hh" role="columnheader">${n > 13 ? ((w - a) % 4 === 0 ? wkLabel(w).split(' ')[1] : '') : wkLabel(w)}</div>`;
  s += `<div class="hh" role="columnheader" style="text-align:right">Total</div></div>`;
  list.forEach((t, r) => {
    let tot = 0;
    s += `<div role="row" style="display:contents"><button type="button" class="nm row-in" style="--i:${r}" data-t="${t.i}" aria-label="Show ${esc(t.name)}’s realisation"><i style="--av:${av(t)}">${t.ini}</i><span>${esc(t.name)}</span></button>`;
    for (let w = a; w < b; w++) {
      const h = t.h[w]; tot += h;
      const d = Math.max(-0.45, Math.min(0.45, (h - t.target) / t.target));
      const p = Math.round(Math.abs(d) / 0.45 * 78 + 6);
      const bg = `color-mix(in oklab, var(--${P}-${d >= 0 ? 'teal' : 'ochre'}) ${p}%, var(--${P}-card))`;
      s += `<div class="c row-in" role="gridcell" style="--i:${r};--bg:${bg};--fg:${p > 52 ? `var(--${P}-card)` : `var(--${P}-ink)`}" data-t="${t.i}" data-w="${w}" aria-label="${esc(t.name)}, week of ${wkLabel(w)}: ${h} hours against ${t.target}">${n > 13 ? '' : Math.round(h)}</div>`;
    }
    s += `<div class="tot row-in" style="--i:${r}">${Math.round(tot)}<small>${pc(tot / (t.target * n), 0)}</small></div></div>`;
  });
  s += `<div class="ft" style="text-align:left">Week total</div>`;
  for (let w = a; w < b; w++) s += `<div class="ft">${n > 13 ? '' : Math.round(list.reduce((x, t) => x + t.h[w], 0))}</div>`;
  s += `<div class="ft" style="text-align:right">${Math.round(list.reduce((x, t) => x + t.h.slice(a, b).reduce((p, q) => p + q, 0), 0)).toLocaleString('en-US')}</div>`;
  el.innerHTML = s;
  $('[data-k=heath]').textContent = `Billable hours by week against target · ${QN(state.q)} 2026`;
}
$('.' + P + '__heat').addEventListener('pointermove', (e) => {
  const c = e.target.closest('.c');
  if (!c) { tip.hidden = true; return; }
  const t = TK[+c.dataset.t], w = +c.dataset.w, h = t.h[w];
  showTip(`<b>${esc(t.name)} · week of ${wkLabel(w)}</b><span>${h} h billable against ${t.target} h target</span><span>${h >= t.target ? '+' : '−'}${Math.abs(h - t.target).toFixed(1)} h · worth ${usd(h * t.rate)} at standard rate</span>`, e.clientX, e.clientY);
});
$('.' + P + '__heat').addEventListener('pointerleave', () => { tip.hidden = true; });

/* ---------- write-offs */
function woRows() {
  const qs = state.q === 'ytd' ? [0, 1, 2] : [state.q];
  return MATTERS.filter((m) => state.g === 'all' || m.g === state.g).map((m) => {
    const wip = qs.reduce((a, q) => a + scopeStats(TK.filter((t) => t.g === m.g), q).L[0], 0);
    return { m, amt: Math.round(wip * m.w / 10) * 10, key: QN(state.q) + '-' + m.id };
  }).sort((a, b) => b.amt - a.amt);
}
function renderWo(flipKey) {
  const ul = $('.' + P + '__wolist');
  const before = new Map();
  if (flipKey && !reduce.matches) $$('li', ul).forEach((li) => before.set(li.dataset.key, li.getBoundingClientRect().top));
  const rows = woRows();
  const ordered = rows.slice().sort((a, b) => (state.wo[a.key] ? 1 : 0) - (state.wo[b.key] ? 1 : 0));
  ul.innerHTML = ordered.map(({ m, amt, key }) => {
    const st = state.wo[key];
    return `<li class="${P}__wo${st ? ' is-done' : ''}${st === 'back' ? ' is-back' : ''}" data-key="${key}"><i></i>` +
      `<span><b>${esc(m.name)}</b><small>${GROUPS[m.g][0]} · responsible partner ${esc(m.partner.name)}</small></span>` +
      `<span class="amt">−${usd(amt)}<small>${st === 'ok' ? 'written off' : st === 'back' ? 'sent back for re-bill' : 'awaiting sign-off'}</small></span>` +
      `<span class="acts">${st ? `<button type="button" data-wo="undo">Undo</button>` : `<button type="button" class="pri" data-wo="ok">Sign off</button><button type="button" data-wo="back">Challenge</button>`}</span>` +
      `<span class="why">${esc(m.why)}</span></li>`;
  }).join('');
  const total = scopeStats(people(), state.q).L[0];
