  const open = rows.filter((r) => !state.wo[r.key]).length;
  $('[data-k=wosum]').innerHTML = `Listed <b>${usd(listed)}</b> of <b>${usd(total)}</b> pre-bill write-offs (${pc(listed / total, 0)}) · <b>${open}</b> awaiting sign-off`;
  $('[data-k=woh]').textContent = `Largest write-offs · ${QN(state.q)} 2026`;
  if (before.size) $$('li', ul).forEach((li) => {
    const b = before.get(li.dataset.key); if (b == null) return;
    const dy = b - li.getBoundingClientRect().top;
    if (Math.abs(dy) > 1) li.animate([{ transform: `translateY(${dy}px)` }, { transform: 'none' }], { duration: 560, easing: 'cubic-bezier(.22,1,.36,1)' });
  });
}

/* ---------- render */
function renderHead() {
  const g = state.g === 'all' ? 'firm-wide' : GROUPS[state.g][0];
  $('[data-k=eyebrow]').textContent = `Harrow Quayle LLP · ${g} · ${QN(state.q)} 2026`;
  $('[data-k=title]').textContent = state.view === 'river' ? (state.tk ? `Where ${state.tk.name.split(' ')[0]}’s hours went` : 'Where the hours went') : state.view === 'heat' ? 'Utilisation by week' : 'Write-offs';
  $('[data-k=riverh]').textContent = state.tk ? `${state.tk.name} · ${LEVEL[state.tk.lv][0]}, $${state.tk.rate.toLocaleString('en-US')}/h` : 'From time worked to cash collected';
  $('[data-act=clear]').hidden = !state.tk;
}
function render(flip) {
  renderHead();
  if (state.view === 'river') { renderKpis(); renderRiver(); renderTable(flip); }
  if (state.view === 'heat') renderHeat();
  if (state.view === 'wo') renderWo();
}

/* ---------- events */
function radio(group, btn) {
  $$('[role=radio]', group).forEach((b) => { const on = b === btn; b.setAttribute('aria-checked', String(on)); b.tabIndex = on ? 0 : -1; });
}
function selectTk(t) {
  state.tk = t;
  $$('.' + P + '__table tbody tr').forEach((tr) => { const on = t && +tr.dataset.t === t.i; tr.setAttribute('aria-selected', String(on)); });
  renderHead(); renderKpis(); renderRiver();
}
root.addEventListener('click', (e) => {
  const t = e.target;
  const nav = t.closest('.' + P + '__rail button');
  if (nav) {
    state.view = nav.dataset.view;
    $$('.' + P + '__rail button').forEach((b) => (b === nav ? b.setAttribute('aria-current', 'page') : b.removeAttribute('aria-current')));
    $$('.' + P + '__view').forEach((v) => { v.hidden = v.dataset.view !== state.view; });
    tip.hidden = true;
    render();
    return;
  }
  const q = t.closest('[data-q]');
  if (q) { state.q = q.dataset.q === 'ytd' ? 'ytd' : +q.dataset.q; radio(q.parentElement, q); render(); return; }
  const g = t.closest('[data-g]');
  if (g) {
    state.g = g.dataset.g; radio(gBox, g);
    if (state.tk && state.g !== 'all' && state.tk.g !== state.g) state.tk = null;
    render(); return;
  }
  const s = t.closest('[data-sort]');
  if (s) {
    if (state.sort === s.dataset.sort) state.dir = -state.dir; else { state.sort = s.dataset.sort; state.dir = s.dataset.sort === 'name' ? 1 : -1; }
    renderTable(true); return;
  }
  const tr = t.closest('.' + P + '__table tbody tr');
  if (tr) { const tk = TK[+tr.dataset.t]; selectTk(state.tk === tk ? null : tk); return; }
  if (t.closest('[data-act=clear]')) { selectTk(null); const f = $('.' + P + '__table tbody tr'); if (f) f.focus({ preventScroll: true }); return; }
  const nm = t.closest('.nm');
  if (nm) {
    state.tk = TK[+nm.dataset.t];
    $('.' + P + '__rail [data-view=river]').click();
    toast(`Showing ${state.tk.name}’s ${QN(state.q)} realisation`);
    return;
  }
  const wo = t.closest('[data-wo]');
  if (wo) {
    const li = wo.closest('li'), key = li.dataset.key;
    const row = woRows().find((r) => r.key === key);
    if (wo.dataset.wo === 'undo') delete state.wo[key]; else state.wo[key] = wo.dataset.wo;
    renderWo(key);
    toast(wo.dataset.wo === 'ok' ? `Signed off · −${usd(row.amt)} on ${row.m.name.split(' —')[0]}` : wo.dataset.wo === 'back' ? `Challenged · ${row.m.partner.name} asked to re-bill` : 'Back to awaiting sign-off');
    const again = $(`[data-key="${key}"] button`); if (again) again.focus({ preventScroll: true });
  }
});
root.addEventListener('keydown', (e) => {
  const r = e.target.closest && e.target.closest('[role=radio]');
  if (r && /^Arrow/.test(e.key)) {
    const all = $$('[role=radio]', r.parentElement), i = all.indexOf(r);
    const n = all[(i + (/Right|Down/.test(e.key) ? 1 : all.length - 1)) % all.length];
    e.preventDefault(); n.click(); n.focus();
    return;
  }
  const tr = e.target.closest && e.target.closest('.' + P + '__table tbody tr');
  if (tr) {
    const all = $$('.' + P + '__table tbody tr'), i = all.indexOf(tr);
    let n = i;
    if (e.key === 'ArrowDown') n = Math.min(all.length - 1, i + 1);
    else if (e.key === 'ArrowUp') n = Math.max(0, i - 1);
    else if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); tr.click(); return; }
    else if (e.key === 'Escape' && state.tk) { selectTk(null); return; }
    else return;
    e.preventDefault(); all.forEach((x) => { x.tabIndex = -1; }); all[n].tabIndex = 0; all[n].focus();
  }
  if (e.key === 'Escape' && state.tk) selectTk(null);
});

/* ---------- mount */
renderGroups();
if (!reduce.matches) { root.classList.add('is-enter'); setTimeout(() => root.classList.remove('is-enter'), 2400); }
render();
let rz = 0, lastW = svgEl.clientWidth;
const ro = new ResizeObserver(() => {
  cancelAnimationFrame(rz);
  rz = requestAnimationFrame(() => {
    if (!root.isConnected) { ro.disconnect(); return; }
    if (svgEl.clientWidth && svgEl.clientWidth !== lastW && shownV) { lastW = svgEl.clientWidth; layoutRiver(shownV); }
  });
});
ro.observe(root);

