@property --dlo-clause-n {
  syntax: "<integer>";
  inherits: true;
  initial-value: 0;
}

.dlo-clause {
  /* re-theme with these four */
  --dlo-clause-bg: oklch(0.2 0.006 255);
  --dlo-clause-ink: oklch(0.93 0.008 250);
  --dlo-clause-amber: oklch(0.81 0.14 76);
  --dlo-clause-red: oklch(0.69 0.17 24);
  /* derived */
  --dlo-clause-green: color-mix(in oklch, oklch(0.78 0.13 152) 92%, var(--dlo-clause-ink));
  --dlo-clause-orange: color-mix(in oklch, var(--dlo-clause-amber) 55%, var(--dlo-clause-red));
  --dlo-clause-rail: color-mix(in oklch, var(--dlo-clause-bg) 80%, black);
  --dlo-clause-panel: color-mix(in oklch, var(--dlo-clause-bg) 94%, var(--dlo-clause-ink));
  --dlo-clause-raise: color-mix(in oklch, var(--dlo-clause-bg) 88%, var(--dlo-clause-ink));
  --dlo-clause-line: color-mix(in oklch, var(--dlo-clause-ink) 10%, transparent);
  --dlo-clause-soft: color-mix(in oklch, var(--dlo-clause-ink) 6%, transparent);
  --dlo-clause-mute: color-mix(in oklch, var(--dlo-clause-ink) 62%, var(--dlo-clause-bg));
  --dlo-clause-faint: color-mix(in oklch, var(--dlo-clause-ink) 40%, var(--dlo-clause-bg));
  --dlo-clause-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dlo-clause-serif: ui-serif, "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, serif;
  --dlo-clause-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dlo-clause-out: cubic-bezier(.16, 1, .3, 1);
  --dlo-clause-spring: linear(0, 0.012, 0.048 2.3%, 0.192 5.1%, 0.716 13.9%, 0.923 18.7%, 1.028 23.2%, 1.068 27%, 1.075 30.6%, 1.058 35%, 1.008 45.4%, 0.993 52.2%, 0.996 64.4%, 1);

  width: 100%;
  height: var(--dlo-clause-h, 680px);
  container-type: inline-size; container-name: dlo-clause;
  position: relative; isolation: isolate; overflow: hidden;
  border-radius: 16px;
  background: var(--dlo-clause-bg); color: var(--dlo-clause-ink);
  font: 13px/1.45 var(--dlo-clause-sans);
  accent-color: var(--dlo-clause-amber);
  color-scheme: dark;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, h4, p, ol) { margin: 0; padding: 0; }
  & :where(ol) { list-style: none; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
  & :where(svg) { display: block; }
  & :focus-visible { outline: 2px solid var(--dlo-clause-amber); outline-offset: 2px; border-radius: 6px; }
  & .dlo-clause__scroll {
    overflow: auto; overscroll-behavior: contain;
    scrollbar-width: thin; scrollbar-color: color-mix(in oklch, var(--dlo-clause-ink) 18%, transparent) transparent;
  }
}
.dlo-clause__shell { height: 100%; display: grid; grid-template-columns: 68px minmax(0, 1fr); grid-template-areas: "rail views"; }

/* ---------- rail */
.dlo-clause__rail {
  grid-area: rail; display: flex; flex-direction: column; align-items: center; gap: 4px; padding: 14px 6px;
  background: var(--dlo-clause-rail); border-right: 1px solid var(--dlo-clause-line);
  & button {
    position: relative; width: 56px; display: grid; justify-items: center; gap: 3px; padding: 8px 0 6px; border-radius: 10px;
    color: var(--dlo-clause-faint); font-size: 10px; font-weight: 600; letter-spacing: .02em;
    transition: background-color .2s, color .2s;
  }
  & button:hover { color: var(--dlo-clause-ink); background: var(--dlo-clause-soft); }
  & button[aria-current=page] { color: var(--dlo-clause-amber); background: color-mix(in oklch, var(--dlo-clause-amber) 11%, transparent); }
  & svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  & em { position: absolute; top: 2px; right: 3px; min-width: 16px; padding: 0 4px; border-radius: 8px; font: 700 9.5px var(--dlo-clause-mono); font-style: normal; line-height: 15px; text-align: center; background: var(--dlo-clause-red); color: var(--dlo-clause-bg); }
  & em:empty { display: none; }
}
.dlo-clause__logo {
  display: grid; place-items: center; width: 38px; height: 38px; margin-bottom: 12px; border-radius: 11px; background: var(--dlo-clause-amber);
  & svg { width: 21px; height: 21px; stroke: var(--dlo-clause-bg); stroke-width: 1.8; }
}

.dlo-clause__views { grid-area: views; position: relative; min-width: 0; min-height: 0; }
.dlo-clause__view { height: 100%; min-height: 0; }
.dlo-clause__view[hidden] { display: none; }

/* ---------- queue view: three panes */
.dlo-clause__qv { display: grid; grid-template-columns: minmax(250px, 296px) minmax(0, 1fr) minmax(220px, 252px); grid-template-areas: "queue review ladder"; }
.dlo-clause__queue { grid-area: queue; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); border-right: 1px solid var(--dlo-clause-line); }
.dlo-clause__qh {
  padding: 16px 14px 10px; display: grid; gap: 6px;
  & h2 { font-size: 16px; font-weight: 700; letter-spacing: -.02em; }
  & p { font-size: 11.5px; color: var(--dlo-clause-mute); font-variant-numeric: tabular-nums; }
  & p b { color: var(--dlo-clause-ink); }
}
.dlo-clause__sev, .dlo-clause__mode {
  display: flex; gap: 2px; padding: 2px; border-radius: 8px; background: var(--dlo-clause-soft); margin-top: 4px;
  & button { flex: 1; padding: 4px 8px; border-radius: 6px; font-size: 11.5px; font-weight: 600; color: var(--dlo-clause-mute); text-align: center; transition: background-color .2s, color .2s; white-space: nowrap; }
  & button:hover { color: var(--dlo-clause-ink); }
  & button[aria-checked=true] { background: var(--dlo-clause-raise); color: var(--dlo-clause-ink); box-shadow: 0 1px 2px black; }
}
.dlo-clause__mode { margin: 0; }
.dlo-clause__list { padding: 2px 8px 12px; display: grid; align-content: start; gap: 2px; }
.dlo-clause__grp { padding: 10px 6px 4px; font-size: 10.5px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase; color: var(--dlo-clause-faint); }
.dlo-clause__item {
  --sv: var(--dlo-clause-faint);
  display: grid; grid-template-columns: 8px minmax(0, 1fr) auto; grid-template-rows: auto auto; gap: 2px 10px; align-items: center;
  padding: 8px 10px; border-radius: 9px; cursor: pointer; transition: background-color .18s, transform .3s var(--dlo-clause-spring);
  &:hover { background: var(--dlo-clause-soft); }
  &[aria-selected=true] { background: var(--dlo-clause-raise); box-shadow: inset 0 0 0 1px var(--dlo-clause-line), inset 3px 0 0 var(--sv); }
  &:focus-visible { outline-offset: -2px; }
  & i { grid-row: span 2; width: 8px; height: 8px; border-radius: 50%; background: var(--sv); box-shadow: 0 0 0 3px color-mix(in oklch, var(--sv) 22%, transparent); }
  & b { font-size: 12.5px; font-weight: 620; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & small { grid-column: 2; font-size: 11px; color: var(--dlo-clause-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .sc { grid-row: span 2; font: 650 12px var(--dlo-clause-mono); color: var(--sv); font-variant-numeric: tabular-nums; }
  &.s-high { --sv: var(--dlo-clause-red); }
  &.s-med { --sv: var(--dlo-clause-orange); }
  &.s-low { --sv: var(--dlo-clause-amber); }
}
@supports (animation-timeline: view()) {
  .dlo-clause__item { animation: dlo-clause-rise linear both; animation-timeline: view(); animation-range: entry 0% entry 80%; }
}
.dlo-clause__empty { padding: 30px 14px; text-align: center; color: var(--dlo-clause-mute); font-size: 12px; text-wrap: balance; }

/* ---------- reviewer */
.dlo-clause__review { grid-area: review; min-width: 0; min-height: 0; padding: 18px 22px 16px; display: flex; flex-direction: column; gap: 12px; }
.dlo-clause__rh { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 16px; align-items: start; }
.dlo-clause__rt {
  min-width: 0;
  & p { font-size: 11px; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; color: var(--dlo-clause-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & h3 { font-size: clamp(18px, 2.2cqi, 23px); font-weight: 700; letter-spacing: -.02em; line-height: 1.15; margin-top: 3px; text-wrap: balance; }
  & h3 span { display: inline-block; margin-left: 8px; vertical-align: 3px; padding: 2px 8px; border-radius: 99px; font: 650 10.5px var(--dlo-clause-sans); letter-spacing: .04em; text-transform: uppercase; background: color-mix(in oklch, var(--sv) 18%, transparent); color: var(--sv); }
}
.dlo-clause__gauge {
  --sc: 0;
  position: relative; width: 96px; flex: none;
  & svg { width: 96px; height: 56px; overflow: visible; }
  & .trk { fill: none; stroke: var(--dlo-clause-soft); stroke-width: 8; stroke-linecap: round; }
  & .val { fill: none; stroke: var(--sv, var(--dlo-clause-amber)); stroke-width: 8; stroke-linecap: round; stroke-dasharray: calc(var(--dlo-clause-n) * 1px) 200px; transition: stroke .3s; }
  & b { position: absolute; left: 0; right: 0; top: 24px; text-align: center; font: 700 20px var(--dlo-clause-mono); font-variant-numeric: tabular-nums; }
  & small { display: block; margin-top: 1px; text-align: center; font-size: 9.5px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase; color: var(--dlo-clause-faint); }
}
.dlo-clause__score::after { content: counter(dlo-clause-n); }
.dlo-clause__gauge {
  --dlo-clause-n: var(--sc);
  counter-reset: dlo-clause-n var(--dlo-clause-n);
  transition: --dlo-clause-n .9s var(--dlo-clause-out);
}
.dlo-clause__bar { display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap; }
.dlo-clause__vs { font-size: 11.5px; color: var(--dlo-clause-mute); & b { color: var(--dlo-clause-ink); font-weight: 650; } }
.dlo-clause__diff {
  font-family: var(--dlo-clause-serif); font-size: 15.5px; line-height: 1.75; letter-spacing: .003em; text-wrap: pretty;
  padding: 16px 18px; border-radius: 12px; background: var(--dlo-clause-panel); box-shadow: inset 0 0 0 1px var(--dlo-clause-line);
  & del, & ins { text-decoration-thickness: 1.5px; text-underline-offset: 3px; border-radius: 3px; padding: 0 1px; }
  & del { color: color-mix(in oklch, var(--dlo-clause-red) 80%, var(--dlo-clause-ink)); background: color-mix(in oklch, var(--dlo-clause-red) 14%, transparent); text-decoration-line: line-through; text-decoration-color: var(--dlo-clause-red); }
  & ins { color: color-mix(in oklch, var(--dlo-clause-green) 85%, var(--dlo-clause-ink)); background: color-mix(in oklch, var(--dlo-clause-green) 13%, transparent); text-decoration-line: underline; text-decoration-color: var(--dlo-clause-green); }
  & .hot { box-shadow: 0 0 0 1.5px var(--dlo-clause-amber); }
  &.is-anim del, &.is-anim ins { animation: dlo-clause-mark .7s var(--dlo-clause-out) both; animation-delay: calc(var(--i) * 45ms + 80ms); }
  &.is-split { display: grid; grid-template-columns: 1fr 1fr; gap: 18px; font-size: 14px; }
  & h5 { margin: 0 0 6px; font: 650 10.5px var(--dlo-clause-sans); letter-spacing: .08em; text-transform: uppercase; color: var(--dlo-clause-faint); }
}
.dlo-clause__stats {
  display: flex; flex-wrap: wrap; gap: 6px 16px; font-size: 11.5px; color: var(--dlo-clause-mute);
  & span { display: inline-flex; align-items: center; gap: 6px; }
  & i { width: 9px; height: 9px; border-radius: 2px; }
  & .i-ins { background: var(--dlo-clause-green); }
  & .i-del { background: var(--dlo-clause-red); }
  & .i-hot { box-shadow: inset 0 0 0 1.5px var(--dlo-clause-amber); }
}
.dlo-clause__ctx {
  display: grid; grid-template-columns: 30px minmax(0, 1fr); gap: 10px; padding: 12px 14px; border-radius: 12px; background: var(--dlo-clause-soft);
  & i { display: grid; place-items: center; width: 30px; height: 30px; border-radius: 50%; font: 700 11px var(--dlo-clause-sans); font-style: normal; background: var(--dlo-clause-raise); color: var(--dlo-clause-mute); box-shadow: inset 0 0 0 1px var(--dlo-clause-line); }
  & p { font-size: 12.5px; color: var(--dlo-clause-ink); text-wrap: pretty; }
  & small { display: block; font-size: 11px; color: var(--dlo-clause-faint); margin-bottom: 2px; }
}
.dlo-clause__acts {
  margin-top: auto; display: flex; flex-wrap: wrap; gap: 8px; padding-top: 6px;
  & button {
    display: inline-flex; align-items: center; gap: 10px; padding: 9px 12px 9px 14px; border-radius: 10px; font-weight: 650; font-size: 12.5px;
    background: var(--dlo-clause-raise); box-shadow: inset 0 0 0 1px var(--dlo-clause-line);
    transition: background-color .2s, transform .25s var(--dlo-clause-spring), opacity .2s;
  }
  & button:hover { background: color-mix(in oklch, var(--dlo-clause-raise) 80%, var(--dlo-clause-ink)); }
  & button:active { transform: scale(.97); }
  & .is-pri { background: var(--dlo-clause-amber); color: var(--dlo-clause-bg); box-shadow: none; }
  & .is-pri:hover { background: color-mix(in oklch, var(--dlo-clause-amber) 86%, white); }
  & .is-warn { color: var(--dlo-clause-red); }
  & button[aria-disabled=true] { opacity: .42; cursor: not-allowed; transform: none; }
  & kbd { font: 650 10px var(--dlo-clause-mono); padding: 1px 5px; border-radius: 4px; box-shadow: inset 0 0 0 1px currentColor; opacity: .6; }
}

/* ---------- ladder */
.dlo-clause__ladder {
  grid-area: ladder; min-height: 0; overflow: auto; scrollbar-width: none; padding: 18px 14px 14px; border-left: 1px solid var(--dlo-clause-line);
  display: flex; flex-direction: column; gap: 10px; background: color-mix(in oklch, var(--dlo-clause-bg) 70%, var(--dlo-clause-rail));
  & h4 { font-size: 10.5px; font-weight: 650; letter-spacing: .09em; text-transform: uppercase; color: var(--dlo-clause-faint); }
}
.dlo-clause__lnote { font-size: 11.5px; color: var(--dlo-clause-mute); text-wrap: pretty; }
.dlo-clause__rungs { position: relative; display: grid; gap: 6px; padding-left: 16px; }
.dlo-clause__rungs::before { content: ""; position: absolute; left: 5px; top: 10px; bottom: 10px; width: 2px; border-radius: 1px; background: linear-gradient(var(--dlo-clause-green), var(--dlo-clause-amber), var(--dlo-clause-red)); opacity: .55; }
.dlo-clause__rung {
  position: relative; display: grid; gap: 5px; padding: 9px 10px; border-radius: 10px; box-shadow: inset 0 0 0 1px var(--dlo-clause-line);
  transition: background-color .2s, box-shadow .2s, transform .3s var(--dlo-clause-spring);
  &::before { content: ""; position: absolute; left: -15px; top: 14px; width: 10px; height: 10px; border-radius: 50%; background: var(--dlo-clause-bg); box-shadow: inset 0 0 0 2px var(--dlo-clause-faint); transition: box-shadow .2s, background-color .2s; }
  &:hover { background: var(--dlo-clause-soft); }
  &[aria-checked=true] { background: var(--dlo-clause-raise); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dlo-clause-amber) 50%, transparent); }
  &[aria-checked=true]::before { background: var(--dlo-clause-amber); box-shadow: 0 0 0 3px color-mix(in oklch, var(--dlo-clause-amber) 25%, transparent); }
  & b { font-size: 12.5px; font-weight: 650; display: flex; justify-content: space-between; gap: 8px; }
  & b small { font: 600 11px var(--dlo-clause-mono); color: var(--dlo-clause-mute); font-variant-numeric: tabular-nums; }
  & .dist { height: 5px; border-radius: 3px; background: var(--dlo-clause-soft); overflow: hidden; }
  & .dist span { display: block; height: 100%; width: var(--w); border-radius: 3px; background: var(--dlo-clause-mute); transition: width .7s var(--dlo-clause-out); }
  &[aria-checked=true] .dist span { background: var(--dlo-clause-amber); }
  & .here { justify-self: start; font-size: 10.5px; font-weight: 650; padding: 1px 7px; border-radius: 99px; background: color-mix(in oklch, var(--dlo-clause-red) 18%, transparent); color: var(--dlo-clause-red); }
  & .here.ok { background: color-mix(in oklch, var(--dlo-clause-green) 16%, transparent); color: var(--dlo-clause-green); }
}
.dlo-clause__walk {
  margin-top: auto; padding: 10px 12px; border-radius: 10px; background: color-mix(in oklch, var(--dlo-clause-red) 9%, transparent); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dlo-clause-red) 22%, transparent);
  & b { font-size: 11px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase; color: var(--dlo-clause-red); }
  & p { font-size: 12px; color: var(--dlo-clause-mute); margin-top: 3px; text-wrap: pretty; }
}
.dlo-clause.is-beyond .dlo-clause__walk { animation: dlo-clause-pulse 1.6s var(--dlo-clause-out) 1; }

/* ---------- matrix */
.dlo-clause__mv, .dlo-clause__lv { padding: 18px 22px; display: grid; align-content: start; gap: 14px; }
.dlo-clause__mh {
  display: flex; align-items: baseline; justify-content: space-between; gap: 12px; flex-wrap: wrap;
  & h2 { font-size: 17px; font-weight: 700; letter-spacing: -.02em; text-wrap: balance; }
  & p { font-size: 12px; color: var(--dlo-clause-mute); }
}
.dlo-clause__legend {
  display: flex; gap: 12px; flex-wrap: wrap;
  & span { display: inline-flex; align-items: center; gap: 6px; font-size: 11px; }
  & span::before { content: ""; width: 10px; height: 10px; border-radius: 3px; background: var(--c); }
  & .s-high { --c: var(--dlo-clause-red); } & .s-med { --c: var(--dlo-clause-orange); } & .s-low { --c: var(--dlo-clause-amber); }
  & .s-ok { --c: var(--dlo-clause-soft); } & .s-done { --c: color-mix(in oklch, var(--dlo-clause-green) 45%, transparent); }
}
.dlo-clause__matrix {
  display: grid; grid-template-columns: minmax(170px, 230px) repeat(6, minmax(58px, 1fr)); gap: 4px; min-width: 620px;
  & .ch { font-size: 10.5px; font-weight: 650; letter-spacing: .04em; color: var(--dlo-clause-mute); padding: 0 2px 4px; text-align: center; align-self: end; text-wrap: balance; line-height: 1.25; }
  & .rh { display: grid; align-content: center; font-size: 12.5px; font-weight: 620; padding-right: 8px; }
  & .rh small { font-size: 11px; font-weight: 500; color: var(--dlo-clause-faint); }
  & .cell { display: grid; place-items: center; height: 40px; border-radius: 8px; font: 650 11.5px var(--dlo-clause-mono); font-variant-numeric: tabular-nums; }
  & .cell.ok { background: var(--dlo-clause-soft); color: var(--dlo-clause-faint); }
  & .cell.na { background: transparent; box-shadow: inset 0 0 0 1px var(--dlo-clause-soft); color: transparent; }
  & button.cell { --c: var(--dlo-clause-amber); background: color-mix(in oklch, var(--c) 26%, transparent); color: var(--c); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--c) 45%, transparent); transition: transform .25s var(--dlo-clause-spring), background-color .2s; }
  & button.cell:hover { transform: scale(1.06); background: color-mix(in oklch, var(--c) 40%, transparent); }
  & button.cell.s-high { --c: var(--dlo-clause-red); }
  & button.cell.s-med { --c: var(--dlo-clause-orange); }
  & button.cell.s-done { --c: var(--dlo-clause-green); background: color-mix(in oklch, var(--c) 12%, transparent); }
  & svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
  & .cell { animation: dlo-clause-pop .45s var(--dlo-clause-out) both; animation-delay: calc(var(--i) * 14ms); }
}
.dlo-clause__bytype { padding: 14px 16px; border-radius: 12px; background: var(--dlo-clause-panel); box-shadow: inset 0 0 0 1px var(--dlo-clause-line); & h3 { font-size: 13px; font-weight: 650; margin-bottom: 6px; } }
.dlo-clause__bars {
  width: 100%; height: 190px; overflow: visible;
  & .gl { stroke: var(--dlo-clause-line); }
  & .ax { font: 500 10px var(--dlo-clause-mono); fill: var(--dlo-clause-faint); }
  & .lb { font: 600 11.5px var(--dlo-clause-sans); fill: var(--dlo-clause-ink); }
  & .seg { transform-box: fill-box; transform-origin: 0 50%; animation: dlo-clause-grow .7s var(--dlo-clause-out) both; animation-delay: calc(var(--i) * 50ms); }
  & .s-high { fill: var(--dlo-clause-red); } & .s-med { fill: var(--dlo-clause-orange); } & .s-low { fill: var(--dlo-clause-amber); }
  & .row { cursor: default; }
  & .row:hover .seg { filter: brightness(1.15); }
}

/* ---------- log */
.dlo-clause__log { display: grid; gap: 6px; max-width: 860px; }
.dlo-clause__entry {
  display: grid; grid-template-columns: 54px minmax(0, 1fr) auto auto; gap: 4px 14px; align-items: center; padding: 10px 12px; border-radius: 10px;
  background: var(--dlo-clause-panel); box-shadow: inset 0 0 0 1px var(--dlo-clause-line);
  & time { font: 600 11.5px var(--dlo-clause-mono); color: var(--dlo-clause-mute); font-variant-numeric: tabular-nums; }
  & b { display: block; font-weight: 620; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & small { display: block; color: var(--dlo-clause-mute); font-size: 11.5px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .tag { font-size: 11px; font-weight: 650; padding: 2px 9px; border-radius: 99px; background: var(--dlo-clause-soft); white-space: nowrap; }
  & .tag.counter { color: var(--dlo-clause-amber); background: color-mix(in oklch, var(--dlo-clause-amber) 14%, transparent); }
  & .tag.accept { color: var(--dlo-clause-green); background: color-mix(in oklch, var(--dlo-clause-green) 14%, transparent); }
  & .tag.escalate { color: var(--dlo-clause-red); background: color-mix(in oklch, var(--dlo-clause-red) 14%, transparent); }
  & button { padding: 5px 10px; border-radius: 7px; font-size: 12px; font-weight: 600; box-shadow: inset 0 0 0 1px var(--dlo-clause-line); }
  & button:hover { background: var(--dlo-clause-soft); }
  @starting-style { opacity: 0; transform: translateY(6px); }
  transition: opacity .35s, transform .45s var(--dlo-clause-out);
}
.dlo-clause__log:empty::before { content: "No decisions yet. Counter, accept or escalate a clause from the queue and it lands here."; color: var(--dlo-clause-mute); font-size: 12.5px; }

/* ---------- tooltip + toasts */
.dlo-clause__tip {
  position: absolute; z-index: 8; left: 0; top: 0; pointer-events: none; max-width: 240px; padding: 7px 10px; border-radius: 8px;
  background: var(--dlo-clause-ink); color: var(--dlo-clause-bg); font-size: 11.5px; box-shadow: 0 12px 28px -10px black;
  & b { display: block; font-weight: 700; }
  & span { display: block; opacity: .8; font-variant-numeric: tabular-nums; }
}
.dlo-clause__toasts { position: absolute; z-index: 9; left: 50%; bottom: 16px; translate: -50% 0; display: grid; gap: 6px; justify-items: center; pointer-events: none; }
.dlo-clause__toast {
  padding: 9px 14px; border-radius: 10px; background: var(--dlo-clause-ink); color: var(--dlo-clause-bg); font-size: 12px; font-weight: 650; white-space: nowrap;
  box-shadow: 0 14px 30px -12px black; transition: opacity .3s, transform .45s var(--dlo-clause-spring);
  @starting-style { opacity: 0; transform: translateY(10px) scale(.96); }
  &.is-out { opacity: 0; transform: translateY(6px); }
}

@keyframes dlo-clause-mark { from { background-color: transparent; text-decoration-color: transparent; color: inherit; } }
@keyframes dlo-clause-rise { from { opacity: 0; transform: translateY(8px); } }
@keyframes dlo-clause-pop { from { opacity: 0; transform: scale(.85); } }
@keyframes dlo-clause-grow { from { transform: scaleX(0); } }
@keyframes dlo-clause-pulse { 0%, 100% { box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dlo-clause-red) 22%, transparent); } 30% { box-shadow: inset 0 0 0 1px var(--dlo-clause-red), 0 0 0 4px color-mix(in oklch, var(--dlo-clause-red) 20%, transparent); } }

/* ---------- responsive */
@container dlo-clause (width < 960px) {
  .dlo-clause__qv { grid-template-columns: minmax(220px, 250px) minmax(0, 1fr); grid-template-rows: minmax(0, 1fr) auto; grid-template-areas: "queue review" "queue ladder"; }
  .dlo-clause__ladder { border-left: 0; border-top: 1px solid var(--dlo-clause-line); flex-direction: row; flex-wrap: wrap; align-items: flex-start; max-height: 210px; }
  .dlo-clause__ladder h4, .dlo-clause__lnote { width: 100%; }
  .dlo-clause__lnote { display: none; }
  .dlo-clause__rungs { flex: 1 1 100%; grid-template-columns: repeat(3, minmax(0, 1fr)); padding-left: 0; }
  .dlo-clause__rungs::before, .dlo-clause__rung::before { display: none; }
  .dlo-clause__walk { display: none; }
  .dlo-clause__diff { font-size: 14.5px; }
}
@container dlo-clause (width < 760px) {
  .dlo-clause__shell { grid-template-columns: minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); grid-template-areas: "rail" "views"; }
  .dlo-clause__rail { flex-direction: row; padding: 6px 10px; border-right: 0; border-bottom: 1px solid var(--dlo-clause-line); & button { width: auto; grid-auto-flow: column; gap: 6px; padding: 7px 10px; font-size: 11.5px; } & em { position: static; } }
  .dlo-clause__logo { margin: 0 8px 0 0; width: 32px; height: 32px; }
  .dlo-clause__qv { overflow: auto; scrollbar-width: thin; grid-template-columns: minmax(0, 1fr); grid-template-rows: max-content max-content max-content; grid-template-areas: "queue" "review" "ladder"; }
  .dlo-clause__queue { border-right: 0; border-bottom: 1px solid var(--dlo-clause-line); }
  .dlo-clause__list { max-height: 190px; }
  .dlo-clause .dlo-clause__review { overflow: visible; padding: 14px; }
  .dlo-clause__acts { margin-top: 0; }
  .dlo-clause__ladder { max-height: none; overflow: visible; }
  .dlo-clause__mv, .dlo-clause__lv { padding: 14px; }
}
@container dlo-clause (width < 520px) {
  .dlo-clause__rail span { display: none; }
  .dlo-clause__rungs { grid-template-columns: minmax(0, 1fr); }
  .dlo-clause__diff.is-split { grid-template-columns: minmax(0, 1fr); }
  .dlo-clause__gauge { width: 76px; & svg { width: 76px; height: 46px; } & b { top: 18px; font-size: 16px; } }
  .dlo-clause__acts kbd { display: none; }
  .dlo-clause__entry { grid-template-columns: minmax(0, 1fr) auto; & time { display: none; } & .tag { grid-column: 1; justify-self: start; } }
}

@media (prefers-reduced-motion: reduce) {
  .dlo-clause *, .dlo-clause *::before, .dlo-clause *::after {
    animation-duration: 1ms !important; animation-delay: 0ms !important; animation-iteration-count: 1 !important;
    transition-duration: 1ms !important; transition-delay: 0ms !important;
  }
  .dlo-clause .dlo-clause__item { animation: none; }
  .dlo-clause .dlo-clause__gauge { transition: none; }
}

