const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => Array.from(el.querySelectorAll(s));
const reduce = matchMedia('(prefers-reduced-motion: reduce)');
const P = 'dlo-clause';

/* ---------- playbook: three acceptable positions per clause, plus the walk-away line */
const TYPES = {
  lol: { name: 'Limitation of liability', short: 'Liability',
    rungs: ['Each party’s total aggregate liability under this Agreement shall not exceed the fees paid or payable in the twelve (12) months before the claim. Neither party shall be liable for indirect, special or consequential damages.',
      'Each party’s total aggregate liability under this Agreement shall not exceed one and a half times the fees paid or payable in the twelve (12) months before the claim. Neither party shall be liable for indirect, special or consequential damages.',
      'Each party’s total aggregate liability under this Agreement shall not exceed two times the fees paid or payable in the twelve (12) months before the claim, and three times those fees for breach of data protection obligations. Neither party shall be liable for indirect, special or consequential damages.'],
    walk: 'Uncapped liability only for fraud, wilful misconduct and the IP indemnity — never for ordinary breach.' },
  ind: { name: 'Indemnification', short: 'Indemnity',
    rungs: ['The Supplier shall defend and indemnify Fernhill against third-party claims that the Services infringe any intellectual property right, and against losses caused by the Supplier’s breach of applicable law.',
      'The Supplier shall defend and indemnify Fernhill against third-party claims that the Services infringe any intellectual property right.',
      'The Supplier shall defend Fernhill against third-party claims that the Services infringe any intellectual property right, subject to the limitation of liability.'],
    walk: 'An IP infringement defence in every deal. No mutual indemnity for ordinary negligence.' },
  law: { name: 'Governing law', short: 'Law',
    rungs: ['This Agreement is governed by the laws of the State of New York, and the parties submit to the exclusive jurisdiction of the state and federal courts in New York County.',
      'This Agreement is governed by the laws of the State of New York, and the parties submit to the non-exclusive jurisdiction of the state and federal courts in New York County.',
      'This Agreement is governed by the laws of the State of Delaware, and any dispute shall be finally resolved by arbitration seated in New York.'],
    walk: 'Any US state law with a neutral or New York forum — never the counterparty’s home courts abroad.' },
  term: { name: 'Term and renewal', short: 'Term',
    rungs: ['This Agreement continues for twelve (12) months and renews only by written agreement of both parties. Either party may terminate for convenience on thirty (30) days’ prior written notice.',
      'This Agreement continues for twelve (12) months and renews automatically for further twelve-month terms unless either party gives sixty (60) days’ prior written notice. Either party may terminate for convenience on thirty (30) days’ prior written notice.',
      'This Agreement continues for twenty-four (24) months and renews automatically for further twelve-month terms unless either party gives ninety (90) days’ prior written notice.'],
    walk: 'Auto-renewal only with a notice window of ninety days or less; a minimum term over twenty-four months needs CFO approval.' },
  dpa: { name: 'Data protection', short: 'Data',
    rungs: ['The Supplier shall process Personal Data only on Fernhill’s documented instructions, notify Fernhill of any Personal Data Breach within twenty-four (24) hours, and engage sub-processors only with Fernhill’s prior written consent.',
      'The Supplier shall process Personal Data only on Fernhill’s documented instructions, notify Fernhill of any Personal Data Breach within forty-eight (48) hours, and engage sub-processors only after thirty (30) days’ notice and an opportunity to object.',
      'The Supplier shall process Personal Data only on Fernhill’s documented instructions, notify Fernhill of any Personal Data Breach within seventy-two (72) hours, and engage sub-processors only after fifteen (15) days’ notice and an opportunity to object.'],
    walk: 'Breach notice within seventy-two hours and a right to object to new sub-processors are the floor.' },
  pay: { name: 'Payment terms', short: 'Payment',
    rungs: ['Fernhill shall pay undisputed invoices within sixty (60) days of receipt. Overdue amounts bear no interest until more than thirty (30) days late.',
      'Fernhill shall pay undisputed invoices within forty-five (45) days of receipt. Overdue amounts bear interest at one percent (1%) per month.',
      'Fernhill shall pay undisputed invoices within thirty (30) days of receipt. Overdue amounts bear interest at one and a half percent (1.5%) per month.'],
    walk: 'Terms shorter than thirty days, or interest above 1.5% a month, need Finance sign-off.' }
};
const TYPE_KEYS = Object.keys(TYPES);
const RUNG = ['Preferred', 'Fallback 1', 'Fallback 2'];
const CONTRACTS = [
  { id: 'c1', name: 'Brightline Logistics', doc: 'Master services agreement', types: ['lol', 'ind', 'law', 'term', 'pay'] },
  { id: 'c2', name: 'Okapi Health', doc: 'Data processing addendum', types: ['law', 'dpa', 'term'] },
  { id: 'c3', name: 'Tessellate Media', doc: 'Reseller agreement', types: ['lol', 'ind', 'law', 'term', 'pay'] },
  { id: 'c4', name: 'Marrow & Finch', doc: 'Mutual NDA', types: ['law', 'term'] },
  { id: 'c5', name: 'Kiln Systems', doc: 'SaaS subscription terms', types: ['lol', 'ind', 'law', 'term', 'dpa', 'pay'] },
  { id: 'c6', name: 'Harbour Point Bank', doc: 'Pilot agreement', types: ['lol', 'ind', 'law', 'dpa', 'term'] }
];
const CON = Object.fromEntries(CONTRACTS.map((c) => [c.id, c]));
/* pos: where their draft sits on our ladder (0-2) or 3 = past the walk-away line */
const ITEMS = [
  { c: 'c1', t: 'lol', note: ['Dana Whitlock', 'Brightline Legal', 'Our insurers will only cover three months of fees. We can’t take a twelve-month cap.'], pos: 3, sec: '11.2', text: 'The Supplier’s total aggregate liability under this Agreement shall not exceed the fees paid in the three (3) months before the claim. Fernhill’s liability under this Agreement shall be unlimited. Neither party shall be liable for indirect, special or consequential damages.' },
  { c: 'c1', t: 'term', note: ['Dana Whitlock', 'Brightline Legal', 'Our pricing assumes a three-year commitment; the notice window matches our capacity planning.'], pos: 3, sec: '14.1', text: 'This Agreement continues for thirty-six (36) months and renews automatically for further thirty-six-month terms unless Fernhill gives one hundred and eighty (180) days’ prior written notice.' },
  { c: 'c1', t: 'ind', note: ['Dana Whitlock', 'Brightline Legal', 'We defend registered rights only, and need prompt notice to control the defence.'], pos: 2, sec: '10.1', text: 'The Supplier shall defend Fernhill against third-party claims that the Services infringe any registered intellectual property right, subject to the limitation of liability, provided Fernhill gives notice within ten (10) days.' },
  { c: 'c2', t: 'dpa', note: ['Ravi Anand', 'Okapi Health privacy', 'We onboard sub-processors monthly and can’t pause for objections.'], pos: 3, sec: '4.3', text: 'The Supplier shall process Personal Data only on Fernhill’s documented instructions, notify Fernhill of any Personal Data Breach within seventy-two (72) hours, and may engage sub-processors after thirty (30) days’ notice.' },
  { c: 'c2', t: 'law', note: ['Ravi Anand', 'Okapi Health privacy', 'Non-exclusive keeps our options open in other states. Happy to keep New York law.'], pos: 1, sec: '9.4', text: 'This Agreement is governed by the laws of the State of New York, and the parties submit to the non-exclusive jurisdiction of the courts in New York County.' },
  { c: 'c3', t: 'pay', note: ['Hollis Grant', 'Tessellate commercial', 'Standard reseller terms across our channel; fifteen days is non-negotiable for us.'], pos: 3, sec: '6.1', text: 'Fernhill shall pay all invoices within fifteen (15) days of the invoice date. Overdue amounts bear interest at two percent (2%) per month.' },
  { c: 'c3', t: 'lol', note: ['Hollis Grant', 'Tessellate commercial', 'We took your one-and-a-half times position and tidied the wording.'], pos: 1, sec: '12.1', text: 'Each party’s total aggregate liability under this Agreement shall not exceed one and a half times the fees paid in the twelve (12) months before the claim. Neither party shall be liable for indirect or consequential damages.' },
  { c: 'c4', t: 'law', note: ['Imogen Pryce', 'Marrow & Finch', 'Our NDA template is English law only. It’s a mutual NDA, so low risk.'], pos: 3, sec: '8', text: 'This Agreement is governed by the laws of England and Wales, and the parties submit to the exclusive jurisdiction of the courts of London.' },
  { c: 'c5', t: 'term', note: ['Kiln deal desk', 'Kiln Systems', 'Ninety days lets us plan renewals; we removed convenience termination to match the discount.'], pos: 2, sec: '3.2', text: 'This Agreement continues for twelve (12) months and renews automatically for further twelve-month terms unless either party gives ninety (90) days’ prior written notice.' },
  { c: 'c5', t: 'lol', note: ['Kiln deal desk', 'Kiln Systems', 'Two times fees is our standard enterprise cap.'], pos: 2, sec: '15.1', text: 'Each party’s total aggregate liability under this Agreement shall not exceed two times the fees paid or payable in the twelve (12) months before the claim. Neither party shall be liable for indirect, special or consequential damages.' },
  { c: 'c6', t: 'ind', note: ['Marcus Bell', 'Harbour Point Bank', 'Our pilot paper is fully mutual. We expect the same in return.'], pos: 3, sec: '7.1', text: 'Each party shall defend and indemnify the other against all claims arising from its negligence or breach of this Agreement, without limit.' },
  { c: 'c6', t: 'dpa', note: ['Marcus Bell', 'Harbour Point Bank', 'Added a reasonableness qualifier on consent. Otherwise your wording.'], pos: 0, sec: '5.2', text: 'The Supplier shall process Personal Data only on Fernhill’s documented instructions, notify Fernhill of any Personal Data Breach within twenty-four (24) hours, and engage sub-processors only with Fernhill’s prior written consent, not to be unreasonably withheld.' }
].map((x, i) => ({ ...x, id: 'q' + i, sev: x.pos === 3 ? 'high' : x.pos === 2 ? 'med' : 'low' }));
const SEVN = { high: 'High', med: 'Medium', low: 'Low' };

/* ---------- word diff (LCS) and a risk-weighted score */
const toks = (s) => s.match(/\S+\s*/g) || [];
const norm = (w) => w.trim().toLowerCase().replace(/’/g, "'");
function diff(a, b) {
  const A = toks(a), B = toks(b), n = A.length, m = B.length;
  const L = Array.from({ length: n + 1 }, () => new Uint16Array(m + 1));
  for (let i = n - 1; i >= 0; i--) for (let j = m - 1; j >= 0; j--) L[i][j] = norm(A[i]) === norm(B[j]) ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1]);
  const ops = [];
  const push = (t, w) => { const l = ops[ops.length - 1]; if (l && l.t === t) { l.s += w; l.n++; } else ops.push({ t, s: w, n: 1 }); };
  let i = 0, j = 0;
  while (i < n && j < m) {
    if (norm(A[i]) === norm(B[j])) { push('eq', B[j]); i++; j++; }
    else if (L[i + 1][j] >= L[i][j + 1]) { push('del', A[i]); i++; }
    else { push('ins', B[j]); j++; }
  }
  while (i < n) push('del', A[i++]);
  while (j < m) push('ins', B[j++]);
  return ops;
}
/* phrases that make a change dangerous when they come in, or when they go out */
const RISK_IN = [[/unlimited|without limit/, 30], [/two times/, 18], [/one and a half times/, 8], [/ninety \(90\)/, 12], [/non-exclusive/, 8], [/negligence/, 14], [/three \(3\) months/, 14], [/england|london/, 22], [/one hundred and eighty/, 18], [/thirty-six/, 12], [/fifteen \(15\) days of the invoice/, 12], [/two percent/, 12], [/provided fernhill gives notice/, 9], [/registered/, 6], [/seventy-two/, 6]];
const RISK_OUT = [[/opportunity to object/, 16], [/terminate for convenience/, 14], [/breach of applicable law/, 10], [/or payable/, 5], [/special/, 5], [/prior written consent/, 8], [/exclusive/, 6]];
function assess(base, theirs) {
  const ops = diff(base, theirs);
  const total = ops.reduce((a, o) => a + o.n, 0) || 1;
  const ins = ops.filter((o) => o.t === 'ins'), del = ops.filter((o) => o.t === 'del');
  const nIns = ins.reduce((a, o) => a + o.n, 0), nDel = del.reduce((a, o) => a + o.n, 0);
  let s = (nIns + nDel) / total * 70, hot = 0;
  ops.forEach((o) => {
    const txt = o.s.toLowerCase().replace(/’/g, "'");
    const list = o.t === 'ins' ? RISK_IN : o.t === 'del' ? RISK_OUT : [];
    list.forEach(([re, w]) => { if (re.test(txt)) { s += w; o.hot = true; hot++; } });
  });
  return { ops, nIns, nDel, hot, dist: (nIns + nDel) / total, score: Math.max(nIns + nDel ? 3 : 0, Math.min(99, Math.round(s))) };
}
ITEMS.forEach((it) => { it.base = assess(TYPES[it.t].rungs[0], it.text); });

/* ---------- state */
const state = { view: 'queue', sev: 'all', sel: ITEMS[0].id, rung: {}, mode: 'inline', done: {}, log: [], clock: 10 * 60 + 42 };
const suggested = (it) => (it.pos === 3 ? 2 : Math.max(0, it.pos - 1));
const rungOf = (it) => (state.rung[it.id] != null ? state.rung[it.id] : suggested(it));
const open = () => ITEMS.filter((it) => !state.done[it.id]);
const shown = () => open().filter((it) => state.sev === 'all' || it.sev === state.sev);
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const sevVar = (s) => `var(--${P}-${s === 'high' ? 'red' : s === 'med' ? 'orange' : 'amber'})`;
const hhmm = (m) => String(Math.floor(m / 60)).padStart(2, '0') + ':' + String(m % 60).padStart(2, '0');

const list = $('.' + P + '__list');
const diffBox = $('.' + P + '__diff');
const gauge = $('.' + P + '__gauge');
const tip = $('.' + P + '__tip');
const toasts = $('.' + P + '__toasts');
function toast(msg) {
  const t = document.createElement('div');
  t.className = P + '__toast'; t.textContent = msg;
  toasts.append(t);
  while (toasts.children.length > 2) toasts.firstChild.remove();
  setTimeout(() => { t.classList.add('is-out'); setTimeout(() => t.remove(), 350); }, 2600);
}

/* ---------- queue */
function renderQueue(flip) {
  const before = new Map();
  if (flip && !reduce.matches) $$('[role=option]', list).forEach((o) => before.set(o.dataset.id, o.getBoundingClientRect().top));
  const items = shown();
  const order = CONTRACTS.map((c) => [c, items.filter((it) => it.c === c.id).sort((a, b) => b.pos - a.pos || b.base.score - a.base.score)]).filter(([, l]) => l.length)
    .sort((a, b) => Math.max(...b[1].map((x) => x.pos)) - Math.max(...a[1].map((x) => x.pos)));
  if (!items.some((it) => it.id === state.sel)) state.sel = order.length ? order[0][1][0].id : null;
  list.innerHTML = order.map(([c, l]) => `<li class="${P}__grp" role="presentation">${esc(c.name)} · ${esc(c.doc)}</li>` +
    l.map((it) => `<li class="${P}__item s-${it.sev}" role="option" data-id="${it.id}" id="${P}-${it.id}" aria-selected="${it.id === state.sel}" tabindex="${it.id === state.sel ? 0 : -1}">` +
      `<i></i><b>${TYPES[it.t].name}</b><span class="sc" title="Deviation score against the preferred position">${it.base.score}</span><small>§${it.sec} · ${SEVN[it.sev]}${it.pos === 3 ? ' · past walk-away' : ' · near ' + RUNG[it.pos]}</small></li>`).join('')).join('') ||
    `<li class="${P}__empty" role="presentation">${open().length ? 'Nothing at this severity.' : 'Queue cleared. Every flagged clause has a decision.'}</li>`;
  const o = open();
  $('[data-k=qsum]').innerHTML = `<b>${o.length}</b> open · <b>${o.filter((x) => x.sev === 'high').length}</b> high · median score <b>${median(o.map((x) => x.base.score))}</b>`;
  $('[data-k=open]').textContent = o.length ? String(o.length) : '';
  if (before.size) $$('[role=option]', list).forEach((el) => {
    const b = before.get(el.dataset.id); if (b == null) return;
    const dy = b - el.getBoundingClientRect().top;
    if (Math.abs(dy) > 1) el.animate([{ transform: `translateY(${dy}px)` }, { transform: 'none' }], { duration: 520, easing: 'cubic-bezier(.16,1,.3,1)' });
  });
}
function median(a) { if (!a.length) return '—'; const s = a.slice().sort((x, y) => x - y), h = s.length >> 1; return s.length % 2 ? s[h] : Math.round((s[h - 1] + s[h]) / 2); }

/* ---------- reviewer */
function opsHTML(ops, only) {
  let i = 0;
  return ops.map((o) => {
    if (o.t === 'eq') return esc(o.s);
    if (only && o.t !== only) return '';
    return `<${o.t} class="${o.hot ? 'hot' : ''}" style="--i:${i++}">${esc(o.s)}</${o.t}>`;
  }).join('');
}
function renderReview(animate) {
  const it = ITEMS.find((x) => x.id === state.sel);
  const review = $('.' + P + '__review');
  review.hidden = false;
  if (!it) {
    $('[data-k=crumb]').textContent = 'Queue';
    $('[data-k=clause]').textContent = 'Nothing left to review';
    diffBox.innerHTML = '<p>Every flagged clause has a decision. The log has the trail, and Undo puts any of them back.</p>';
    $('[data-k=stats]').textContent = ''; $('[data-k=vs]').textContent = ''; $('.' + P + '__ctx').innerHTML = '';
    gauge.style.setProperty('--sc', 0);
    $$('.' + P + '__acts button').forEach((b) => { b.setAttribute('aria-disabled', 'true'); b.title = 'The queue is empty'; });
    $('.' + P + '__rungs').innerHTML = ''; $('[data-k=walk]').textContent = '';
    return;
  }
  const T = TYPES[it.t], c = CON[it.c], r = rungOf(it);
  const a = assess(T.rungs[r], it.text);
  review.style.setProperty('--sv', sevVar(it.sev));
  $('[data-k=crumb]').textContent = `${c.name} · ${c.doc} · §${it.sec}`;
  $('[data-k=clause]').innerHTML = `${T.name}<span>${SEVN[it.sev]}</span>`;
  $('[data-k=vs]').innerHTML = `Their draft against <b>${RUNG[r]}</b>${r === suggested(it) ? ' (suggested)' : ''}`;
  gauge.style.setProperty('--sc', a.score);
  gauge.style.setProperty('--sv', a.score >= 60 ? `var(--${P}-red)` : a.score >= 30 ? `var(--${P}-orange)` : `var(--${P}-green)`);
  if (state.mode === 'inline') {
    diffBox.classList.remove('is-split');
    diffBox.innerHTML = opsHTML(a.ops);
  } else {
    diffBox.classList.add('is-split');
    diffBox.innerHTML = `<div><h5>Their draft</h5>${opsHTML(a.ops, 'ins')}</div><div><h5>Playbook · ${RUNG[r]}</h5>${opsHTML(a.ops, 'del')}</div>`;
  }
  if (animate && !reduce.matches) { diffBox.classList.remove('is-anim'); void diffBox.offsetWidth; diffBox.classList.add('is-anim'); }
  $('.' + P + '__ctx').innerHTML = `<i aria-hidden="true">${it.note[0].split(' ').map((w) => w[0]).join('').slice(0, 2)}</i><div><small>${esc(it.note[0])} · ${esc(it.note[1])}</small><p>“${esc(it.note[2])}”</p></div>`;
  $('[data-k=stats]').innerHTML = `<span><i class="i-ins"></i>${a.nIns} word${a.nIns === 1 ? '' : 's'} they added</span><span><i class="i-del"></i>${a.nDel} of ours removed</span><span><i class="i-hot"></i>${a.hot} risk phrase${a.hot === 1 ? '' : 's'}</span>`;
  /* ladder */
  $('.' + P + '__rungs').innerHTML = T.rungs.map((txt, k) => {
    const d = assess(txt, it.text);
    const here = it.pos === k ? `<span class="here ok">Their draft is about here</span>` : '';
    return `<li class="${P}__rung" role="radio" tabindex="${k === r ? 0 : -1}" aria-checked="${k === r}" data-rung="${k}"><b>${RUNG[k]}<small>${Math.round(d.dist * 100)}% apart</small></b><span class="dist" aria-hidden="true"><span style="--w:${Math.max(3, d.dist * 100).toFixed(0)}%"></span></span>${here}</li>`;
  }).join('');
  $('[data-k=walk]').textContent = T.walk;
  root.classList.toggle('is-beyond', it.pos === 3);
  const walk = $('.' + P + '__walk');
  walk.querySelector('b').textContent = it.pos === 3 ? 'Past the walk-away line' : 'Walk-away';
  /* actions */
  $('[data-k=counterlbl]').textContent = `Counter with ${RUNG[r]}`;
  const acc = $('[data-do=accept]');
  if (it.pos === 3) { acc.setAttribute('aria-disabled', 'true'); acc.title = 'Their draft is past the walk-away line — counter or escalate'; }
  else { acc.removeAttribute('aria-disabled'); acc.title = 'Accept the counterparty wording as drafted'; }
  ['counter', 'escalate'].forEach((k) => { const b = $(`[data-do=${k}]`); b.removeAttribute('aria-disabled'); b.removeAttribute('title'); });
}

/* ---------- matrix + bars */
function renderMatrix() {
  const m = $('.' + P + '__matrix');
  let s = `<div role="row" style="display:contents"><div class="ch" role="columnheader">Contract</div>${TYPE_KEYS.map((k) => `<div class="ch" role="columnheader">${TYPES[k].name}</div>`).join('')}</div>`;
  let i = 0;
  CONTRACTS.forEach((c) => {
    s += `<div role="row" style="display:contents"><div class="rh" role="rowheader">${esc(c.name)}<small>${esc(c.doc)}</small></div>`;
    TYPE_KEYS.forEach((k) => {
      const it = ITEMS.find((x) => x.c === c.id && x.t === k);
      if (it) {
        const d = state.done[it.id];
        s += d ? `<button type="button" class="cell s-done" role="gridcell" style="--i:${i++}" data-open="${it.id}" aria-label="${esc(c.name)}, ${TYPES[k].name}: ${d.label}. Opens the decision log."><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 12.5 4.5 4.5L19 7.5"/></svg></button>`
          : `<button type="button" class="cell s-${it.sev}" role="gridcell" style="--i:${i++}" data-open="${it.id}" aria-label="${esc(c.name)}, ${TYPES[k].name}: ${SEVN[it.sev]}, score ${it.base.score}. Opens it for review.">${it.base.score}</button>`;
      } else if (c.types.includes(k)) s += `<div class="cell ok" role="gridcell" style="--i:${i++}" aria-label="${TYPES[k].name}: playbook wording"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 12.5 4 4 8-9"/></svg></div>`;
      else s += `<div class="cell na" role="gridcell" style="--i:${i++}" aria-label="${TYPES[k].name}: not in this document">·</div>`;
    });
    s += '</div>';
  });
  m.innerHTML = s;
  /* stacked bars: open deviations per clause type */
  const svg = $('.' + P + '__bars');
  const W = svg.clientWidth || 600, H = 190, L = 150, R = 30, rowH = (H - 26) / TYPE_KEYS.length;
  const counts = TYPE_KEYS.map((k) => ['high', 'med', 'low'].map((sv) => open().filter((x) => x.t === k && x.sev === sv).length));
  const max = Math.max(3, ...counts.map((c) => c[0] + c[1] + c[2]));
  const x = (v) => L + v / max * (W - L - R);
  let g = '';
  for (let v = 0; v <= max; v++) g += `<line class="gl" x1="${x(v)}" x2="${x(v)}" y1="0" y2="${H - 22}"/><text class="ax" x="${x(v)}" y="${H - 6}" text-anchor="middle">${v}</text>`;
  TYPE_KEYS.forEach((k, ri) => {
    const y = ri * rowH + 4, c = counts[ri];
    let acc = 0, segs = '';
    ['high', 'med', 'low'].forEach((sv, si) => { if (c[si]) { segs += `<rect class="seg s-${sv}" style="--i:${ri}" x="${x(acc) + (acc ? 1 : 0)}" y="${y + 4}" width="${x(acc + c[si]) - x(acc) - (acc ? 1 : 0)}" height="${rowH - 10}" rx="3"/>`; acc += c[si]; } });
    g += `<g class="row" data-k="${k}"><text class="lb" x="${L - 12}" y="${y + rowH / 2 + 3}" text-anchor="end">${TYPES[k].name}</text>${segs}<rect x="${L}" y="${y}" width="${W - L - R}" height="${rowH}" fill="transparent"/></g>`;
  });
  svg.setAttribute('viewBox', `0 0 ${W} ${H}`);
  svg.innerHTML = g;
}
$('.' + P + '__bars').addEventListener('pointermove', (e) => {
  const row = e.target.closest('.row');
  if (!row) { tip.hidden = true; return; }
  const k = row.dataset.k, o = open().filter((x) => x.t === k);
  tip.innerHTML = `<b>${TYPES[k].name}</b><span>${o.length} open · ${o.filter((x) => x.sev === 'high').length} high, ${o.filter((x) => x.sev === 'med').length} medium, ${o.filter((x) => x.sev === 'low').length} low</span>` + o.map((x) => `<span>${esc(CON[x.c].name)} · score ${x.base.score}</span>`).join('');
  tip.hidden = false;
  const r = root.getBoundingClientRect();
  tip.style.translate = Math.min(r.width - tip.offsetWidth - 8, e.clientX - r.left + 14) + 'px ' + Math.min(r.height - tip.offsetHeight - 8, e.clientY - r.top + 14) + 'px';
});
$('.' + P + '__bars').addEventListener('pointerleave', () => { tip.hidden = true; });

/* ---------- log */
function renderLog() {
  const ol = $('.' + P + '__log');
  ol.innerHTML = state.log.map((e) => {
    const it = ITEMS.find((x) => x.id === e.id);
    return `<li class="${P}__entry" data-id="${e.id}"><time>${e.time}</time><span><b>${esc(CON[it.c].name)} · ${TYPES[it.t].name}</b><small>${esc(e.note)}</small></span><span class="tag ${e.act}">${e.label}</span><button type="button" data-undo="${e.id}">Undo</button></li>`;
  }).join('');
  const n = state.log.length;
  $('[data-k=logsum]').textContent = n ? `${n} decision${n === 1 ? '' : 's'} · ${state.log.filter((e) => e.act === 'escalate').length} escalated` : '';
}

/* ---------- decisions */
function decide(act) {
  const it = ITEMS.find((x) => x.id === state.sel); if (!it) return;
  const btn = $(`[data-do=${act}]`);
  if (btn.getAttribute('aria-disabled') === 'true') { toast(btn.title || 'Not available for this clause'); return; }
  const r = rungOf(it);
  const label = act === 'counter' ? `Countered · ${RUNG[r]}` : act === 'accept' ? 'Accepted as drafted' : 'Escalated to GC';
  const note = act === 'counter' ? `Sent ${RUNG[r].toLowerCase()} wording back to ${CON[it.c].name}` : act === 'accept' ? `Their §${it.sec} wording stands` : `Past walk-away: ${TYPES[it.t].walk.split(' — ')[0].split(';')[0]}`;
  state.clock += 3 + (state.log.length * 7) % 5;
  state.done[it.id] = { act, label };
  state.log.unshift({ id: it.id, act, label, note, time: hhmm(state.clock) });
  /* select the next clause in reading order */
  const ids = $$('[role=option]', list).map((o) => o.dataset.id), i = ids.indexOf(it.id);
  const next = ids.slice(i + 1).concat(ids.slice(0, i).reverse()).find((id) => !state.done[id]);
  state.sel = next || null;
  renderQueue(true); renderReview(true); renderLog();
  toast(`${CON[it.c].name} · ${TYPES[it.t].short}: ${label.toLowerCase()}`);
  const o = $(`[role=option][aria-selected=true]`, list); if (o) o.focus({ preventScroll: true });
}
function select(id, focus) {
  state.sel = id;
  $$('[role=option]', list).forEach((o) => { const on = o.dataset.id === id; o.setAttribute('aria-selected', String(on)); o.tabIndex = on ? 0 : -1; if (on && focus) { o.focus({ preventScroll: true }); o.scrollIntoView({ block: 'nearest' }); } });
  renderReview(true);
}
function setView(v) {
  state.view = v;
  $$('.' + P + '__rail button').forEach((b) => (b.dataset.view === v ? b.setAttribute('aria-current', 'page') : b.removeAttribute('aria-current')));
  $$('.' + P + '__view').forEach((s) => { s.hidden = s.dataset.view !== v; });
  tip.hidden = true;
  if (v === 'matrix') renderMatrix();
  if (v === 'log') renderLog();
}

root.addEventListener('click', (e) => {
  const t = e.target;
  const nav = t.closest('.' + P + '__rail button');
  if (nav) { setView(nav.dataset.view); return; }
  const sev = t.closest('[data-sev]');
  if (sev) {
    state.sev = sev.dataset.sev;
    $$('[data-sev]').forEach((b) => { const on = b === sev; b.setAttribute('aria-checked', String(on)); b.tabIndex = on ? 0 : -1; });
    renderQueue(true); renderReview(true);
    return;
  }
  const opt = t.closest('[role=option]');
  if (opt) { select(opt.dataset.id); return; }
  const mode = t.closest('[data-mode]');
  if (mode) {
    state.mode = mode.dataset.mode;
    $$('[data-mode]').forEach((b) => { const on = b === mode; b.setAttribute('aria-checked', String(on)); b.tabIndex = on ? 0 : -1; });
    renderReview(true);
    return;
  }
  const rung = t.closest('[data-rung]');
  if (rung) { state.rung[state.sel] = +rung.dataset.rung; renderReview(true); const f = $(`[data-rung="${rung.dataset.rung}"]`); if (f) f.focus({ preventScroll: true }); return; }
  const d = t.closest('[data-do]');
  if (d) { decide(d.dataset.do); return; }
  const cell = t.closest('[data-open]');
  if (cell) {
    const id = cell.dataset.open;
    if (state.done[id]) { setView('log'); const li = $(`.${P}__entry[data-id="${id}"]`); if (li) { li.animate([{ boxShadow: `0 0 0 2px var(--${P}-amber)` }, { boxShadow: '0 0 0 0 transparent' }], { duration: 1200 }); li.querySelector('button').focus({ preventScroll: true }); } return; }
    state.sev = 'all';
    $$('[data-sev]').forEach((b) => { const on = b.dataset.sev === 'all'; b.setAttribute('aria-checked', String(on)); b.tabIndex = on ? 0 : -1; });
    state.sel = id; setView('queue'); renderQueue(); renderReview(true);
    const o = $(`[data-id="${id}"]`, list); if (o) { o.focus({ preventScroll: true }); o.scrollIntoView({ block: 'nearest' }); }
    return;
  }
  const u = t.closest('[data-undo]');
  if (u) {
    const id = u.dataset.undo;
    delete state.done[id];
    state.log = state.log.filter((x) => x.id !== id);
    if (!state.sel) state.sel = id;
    renderQueue(); renderReview(); renderLog();
    toast('Decision undone · back in the queue');
  }
});
root.addEventListener('keydown', (e) => {
  if (e.target.closest && e.target.closest('input, textarea, select')) return;
  const opt = e.target.closest && e.target.closest('[role=option]');
  const ids = $$('[role=option]', list).map((o) => o.dataset.id);
  const step = (d) => { const i = ids.indexOf(state.sel); const n = ids[Math.max(0, Math.min(ids.length - 1, i + d))]; if (n && n !== state.sel) select(n, true); };
  if (opt && (e.key === 'ArrowDown' || e.key === 'ArrowUp')) { e.preventDefault(); step(e.key === 'ArrowDown' ? 1 : -1); return; }
  if (opt && (e.key === 'Home' || e.key === 'End')) { e.preventDefault(); select(e.key === 'Home' ? ids[0] : ids[ids.length - 1], true); return; }
  const rr = e.target.closest && e.target.closest('[role=radio]');
  if (rr && /^Arrow/.test(e.key)) {
    const all = $$('[role=radio]', rr.parentElement), i = all.indexOf(rr);
    const n = all[(i + (/Right|Down/.test(e.key) ? 1 : all.length - 1)) % all.length];
    e.preventDefault(); n.click(); n.focus();
    return;
  }
  if (state.view !== 'queue' || e.metaKey || e.ctrlKey || e.altKey) return;
  const k = e.key.toLowerCase();
  if (k === 'j' || k === 'k') { e.preventDefault(); step(k === 'j' ? 1 : -1); }
  else if (k === 'c' || k === 'a' || k === 'e') { e.preventDefault(); decide({ c: 'counter', a: 'accept', e: 'escalate' }[k]); }
});

/* ---------- mount */
renderQueue(); renderReview(true);
let rz = 0, lastW = root.clientWidth;
const ro = new ResizeObserver(() => {
  cancelAnimationFrame(rz);
  rz = requestAnimationFrame(() => {
    if (!root.isConnected) { ro.disconnect(); return; }
    if (root.clientWidth !== lastW) { lastW = root.clientWidth; if (state.view === 'matrix') renderMatrix(); }
  });
});
ro.observe(root);

css:
.dlo-renew {
  /* re-theme with these four */
  --dlo-renew-bg: oklch(0.973 0.011 140);
  --dlo-renew-ink: oklch(0.255 0.03 165);
  --dlo-renew-green: oklch(0.5 0.095 158);
  --dlo-renew-saffron: oklch(0.79 0.15 76);
  /* derived */
  --dlo-renew-brick: oklch(0.56 0.16 31);
  --dlo-renew-card: color-mix(in oklch, var(--dlo-renew-bg) 35%, white);
  --dlo-renew-side: color-mix(in oklch, var(--dlo-renew-bg) 93%, var(--dlo-renew-green));
  --dlo-renew-line: color-mix(in oklch, var(--dlo-renew-ink) 12%, transparent);
  --dlo-renew-hair: color-mix(in oklch, var(--dlo-renew-ink) 6.5%, transparent);
  --dlo-renew-wash: color-mix(in oklch, var(--dlo-renew-ink) 4%, transparent);
  --dlo-renew-mute: color-mix(in oklch, var(--dlo-renew-ink) 62%, var(--dlo-renew-bg));
  --dlo-renew-faint: color-mix(in oklch, var(--dlo-renew-ink) 40%, var(--dlo-renew-bg));
  --dlo-renew-term: color-mix(in oklab, var(--dlo-renew-green) 30%, var(--dlo-renew-card));
  --dlo-renew-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dlo-renew-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dlo-renew-out: cubic-bezier(.2, .9, .25, 1);
  --dlo-renew-spring: linear(0, 0.01, 0.04 2.2%, 0.163 4.8%, 0.664 13%, 0.887 17.7%, 1.006 22.1%, 1.059 25.9%, 1.077 29.5%, 1.068 33.4%, 1.015 43.4%, 0.994 50.7%, 0.995 62.9%, 1);
  --dlo-renew-lw: 262px;

  width: 100%;
  height: var(--dlo-renew-h, 680px);
  container-type: inline-size; container-name: dlo-renew;
  position: relative; isolation: isolate; overflow: hidden;
  border-radius: 14px;
  background: var(--dlo-renew-bg); color: var(--dlo-renew-ink);
  font: 13px/1.45 var(--dlo-renew-sans);
  accent-color: var(--dlo-renew-green);
  color-scheme: light;
  box-shadow: inset 0 0 0 1px var(--dlo-renew-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, h4, p, dl, dd, ol, table) { margin: 0; padding: 0; }
  & :where(ol) { list-style: none; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
  & :where(svg) { display: block; }
  & :focus-visible { outline: 2px solid var(--dlo-renew-green); outline-offset: 2px; border-radius: 6px; }
  & .dlo-renew__scroll {
    overflow: auto; overscroll-behavior: contain;
    scrollbar-width: thin; scrollbar-color: color-mix(in oklch, var(--dlo-renew-ink) 22%, transparent) transparent;
  }
}
.dlo-renew__shell { height: 100%; display: grid; grid-template-columns: 196px minmax(0, 1fr); grid-template-areas: "side main"; }

/* ---------- side */
.dlo-renew__side {
  grid-area: side; min-height: 0; display: flex; flex-direction: column; gap: 18px; padding: 18px 12px 14px;
  background: var(--dlo-renew-side); border-right: 1px solid var(--dlo-renew-line); overflow: auto; scrollbar-width: none;
}
.dlo-renew__brand {
  display: flex; align-items: center; gap: 10px; padding: 0 4px;
  & svg { width: 32px; height: 32px; flex: none; padding: 6px; border-radius: 50%; background: var(--dlo-renew-green); fill: none; stroke: var(--dlo-renew-card); stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
  & b { display: block; font-size: 14px; font-weight: 720; letter-spacing: -.015em; line-height: 1.15; }
  & small { display: block; font-size: 11px; color: var(--dlo-renew-mute); }
}
.dlo-renew__nav {
  display: grid; gap: 2px;
  & button { display: flex; align-items: center; gap: 10px; padding: 8px 10px; border-radius: 9px; color: var(--dlo-renew-mute); font-weight: 580; transition: background-color .2s, color .2s; }
  & button:hover { background: var(--dlo-renew-wash); color: var(--dlo-renew-ink); }
  & button[aria-current=page] { background: var(--dlo-renew-card); color: var(--dlo-renew-ink); box-shadow: 0 0 0 1px var(--dlo-renew-line), 0 1px 3px var(--dlo-renew-hair); }
  & svg { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  & button[aria-current=page] svg { stroke: var(--dlo-renew-green); }
}
.dlo-renew__types {
  display: flex; flex-wrap: wrap; gap: 5px; padding: 0 2px;
  & p { width: 100%; font-size: 10.5px; font-weight: 650; letter-spacing: .09em; text-transform: uppercase; color: var(--dlo-renew-faint); margin-bottom: 2px; }
  & button { padding: 4px 10px; border-radius: 99px; font-size: 12px; font-weight: 600; color: var(--dlo-renew-mute); box-shadow: inset 0 0 0 1px var(--dlo-renew-line); background: var(--dlo-renew-card); transition: background-color .2s, color .2s, box-shadow .2s; }
  & button:hover { color: var(--dlo-renew-ink); }
  & button[aria-pressed=true] { background: var(--dlo-renew-ink); color: var(--dlo-renew-card); box-shadow: none; }
  & small { font: 600 10.5px var(--dlo-renew-mono); opacity: .7; margin-left: 4px; }
}
.dlo-renew__key {
  margin-top: auto; display: grid; gap: 6px; padding: 0 4px; font-size: 11.5px; color: var(--dlo-renew-mute);
  & p { font-size: 10.5px; font-weight: 650; letter-spacing: .09em; text-transform: uppercase; color: var(--dlo-renew-faint); }
  & span { display: flex; align-items: center; gap: 8px; }
  & i { width: 22px; height: 9px; border-radius: 3px; flex: none; }
  & .k-term { background: var(--dlo-renew-term); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dlo-renew-green) 30%, transparent); }
  & .k-win { background: repeating-linear-gradient(135deg, var(--dlo-renew-saffron) 0 2px, transparent 2px 5px); box-shadow: inset 0 0 0 1px var(--dlo-renew-saffron); }
  & .k-dl { width: 9px; height: 9px; border-radius: 1px; transform: rotate(45deg) scale(.85); background: var(--dlo-renew-ink); margin: 0 6px; }
  & .k-auto { background: color-mix(in oklch, var(--dlo-renew-brick) 18%, transparent); box-shadow: inset 0 0 0 1px var(--dlo-renew-brick); }
}

/* ---------- main */
.dlo-renew__main { grid-area: main; min-width: 0; min-height: 0; display: grid; grid-template-columns: minmax(0, 1fr); grid-template-rows: auto auto auto minmax(0, 1fr); }
.dlo-renew__head { display: flex; align-items: flex-end; justify-content: space-between; gap: 16px; padding: 16px 20px 10px; flex-wrap: wrap; }
.dlo-renew__title {
  & p { font-size: 11px; font-weight: 600; letter-spacing: .07em; text-transform: uppercase; color: var(--dlo-renew-green); }
  & h2 { font-size: clamp(19px, 2.3cqi, 25px); font-weight: 720; letter-spacing: -.025em; line-height: 1.1; text-wrap: balance; }
}
.dlo-renew__asof {
  display: flex; align-items: center; gap: 10px; padding: 6px 8px 6px 6px; border-radius: 12px; background: var(--dlo-renew-card); box-shadow: 0 0 0 1px var(--dlo-renew-line);
  & label { display: grid; gap: 2px; font-size: 11px; color: var(--dlo-renew-mute); }
  & b { color: var(--dlo-renew-ink); font-weight: 650; font-variant-numeric: tabular-nums; }
  & input { width: 200px; margin: 0; cursor: ew-resize; }
}
.dlo-renew__play {
  display: grid; place-items: center; width: 34px; height: 34px; border-radius: 9px; background: var(--dlo-renew-ink); color: var(--dlo-renew-card);
  transition: background-color .2s, transform .25s var(--dlo-renew-spring);
  &:hover { background: var(--dlo-renew-green); }
  &:active { transform: scale(.92); }
  & svg { width: 16px; height: 16px; fill: currentColor; stroke: currentColor; stroke-width: 2.2; stroke-linecap: round; stroke-linejoin: round; }
  & .pa { display: none; fill: none; }
  &[aria-pressed=true] .pl { display: none; }
  &[aria-pressed=true] .pa { display: block; }
}
.dlo-renew__reset { padding: 6px 10px; border-radius: 8px; font-size: 12px; font-weight: 650; color: var(--dlo-renew-mute); box-shadow: inset 0 0 0 1px var(--dlo-renew-line); &:hover { color: var(--dlo-renew-ink); background: var(--dlo-renew-wash); } }
.dlo-renew__reset[aria-disabled=true] { opacity: .45; cursor: not-allowed; }

.dlo-renew__kpis {
  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 10px; padding: 0 20px 10px;
  & > div { padding: 9px 13px; border-radius: 11px; background: var(--dlo-renew-card); box-shadow: 0 0 0 1px var(--dlo-renew-line); min-width: 0; transition: box-shadow .3s; }
  & dt { font-size: 11px; font-weight: 600; color: var(--dlo-renew-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & dd { margin: 0; display: flex; align-items: baseline; gap: 8px; font-size: clamp(18px, 2.1cqi, 23px); font-weight: 720; letter-spacing: -.025em; font-variant-numeric: tabular-nums; line-height: 1.25; }
  & dd small { font-size: 11.5px; font-weight: 600; letter-spacing: 0; color: var(--dlo-renew-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .is-hot { box-shadow: 0 0 0 1px color-mix(in oklch, var(--dlo-renew-brick) 45%, transparent), 0 0 0 4px color-mix(in oklch, var(--dlo-renew-brick) 9%, transparent); }
  & .is-hot dd { color: var(--dlo-renew-brick); }
}

/* lifecycle strip: chevrons */
.dlo-renew__life {
  display: flex; gap: 3px; padding: 0 20px 12px; min-width: 0;
  & li { flex: 1 1 0; min-width: 0; display: flex; }
  & button {
    flex: 1; min-width: 0; display: grid; grid-template-columns: auto minmax(0, 1fr); align-items: baseline; gap: 0 8px; padding: 6px 14px 6px 18px;
    background: var(--dlo-renew-card); box-shadow: inset 0 0 0 1px var(--dlo-renew-line);
    clip-path: polygon(0 0, calc(100% - 10px) 0, 100% 50%, calc(100% - 10px) 100%, 0 100%, 10px 50%);
    transition: background-color .2s, color .2s;
  }
  & li:first-child button { clip-path: polygon(0 0, calc(100% - 10px) 0, 100% 50%, calc(100% - 10px) 100%, 0 100%); padding-left: 12px; border-radius: 8px 0 0 8px; }
  & button:hover { background: color-mix(in oklab, var(--dlo-renew-green) 10%, var(--dlo-renew-card)); }
  & b { font: 700 16px var(--dlo-renew-sans); font-variant-numeric: tabular-nums; letter-spacing: -.02em; }
  & span { font-size: 11.5px; font-weight: 600; color: var(--dlo-renew-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .is-active button { background: color-mix(in oklab, var(--dlo-renew-green) 16%, var(--dlo-renew-card)); }
  & .is-due button { background: color-mix(in oklab, var(--dlo-renew-saffron) 26%, var(--dlo-renew-card)); }
  & b.bump { animation: dlo-renew-bump .6s var(--dlo-renew-spring); }
}

.dlo-renew__views { position: relative; min-height: 0; padding: 0 20px 16px; }
.dlo-renew__view { height: 100%; min-height: 0; }
.dlo-renew__view[hidden] { display: none; }

/* ---------- runway board: one grid, subgrid rows share the label + timeline columns */
.dlo-renew__rw { border-radius: 12px; background: var(--dlo-renew-card); box-shadow: 0 0 0 1px var(--dlo-renew-line); overflow: hidden; }
.dlo-renew__board {
  height: 100%; position: relative;
  display: grid; grid-template-columns: var(--dlo-renew-lw) minmax(0, 1fr); align-content: start;
}
.dlo-renew__chartrow, .dlo-renew__axis, .dlo-renew__row { grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; }
.dlo-renew__chartrow { padding-top: 10px; position: sticky; top: 0; z-index: 3; background: var(--dlo-renew-card); border-bottom: 1px solid var(--dlo-renew-line); }
.dlo-renew__chartlbl {
  padding: 4px 14px 8px 16px; display: grid; align-content: start; gap: 2px;
  & b { font-size: 12.5px; font-weight: 680; }
  & span { font-size: 11px; color: var(--dlo-renew-faint); text-wrap: pretty; }
}
.dlo-renew__chip {
  justify-self: start; margin-top: 6px; display: inline-flex; align-items: center; gap: 6px; padding: 3px 8px 3px 10px; border-radius: 99px;
  font-size: 11.5px; font-weight: 650; background: var(--dlo-renew-ink); color: var(--dlo-renew-card);
  &::after { content: "×"; font-size: 14px; line-height: 1; opacity: .7; }
  &:hover::after { opacity: 1; }
}
.dlo-renew__chip[hidden] { display: none; }
.dlo-renew__var {
  width: calc(100% - 16px); margin-right: 16px; height: 104px; overflow: visible;
  & .ax { font: 500 9.5px var(--dlo-renew-mono); fill: var(--dlo-renew-faint); font-variant-numeric: tabular-nums; }
  & .ml { font: 650 10px var(--dlo-renew-sans); fill: var(--dlo-renew-mute); letter-spacing: .04em; text-transform: uppercase; }
  & .gl { stroke: var(--dlo-renew-hair); }
  & .mo { cursor: pointer; outline: none; }
  & .mo .hit { fill: transparent; }
  & .mo:hover .hit, & .mo:focus-visible .hit { fill: var(--dlo-renew-wash); }
  & .mo.is-sel .hit { fill: color-mix(in oklch, var(--dlo-renew-green) 12%, transparent); }
  & .mo:focus-visible .hit { stroke: var(--dlo-renew-green); stroke-width: 1.5; }
  & .seg { transform-box: fill-box; transform-origin: 50% 100%; transition: y .5s var(--dlo-renew-out), height .5s var(--dlo-renew-out); }
  & .s-open { fill: var(--dlo-renew-saffron); }
  & .s-dec { fill: var(--dlo-renew-green); }
  & .s-miss { fill: var(--dlo-renew-brick); }
  & .asof { stroke: var(--dlo-renew-ink); stroke-width: 1.5; }
}
.dlo-renew.is-enter .dlo-renew__var .seg { animation: dlo-renew-grow .8s var(--dlo-renew-out) both; animation-delay: calc(var(--i) * 45ms + 100ms); }

.dlo-renew__rows { grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; position: relative; }
.dlo-renew__row {
  position: relative; min-height: 38px; border-bottom: 1px solid var(--dlo-renew-hair); cursor: pointer;
  transition: background-color .15s, opacity .3s;
  &:hover { background: var(--dlo-renew-wash); }
  &[aria-selected=true] { background: color-mix(in oklab, var(--dlo-renew-green) 8%, var(--dlo-renew-card)); box-shadow: inset 3px 0 0 var(--dlo-renew-green); }
  &:focus-visible { outline-offset: -2px; }
  &.is-dim { opacity: .3; }
  .dlo-renew.is-enter & { animation: dlo-renew-fade .6s var(--dlo-renew-out) both; animation-delay: calc(var(--i) * 35ms + 200ms); }
}
.dlo-renew__lbl {
  display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; gap: 0 8px; padding: 5px 10px 5px 16px; min-width: 0;
  & b { font-size: 12.5px; font-weight: 640; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & small { grid-column: 1; font-size: 11px; color: var(--dlo-renew-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
}
.dlo-renew__alert {
  grid-row: span 2; grid-column: 2; font: 650 10.5px var(--dlo-renew-sans); padding: 2px 7px; border-radius: 99px; white-space: nowrap;
  background: var(--dlo-renew-wash); color: var(--dlo-renew-mute);
  &.a-due { background: var(--dlo-renew-brick); color: var(--dlo-renew-card); }
  &.a-win { background: color-mix(in oklch, var(--dlo-renew-saffron) 35%, transparent); color: color-mix(in oklab, var(--dlo-renew-saffron) 35%, var(--dlo-renew-ink)); }
  &.a-miss { background: color-mix(in oklch, var(--dlo-renew-brick) 14%, transparent); color: var(--dlo-renew-brick); }
  &.a-ok { background: color-mix(in oklch, var(--dlo-renew-green) 14%, transparent); color: var(--dlo-renew-green); }
  &.a-pop { animation: dlo-renew-bump .6s var(--dlo-renew-spring); }
}
.dlo-renew__track { position: relative; margin-right: 16px; }
.dlo-renew__track > * { position: absolute; top: 50%; }
.dlo-renew__term {
  height: 14px; translate: 0 -50%; border-radius: 4px; background: var(--dlo-renew-term); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dlo-renew-green) 30%, transparent);
  &.cut { border-radius: 0 4px 4px 0; -webkit-mask: linear-gradient(90deg, transparent, black 26px); mask: linear-gradient(90deg, transparent, black 26px); }
  &.over { border-radius: 4px 0 0 4px; }
  &.is-noticed { background: repeating-linear-gradient(90deg, var(--dlo-renew-term) 0 6px, transparent 6px 8px); }
}
.dlo-renew__win {
  height: 22px; translate: 0 -50%; border-radius: 4px;
  background: repeating-linear-gradient(135deg, color-mix(in oklch, var(--dlo-renew-saffron) 70%, transparent) 0 2px, transparent 2px 6px);
  box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dlo-renew-saffron) 80%, transparent);
}
.dlo-renew__dl {
  width: 11px; height: 11px; translate: -50% -50%; rotate: 45deg; border-radius: 2px; background: var(--dlo-renew-ink); box-shadow: 0 0 0 2px var(--dlo-renew-card);
  &.is-hot { background: var(--dlo-renew-brick); animation: dlo-renew-ping 1.8s var(--dlo-renew-out) infinite; }
  &.is-done { background: var(--dlo-renew-green); }
}
.dlo-renew__ext {
  height: 14px; translate: 0 -50%; border-radius: 0 4px 4px 0; transform-origin: 0 50%;
  background: color-mix(in oklch, var(--dlo-renew-brick) 16%, transparent); box-shadow: inset 0 0 0 1px var(--dlo-renew-brick);
  &.is-planned { background: repeating-linear-gradient(90deg, color-mix(in oklch, var(--dlo-renew-green) 25%, transparent) 0 6px, transparent 6px 9px); box-shadow: inset 0 0 0 1px var(--dlo-renew-green); }
  &.is-new { animation: dlo-renew-extend .9s var(--dlo-renew-out) both; }
}
.dlo-renew__end {
  width: 3px; height: 22px; translate: -50% -50%; border-radius: 2px; background: var(--dlo-renew-ink);
  &.is-exp { background: var(--dlo-renew-faint); }
}
.dlo-renew__chartrow { grid-row: 1; }
.dlo-renew__rows { grid-row: 2; }
.dlo-renew__grid { grid-column: 2; grid-row: 1 / 3; position: relative; margin-right: 16px; pointer-events: none; z-index: 0; }
.dlo-renew__grid.is-now { z-index: 2; }
.dlo-renew__grid i { position: absolute; top: 0; bottom: 0; width: 1px; background: var(--dlo-renew-hair); }
.dlo-renew__now { position: absolute; top: 0; bottom: 0; width: 2px; margin-left: -1px; background: var(--dlo-renew-ink); z-index: 4; }
.dlo-renew__now::before { content: ""; position: absolute; top: 0; left: -4px; width: 10px; height: 10px; border-radius: 50%; background: var(--dlo-renew-ink); }
.dlo-renew__row, .dlo-renew__chartrow { z-index: 1; }

/* ---------- register */
.dlo-renew__rg { display: grid; grid-template-rows: auto minmax(0, 1fr); gap: 10px; }
.dlo-renew__rgbar { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.dlo-renew__rgbar .dlo-renew__chip { margin: 0; }
.dlo-renew__search {
  flex: 1 1 260px; max-width: 380px; display: flex; align-items: center; gap: 8px; padding: 0 12px; height: 34px; border-radius: 10px; background: var(--dlo-renew-card); box-shadow: 0 0 0 1px var(--dlo-renew-line);
  &:focus-within { box-shadow: 0 0 0 2px var(--dlo-renew-green); }
  & svg { width: 16px; height: 16px; fill: none; stroke: var(--dlo-renew-faint); stroke-width: 1.8; stroke-linecap: round; flex: none; }
  & input { flex: 1; min-width: 0; border: 0; background: none; font: inherit; color: inherit; outline: none; }
}
.dlo-renew__count { margin-left: auto; font-size: 12px; color: var(--dlo-renew-mute); font-variant-numeric: tabular-nums; }
.dlo-renew__tablewrap { border-radius: 12px; background: var(--dlo-renew-card); box-shadow: 0 0 0 1px var(--dlo-renew-line); }
.dlo-renew__table {
  width: 100%; border-collapse: separate; border-spacing: 0; font-variant-numeric: tabular-nums;
  & th { position: sticky; top: 0; z-index: 1; background: var(--dlo-renew-card); text-align: left; font-size: 11px; font-weight: 600; color: var(--dlo-renew-mute); border-bottom: 1px solid var(--dlo-renew-line); padding: 0; white-space: nowrap; }
  & th:last-child, & td:last-child { text-align: right; }
  & th button { display: inline-flex; align-items: center; gap: 4px; padding: 10px 12px 8px; }
  & th button:hover, & th[aria-sort=ascending] button, & th[aria-sort=descending] button { color: var(--dlo-renew-ink); }
  & th button::after { content: ""; width: 6px; height: 6px; border: solid currentColor; border-width: 0 1.5px 1.5px 0; opacity: 0; transform: rotate(45deg) translateY(-2px); transition: transform .3s var(--dlo-renew-spring), opacity .2s; }
  & th[aria-sort=descending] button::after { opacity: 1; }
  & th[aria-sort=ascending] button::after { opacity: 1; transform: rotate(-135deg) translateY(-2px); }
  & td { padding: 8px 12px; border-bottom: 1px solid var(--dlo-renew-hair); font-size: 12.5px; white-space: nowrap; }
  & td b { display: block; font-weight: 630; }
  & td small { display: block; font-size: 11px; color: var(--dlo-renew-faint); }
  & tbody tr { cursor: pointer; transition: background-color .15s; }
  & tbody tr:hover { background: var(--dlo-renew-wash); }
  & tbody tr:focus-visible { outline: 2px solid var(--dlo-renew-green); outline-offset: -2px; }
}
.dlo-renew__stage { display: inline-flex; align-items: center; gap: 6px; font-size: 12px; font-weight: 600; & i { width: 7px; height: 7px; border-radius: 50%; background: var(--c, var(--dlo-renew-faint)); } }
@supports (animation-timeline: view()) {
  .dlo-renew__table tbody tr { animation: dlo-renew-fade linear both; animation-timeline: view(); animation-range: entry 0% entry 60%; }
}

/* ---------- drawer */
.dlo-renew__drawer {
  position: absolute; z-index: 6; inset: 10px 10px 10px auto; width: min(360px, calc(100% - 20px)); display: flex; flex-direction: column; border-radius: 14px;
  background: var(--dlo-renew-card); box-shadow: 0 0 0 1px var(--dlo-renew-line), 0 30px 60px -24px color-mix(in oklch, var(--dlo-renew-ink) 45%, transparent);
  transform: translateX(calc(100% + 24px)); opacity: 0; visibility: hidden;
  transition: transform .5s var(--dlo-renew-out), opacity .3s, visibility 0s .5s;
  &[data-open] { transform: none; opacity: 1; visibility: visible; transition: transform .5s var(--dlo-renew-out), opacity .2s, visibility 0s; }
}
.dlo-renew__dbody { flex: 1; min-height: 0; overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; padding: 16px 18px; display: grid; align-content: start; gap: 14px; }
.dlo-renew__dtop {
  display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 10px;
  & p { font-size: 11px; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; color: var(--dlo-renew-green); }
  & h3 { font-size: 18px; font-weight: 720; letter-spacing: -.02em; line-height: 1.15; text-wrap: balance; margin-top: 3px; }
  & h3 small { display: block; font-size: 12.5px; font-weight: 500; letter-spacing: 0; color: var(--dlo-renew-mute); margin-top: 2px; }
}
.dlo-renew__x { display: grid; place-items: center; width: 30px; height: 30px; border-radius: 8px; color: var(--dlo-renew-mute); &:hover { background: var(--dlo-renew-wash); color: var(--dlo-renew-ink); } & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; } }
.dlo-renew__facts {
  display: grid; grid-template-columns: 1fr 1fr; gap: 1px; border-radius: 10px; overflow: hidden; background: var(--dlo-renew-line); margin: 0;
  & div { background: var(--dlo-renew-card); padding: 8px 10px; }
  & dt { font-size: 10.5px; color: var(--dlo-renew-mute); }
  & dd { margin: 0; font-weight: 650; font-size: 13px; font-variant-numeric: tabular-nums; }
}
.dlo-renew__steps {
  display: grid; gap: 0; margin: 0; padding: 0 0 0 14px; position: relative;
  &::before { content: ""; position: absolute; left: 4px; top: 6px; bottom: 6px; width: 2px; background: var(--dlo-renew-line); }
  & li { position: relative; padding: 5px 0; font-size: 12px; display: flex; justify-content: space-between; gap: 8px; }
  & li::before { content: ""; position: absolute; left: -14px; top: 9px; width: 10px; height: 10px; border-radius: 50%; background: var(--dlo-renew-card); box-shadow: inset 0 0 0 2px var(--dlo-renew-faint); }
  & li.done::before { background: var(--dlo-renew-green); box-shadow: none; }
  & li.hot::before { background: var(--dlo-renew-brick); box-shadow: none; }
  & li span:last-child { font: 600 11.5px var(--dlo-renew-mono); color: var(--dlo-renew-mute); }
}
.dlo-renew__acts {
  display: grid; gap: 6px;
  & button { padding: 10px 12px; border-radius: 9px; font-weight: 650; text-align: center; box-shadow: inset 0 0 0 1px var(--dlo-renew-line); transition: background-color .2s, transform .2s var(--dlo-renew-spring); }
  & button:hover { background: var(--dlo-renew-wash); }
  & button:active { transform: scale(.98); }
  & .pri { background: var(--dlo-renew-ink); color: var(--dlo-renew-card); box-shadow: none; }
  & .pri:hover { background: color-mix(in oklab, var(--dlo-renew-ink) 85%, var(--dlo-renew-green)); }
  & button[aria-disabled=true] { opacity: .45; cursor: not-allowed; transform: none; }
}
.dlo-renew__dnote { font-size: 12px; color: var(--dlo-renew-mute); text-wrap: pretty; & b { color: var(--dlo-renew-ink); } }

/* ---------- tooltip + toasts */
.dlo-renew__tip {
  position: absolute; z-index: 8; left: 0; top: 0; pointer-events: none; max-width: 260px; padding: 8px 10px; border-radius: 9px;
  background: var(--dlo-renew-ink); color: var(--dlo-renew-card); font-size: 11.5px; box-shadow: 0 12px 30px -12px color-mix(in oklch, var(--dlo-renew-ink) 60%, transparent);
  & b { display: block; font-weight: 700; }
  & span { display: block; opacity: .8; font-variant-numeric: tabular-nums; }
}
.dlo-renew__toasts { position: absolute; z-index: 9; right: 16px; bottom: 16px; display: grid; gap: 6px; justify-items: end; pointer-events: none; }
.dlo-renew__toast {
  padding: 9px 14px; border-radius: 10px; background: var(--dlo-renew-ink); color: var(--dlo-renew-card); font-size: 12px; font-weight: 600; max-width: 340px;
  box-shadow: 0 14px 30px -14px color-mix(in oklch, var(--dlo-renew-ink) 70%, transparent);
  transition: opacity .3s, transform .45s var(--dlo-renew-spring);
  @starting-style { opacity: 0; transform: translateY(10px) scale(.96); }
  &.is-out { opacity: 0; transform: translateX(10px); }
  &.is-bad { background: var(--dlo-renew-brick); }
}

@keyframes dlo-renew-grow { from { transform: scaleY(0); } }
@keyframes dlo-renew-fade { from { opacity: 0; transform: translateY(4px); } }
@keyframes dlo-renew-extend { from { transform: scaleX(0); opacity: .3; } }
@keyframes dlo-renew-bump { 30% { transform: scale(1.18); } }
@keyframes dlo-renew-ping { 0% { box-shadow: 0 0 0 2px var(--dlo-renew-card), 0 0 0 2px color-mix(in oklch, var(--dlo-renew-brick) 60%, transparent); } 70%, 100% { box-shadow: 0 0 0 2px var(--dlo-renew-card), 0 0 0 9px transparent; } }

/* ---------- responsive */
@container dlo-renew (width < 960px) {
  .dlo-renew__board { --dlo-renew-lw: 200px; }
  .dlo-renew__shell { grid-template-columns: 168px minmax(0, 1fr); }
  .dlo-renew__key { display: none; }
  .dlo-renew__kpis { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .dlo-renew__life span { font-size: 10px; letter-spacing: .02em; }
  .dlo-renew__life button { grid-template-columns: minmax(0, 1fr); justify-items: center; padding-block: 4px; line-height: 1.2; }
  .dlo-renew__life b { font-size: 14px; }
}
@container dlo-renew (width < 760px) {
  .dlo-renew__board { --dlo-renew-lw: 168px; }
  .dlo-renew__shell { grid-template-columns: minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); grid-template-areas: "side" "main"; }
  .dlo-renew__side { flex-direction: row; align-items: center; gap: 10px; padding: 8px 12px; overflow-x: auto; border-right: 0; border-bottom: 1px solid var(--dlo-renew-line); }
  .dlo-renew__brand span, .dlo-renew__types p { display: none; }
  .dlo-renew__brand { padding: 0; }
  .dlo-renew__nav { display: flex; & span { display: none; } & button { padding: 8px; } }
  .dlo-renew__types { flex-wrap: nowrap; & button { flex: none; } }
  .dlo-renew__main { overflow: auto; scrollbar-width: thin; grid-template-rows: max-content max-content max-content 560px; }
  .dlo-renew__head { padding: 12px 14px 8px; }
  .dlo-renew__asof { flex: 1 1 100%; & label { flex: 1; } & input { width: 100%; } }
  .dlo-renew__kpis, .dlo-renew__life { padding-inline: 14px; }
  .dlo-renew__views { padding: 0 14px 14px; }
  .dlo-renew__board { min-width: 600px; }
  .dlo-renew__rw { overflow: auto; }
  .dlo-renew__lbl small, .dlo-renew__chartlbl span { display: none; }
  .dlo-renew__c1, .dlo-renew__c2 { display: none; }
}
@container dlo-renew (width < 480px) {
  .dlo-renew__life li:nth-child(n+5) { display: none; }
  .dlo-renew__kpis dd small { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .dlo-renew *, .dlo-renew *::before, .dlo-renew *::after {
    animation-duration: 1ms !important; animation-delay: 0ms !important; animation-iteration-count: 1 !important;
    transition-duration: 1ms !important; transition-delay: 0ms !important;
  }
  .dlo-renew .dlo-renew__table tbody tr { animation: none; }
  .dlo-renew .dlo-renew__dl.is-hot { animation: none; box-shadow: 0 0 0 2px var(--dlo-renew-card), 0 0 0 4px color-mix(in oklch, var(--dlo-renew-brick) 40%, transparent); }
}

