/* ---------- state */
const state = { view: 'runway', day: 0, types: new Set(TYPES), month: null, stage: null, q: '', sort: 'deadline', dir: 1, open: null, playing: false };
const asof = () => TODAY + state.day * DAY;
const decisionDate = (c) => (c.renew ? c.deadline : c.end - c.notice * DAY);
function alertOf(c, D = asof()) {
  if (c.status === 'noticed') return D > c.end ? { k: 'ok', txt: 'Ended ' + dm(c.end) } : { k: 'ok', txt: 'Notice sent' };
  if (c.status === 'renewing') return { k: 'ok', txt: 'Renewal approved' };
  if (!c.renew) {
    if (D > c.end) return { k: 'miss', txt: 'Expired ' + dm(c.end) };
    const d = Math.round((decisionDate(c) - D) / DAY);
    if (d < 0) return { k: 'due', txt: 'Expires ' + dm(c.end) };
    return d <= 60 ? { k: 'win', txt: 'Re-source in ' + d + 'd' } : { k: '', txt: 'Expires ' + dm(c.end) };
  }
  if (D > c.deadline) return { k: 'miss', txt: 'Auto-renewed' };
  const d = Math.round((c.deadline - D) / DAY);
  if (d <= 14) return { k: 'due', txt: d === 0 ? 'Notice due today' : 'Notice in ' + d + 'd' };
  if (d <= 60) return { k: 'win', txt: 'Decide in ' + d + 'd' };
  return { k: '', txt: c.status === 'negotiating' ? 'Negotiating' : 'Notice by ' + dm(c.deadline) };
}
const missed = (c, D = asof()) => c.renew && (c.status === 'active' || c.status === 'negotiating') && D > c.deadline;
const stageOf = (c) => (c.pipe ? c.stage : c.status === 'negotiating' ? 'negotiation' : 'active');
const visible = () => C.filter((c) => state.types.has(c.type) && (state.month == null || monthIdx(decisionDate(c)) === state.month));
const monthIdx = (t) => { const d = new Date(t); return (d.getUTCFullYear() - 2026) * 12 + d.getUTCMonth() - 9; };
const money = (v) => (v >= 1e6 ? '$' + (v / 1e6).toFixed(2) + 'M' : v >= 1e3 ? '$' + Math.round(v / 1e3) + 'k' : v ? '$' + v : '—');
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const board = $('.' + P + '__board');
const rowsEl = $('.' + P + '__rows');
