  t.className = P + '__toast' + (bad ? ' is-bad' : ''); t.textContent = msg;
  toasts.append(t);
  while (toasts.children.length > 3) toasts.firstChild.remove();
  setTimeout(() => { t.classList.add('is-out'); setTimeout(() => t.remove(), 350); }, 2800);
}
function showTip(html, x, y) {
  tip.innerHTML = html; tip.hidden = false;
  const r = root.getBoundingClientRect(), w = tip.offsetWidth, h = tip.offsetHeight;
  let lx = x - r.left + 14, ly = y - r.top + 14;
  if (lx + w > r.width - 8) lx = x - r.left - w - 14;
  if (ly + h > r.height - 8) ly = y - r.top - h - 12;
  tip.style.translate = Math.max(8, lx) + 'px ' + Math.max(8, ly) + 'px';
}

/* ---------- type chips */
const typeBox = $('.' + P + '__types');
typeBox.insertAdjacentHTML('beforeend', TYPES.map((t) => `<button type="button" data-type="${t}" aria-pressed="true">${t}<small>${C.filter((c) => c.type === t).length}</small></button>`).join(''));

/* ---------- KPIs + lifecycle */
let lastKpi = '';
function renderKpis() {
  const D = asof(), vis = C.filter((c) => state.types.has(c.type));
  const undecided = (c) => c.renew && (c.status === 'active' || c.status === 'negotiating');
  const due30 = vis.filter((c) => undecided(c) && c.deadline >= D && c.deadline <= D + 30 * DAY);
  const ren90 = vis.filter((c) => undecided(c) && c.deadline >= D && c.deadline <= D + 90 * DAY);
  const miss = vis.filter((c) => missed(c, D));
  const exp = vis.filter((c) => !c.renew && c.status === 'expiring' && c.end >= D && c.end <= D + 180 * DAY);
  const sum = (l) => l.reduce((a, c) => a + c.value, 0);
  const tiles = [
    ['Notices due in 30 days', due30.length, money(sum(due30)), due30.some((c) => c.deadline - D <= 14 * DAY)],
    ['Auto-renewing if nobody acts', money(sum(ren90)), 'next 90 days', false],
    ['Missed, renewed without review', miss.length, money(sum(miss)), miss.length > 0],
    ['Expiring, no auto-renewal', exp.length, 'next 180 days', false]
  ];
  const sig = JSON.stringify(tiles);
  if (sig === lastKpi) return;
  lastKpi = sig;
  $('.' + P + '__kpis').innerHTML = tiles.map((t) => `<div class="${t[3] ? 'is-hot' : ''}"><dt>${t[0]}</dt><dd>${t[1]}<small>${t[2]}</small></dd></div>`).join('');
}
let lastLife = {};
function renderLife() {
  const D = asof();
  const all = C.concat(PIPE);
  const n = {};
  STAGES.forEach(([k]) => { n[k] = 0; });
  all.forEach((c) => { n[stageOf(c)]++; });
  n.due = C.filter((c) => { const a = alertOf(c, D); return a.k === 'due' || a.k === 'win'; }).length;
  const avg = { requested: 4, drafting: 9, negotiation: 17, signature: 3, active: '', due: '' };
  if (STAGES.every(([k]) => lastLife[k] === n[k])) return;
  $('.' + P + '__life').innerHTML = STAGES.map(([k, name]) => `<li class="${k === 'active' ? 'is-active' : k === 'due' ? 'is-due' : ''}"><button type="button" data-stage="${k}" aria-label="${name}: ${n[k]}. Opens the register filtered to this stage." title="${avg[k] ? 'Average ' + avg[k] + ' days in this stage' : name}"><b class="${lastLife[k] != null && lastLife[k] !== n[k] ? 'bump' : ''}">${n[k]}</b><span>${name}</span></button></li>`).join('');
  lastLife = n;
}

/* ---------- runway */
let gridEl = null, nowEl = null, prevMiss = new Set(C.filter((c) => missed(c)).map((c) => c.id));
function ensureGrid() {
  if (gridEl) return;
  gridEl = document.createElement('div');
  gridEl.className = P + '__grid'; gridEl.setAttribute('aria-hidden', 'true');
  for (let m = 0; m <= 12; m++) { const i = document.createElement('i'); i.style.left = (xf(Date.UTC(2026, 9 + m, 1)) * 100) + '%'; gridEl.append(i); }
  const nowWrap = document.createElement('div');
  nowWrap.className = P + '__grid is-now'; nowWrap.setAttribute('aria-hidden', 'true');
  nowEl = document.createElement('span'); nowEl.className = P + '__now'; nowWrap.append(nowEl);
  board.append(gridEl, nowWrap);
}
const pct = (v) => (v * 100).toFixed(3) + '%';
function rowHTML(c, i, fresh) {
  const D = asof(), a = alertOf(c, D), miss = missed(c, D);
  const s0 = Math.max(c.start, W0), e0 = Math.min(c.end, W1);
  let bars = `<span class="${P}__term${c.start < W0 ? ' cut' : ''}${c.end > W1 ? ' over' : ''}${c.status === 'noticed' ? ' is-noticed' : ''}" style="left:${pct(xf(s0))};width:${pct(xf(e0) - xf(s0))}"></span>`;
  if (c.renew && c.status !== 'noticed') {
    const wo = Math.max(W0, c.deadline - 60 * DAY);
    if (c.deadline > W0) bars += `<span class="${P}__win" style="left:${pct(xf(wo))};width:${pct(xf(c.deadline) - xf(wo))}"></span>`;
    if (miss || c.status === 'renewing') {
      const ne = addMonths(c.end, c.renew);
      if (c.end < W1) bars += `<span class="${P}__ext${c.status === 'renewing' ? ' is-planned' : ''}${fresh ? ' is-new' : ''}" style="left:${pct(xf(c.end))};width:${pct(xf(ne) - xf(c.end))}"></span>`;
    }
    if (c.deadline > W0 && c.deadline < W1) bars += `<span class="${P}__dl${a.k === 'due' ? ' is-hot' : ''}${c.status === 'renewing' ? ' is-done' : ''}" style="left:${pct(xf(c.deadline))}"></span>`;
  }
  if (c.end < W1) bars += `<span class="${P}__end${c.renew ? '' : ' is-exp'}" style="left:${pct(xf(c.end))}"></span>`;
  return `<div class="${P}__row" role="option" data-id="${c.id}" tabindex="-1" aria-selected="${state.open === c.id}" style="--i:${i}" aria-label="${esc(c.cp)}, ${esc(c.title)}. ${a.txt}. Term ends ${dmy(c.end)}.">` +
    `<div class="${P}__lbl"><b>${esc(c.cp)}</b><span class="${P}__alert a-${a.k || 'q'}${fresh ? ' a-pop' : ''}">${a.txt}</span><small>${esc(c.title)} · ${money(c.value)}</small></div>` +
    `<div class="${P}__track">${bars}</div></div>`;
}
let rowSig = '';
function renderRows(force, freshIds) {
  const list = visible().sort((a, b) => decisionDate(a) - decisionDate(b));
  const sig = list.map((c) => c.id + ':' + c.status + ':' + alertOf(c).txt).join('|') + state.open;
  if (!force && sig === rowSig) return;
  rowSig = sig;
  const focusId = document.activeElement && document.activeElement.closest && root.contains(document.activeElement) && document.activeElement.closest('[role=option]') ? document.activeElement.dataset.id : null;
  rowsEl.innerHTML = list.map((c, i) => rowHTML(c, i, freshIds && freshIds.has(c.id))).join('') ||
    `<div class="${P}__row" role="presentation" style="grid-column:1/-1;padding:16px;cursor:default">No agreements match these filters.</div>`;
  const opts = $$('[role=option]', rowsEl);
  const keep = opts.find((o) => o.dataset.id === (focusId || state.open)) || opts[0];
  if (keep) keep.tabIndex = 0;
  if (focusId && keep && keep.dataset.id === focusId) keep.focus({ preventScroll: true });
}
function placeNow() {
  ensureGrid();
  nowEl.style.left = pct(xf(asof()));
}

/* value at the notice deadline, by month, coloured by what happened to it */
function renderVar() {
  const W = varSvg.clientWidth || 700, H = 104, top = 6, base = H - 20;
  const D = asof(), vis = C.filter((c) => state.types.has(c.type));
  const months = Array.from({ length: 12 }, (_, m) => {
    const l = vis.filter((c) => monthIdx(decisionDate(c)) === m && (c.renew || c.status === 'expiring'));
    const cat = (c) => (missed(c, D) || (!c.renew && D > c.end) ? 'miss' : c.status === 'noticed' || c.status === 'renewing' ? 'dec' : 'open');
    return { l, miss: l.filter((c) => cat(c) === 'miss').reduce((a, c) => a + c.value, 0), dec: l.filter((c) => cat(c) === 'dec').reduce((a, c) => a + c.value, 0), open: l.filter((c) => cat(c) === 'open').reduce((a, c) => a + c.value, 0) };
  });
  const max = Math.max(1e6, ...months.map((m) => m.miss + m.dec + m.open));
  const step = max > 2.5e6 ? 1e6 : 5e5, ceil = Math.ceil(max / step) * step;
  const y = (v) => base - v / ceil * (base - top);
  let s = '';
  for (let v = step; v <= ceil; v += step) s += `<line class="gl" x1="0" x2="${W}" y1="${y(v)}" y2="${y(v)}"/><text class="ax" x="${W}" y="${y(v) - 3}" text-anchor="end">${money(v).replace('.00', '')}</text>`;
  months.forEach((m, i) => {
    const t0 = Date.UTC(2026, 9 + i, 1), t1 = Date.UTC(2026, 10 + i, 1);
    const x0 = xf(t0) * W, x1 = xf(t1) * W, bw = Math.min(28, (x1 - x0) * 0.56), cx = (x0 + x1) / 2;
    let acc = 0, segs = '';
    [['miss', m.miss], ['dec', m.dec], ['open', m.open]].forEach(([k, v]) => {
      if (!v) return;
      segs += `<rect class="seg s-${k}" style="--i:${i}" x="${cx - bw / 2}" y="${y(acc + v)}" width="${bw}" height="${Math.max(1, y(acc) - y(acc + v) - (acc ? 1 : 0))}" rx="2"/>`;
      acc += v;
    });
    const d = new Date(t0);
    s += `<g class="mo${state.month === i ? ' is-sel' : ''}" data-m="${i}" role="button" tabindex="0" aria-pressed="${state.month === i}" aria-label="${MON[d.getUTCMonth()]} ${d.getUTCFullYear()}: ${money(acc)} across ${m.l.length} agreements. Filters the runway."><rect class="hit" x="${x0 + 1}" y="${top}" width="${x1 - x0 - 2}" height="${base - top + 16}" rx="4"/>${segs}` +
      `<text class="ml" x="${cx}" y="${H - 5}" text-anchor="middle">${x1 - x0 < 44 ? MON[d.getUTCMonth()][0] : MON[d.getUTCMonth()] + (d.getUTCMonth() === 0 ? ' ’27' : '')}</text></g>`;
  });
  const ax = xf(D) * W;
  varSvg._months = months;
  /* while time plays, only the as-of line moves unless a month's mix changed */
  const sig = W + '|' + state.month + '|' + months.map((m) => m.miss + ':' + m.dec + ':' + m.open).join();
  const line = varSvg.querySelector('.asof');
  if (sig === varSig && line) { line.setAttribute('x1', ax); line.setAttribute('x2', ax); return; }
  varSig = sig;
  s += `<line class="asof" x1="${ax}" x2="${ax}" y1="${top - 4}" y2="${base}"/>`;
  varSvg.setAttribute('viewBox', `0 0 ${W} ${H}`);
  varSvg.innerHTML = s;
}
let varSig = '';
varSvg.addEventListener('pointermove', (e) => {
  const g = e.target.closest('.mo');
  if (!g) { tip.hidden = true; return; }
  const m = varSvg._months[+g.dataset.m], d = new Date(Date.UTC(2026, 9 + +g.dataset.m, 1));
  const lines = m.l.map((c) => `<span>${esc(c.cp)} · ${money(c.value)} · ${alertOf(c).txt.toLowerCase()}</span>`).join('');
