});
varSvg.addEventListener('pointerleave', () => { tip.hidden = true; });

/* ---------- register */
function renderRegister() {
  const D = asof();
  const q = state.q.trim().toLowerCase();
  let rows = C.concat(PIPE).filter((c) => state.types.has(c.type) && (!state.stage || (state.stage === 'due' ? (!c.pipe && ['due', 'win'].includes(alertOf(c, D).k)) : stageOf(c) === state.stage)) && (!q || (c.cp + ' ' + c.title).toLowerCase().includes(q)));
  const key = { name: (c) => c.cp, stage: (c) => STAGES.findIndex(([k]) => k === stageOf(c)), deadline: (c) => (c.pipe ? Infinity : decisionDate(c)), end: (c) => (c.pipe ? Infinity : c.end), value: (c) => c.value }[state.sort];
  rows.sort((a, b) => { const x = key(a), y = key(b); return (typeof x === 'string' ? x.localeCompare(y) : x - y) * state.dir; });
  const stageColor = { requested: 'var(--' + P + '-faint)', drafting: 'var(--' + P + '-saffron)', negotiation: 'var(--' + P + '-brick)', signature: 'var(--' + P + '-ink)', active: 'var(--' + P + '-green)' };
  $('.' + P + '__table tbody').innerHTML = rows.map((c, i) => {
    const st = stageOf(c), a = c.pipe ? null : alertOf(c, D);
    return `<tr data-id="${c.id}" tabindex="${i === 0 ? 0 : -1}"><td><b>${esc(c.cp)}</b><small>${esc(c.title)} · ${c.type}</small></td>` +
      `<td class="${P}__c1"><span class="${P}__stage" style="--c:${stageColor[st]}"><i></i>${STAGES.find(([k]) => k === st)[1]}</span></td>` +
      `<td>${c.pipe ? '<small>In flight</small>' : `<b>${dmy(decisionDate(c))}</b><small>${a.txt}</small>`}</td>` +
      `<td class="${P}__c2">${c.pipe ? '—' : dmy(c.end)}</td><td>${money(c.value)}</td></tr>`;
  }).join('') || `<tr><td colspan="5" style="padding:24px;text-align:center;color:var(--${P}-mute)">Nothing matches “${esc(state.q)}”.</td></tr>`;
  $('[data-k=count]').textContent = `${rows.length} of ${C.length + PIPE.length} agreements`;
  const chip = $('[data-act=clearstage]');
  chip.hidden = !state.stage;
  if (state.stage) chip.textContent = 'Stage: ' + STAGES.find(([k]) => k === state.stage)[1];
  $$('.' + P + '__table th[aria-sort]').forEach((th) => { const k = th.querySelector('[data-sort]').dataset.sort; th.setAttribute('aria-sort', k === state.sort ? (state.dir > 0 ? 'ascending' : 'descending') : 'none'); });
}

/* ---------- drawer */
let lastFocus = null;
function renderDrawer() {
  const c = C.find((x) => x.id === state.open); if (!c) return;
  const D = asof(), a = alertOf(c, D), miss = missed(c, D);
  const ne = c.renew ? addMonths(c.end, c.renew) : null;
  const steps = [
    ['Signed', c.start, true, false],
    c.renew ? ['Decision window opens', c.deadline - 60 * DAY, D >= c.deadline - 60 * DAY, false] : ['Start re-sourcing', decisionDate(c), D >= decisionDate(c), false],
    c.renew ? ['Notice deadline', c.deadline, D > c.deadline, a.k === 'due'] : null,
    ['Term ends', c.end, D > c.end, false],
    c.renew && c.status !== 'noticed' ? [miss ? 'Auto-renewed to' : c.status === 'renewing' ? 'Renews to' : 'Would renew to', ne, false, miss] : null
  ].filter(Boolean);
  const noticeOk = c.renew && (c.status === 'active' || c.status === 'negotiating') && !miss;
  const noticeWhy = c.status === 'noticed' ? `Notice already sent on ${dmy(c.sentOn)}` : !c.renew ? 'No auto-renewal: this agreement simply expires' : miss ? `The deadline passed on ${dmy(c.deadline)}; it auto-renewed to ${dmy(ne)}` : c.status === 'renewing' ? 'Renewal already approved' : '';
  const renewOk = (c.renew && (c.status === 'active' || c.status === 'negotiating') && !miss) || (!c.renew && c.status === 'expiring');
  const negOk = c.status === 'active' || (c.status === 'expiring' && c.type !== 'NDA');
  dbody.innerHTML =
    `<div class="${P}__dtop"><div><p>${c.type} · ${esc(c.owner)}</p><h3 id="${P}-dt">${esc(c.cp)}<small>${esc(c.title)}</small></h3></div><button type="button" class="${P}__x" aria-label="Close detail"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 6l12 12M18 6 6 18"/></svg></button></div>` +
    `<dl class="${P}__facts"><div><dt>Annual value</dt><dd>${money(c.value)}</dd></div><div><dt>Status at ${dm(D)}</dt><dd>${a.txt}</dd></div><div><dt>Auto-renewal</dt><dd>${c.renew ? c.renew + ' months' : 'None'}</dd></div><div><dt>Notice period</dt><dd>${c.notice} days</dd></div></dl>` +
    `<ol class="${P}__steps">${steps.map(([n, t, done, hot]) => `<li class="${done ? 'done' : ''}${hot ? ' hot' : ''}"><span>${n}</span><span>${dmy(t)}</span></li>`).join('')}</ol>` +
    `<p class="${P}__dnote">${c.renew ? `Notice must reach ${esc(c.cp)} by <b>${wdmy(c.deadline)}</b> — ${c.notice} days before the term ends.` : `No renewal clause. Start re-sourcing by <b>${wdmy(decisionDate(c))}</b>.`}</p>` +
    `<div class="${P}__acts">` +
    `<button type="button" class="pri" data-do="notice" ${noticeOk ? '' : `aria-disabled="true" title="${esc(noticeWhy)}"`}>Send non-renewal notice</button>` +
    `<button type="button" data-do="renew" ${renewOk ? '' : `aria-disabled="true" title="${miss ? 'Already auto-renewed' : 'Nothing to approve in this state'}"`}>${c.renew ? 'Approve renewal' : 'Start re-sourcing'}</button>` +
    `<button type="button" data-do="neg" ${negOk ? '' : `aria-disabled="true" title="${c.status === 'negotiating' ? 'Already in negotiation' : 'Not available in this state'}"`}>Open renegotiation</button>` +
    (c.status !== c.init ? `<button type="button" data-do="undo">Undo decision</button>` : '') + `</div>`;
}
function openDrawer(id, from) {
  if (!state.open) lastFocus = from || document.activeElement;
  state.open = id; renderDrawer();
  drawer.setAttribute('data-open', ''); drawer.removeAttribute('inert'); drawer.setAttribute('aria-hidden', 'false'); drawer.setAttribute('aria-labelledby', P + '-dt');
  $$('[role=option]', rowsEl).forEach((o) => o.setAttribute('aria-selected', String(o.dataset.id === id)));
  $('.' + P + '__x', dbody).focus({ preventScroll: true });
}
function closeDrawer() {
  if (!state.open) return;
  state.open = null;
  drawer.removeAttribute('data-open'); drawer.setAttribute('inert', ''); drawer.setAttribute('aria-hidden', 'true');
  $$('[role=option]', rowsEl).forEach((o) => o.setAttribute('aria-selected', 'false'));
  if (lastFocus && lastFocus.isConnected) lastFocus.focus({ preventScroll: true });
  lastFocus = null;
}

/* ---------- time */
function setDay(d, quiet) {
  state.day = Math.max(0, Math.min(360, Math.round(d)));
  range.value = state.day;
  $('[data-k=asof]').textContent = wdmy(asof());
  const reset = $('[data-act=today]');
  if (state.day === 0) { reset.setAttribute('aria-disabled', 'true'); reset.title = 'Already showing today'; } else { reset.removeAttribute('aria-disabled'); reset.removeAttribute('title'); }
  /* contracts that just slipped past their deadline */
