  const fresh = new Set([...nowMiss].filter((id) => !prevMiss.has(id)));
  prevMiss = nowMiss;
  if (!quiet) fresh.forEach((id) => { const c = C.find((x) => x.id === id); toast(`${c.cp} auto-renewed to ${dmy(addMonths(c.end, c.renew))} · ${money(c.value)} a year`, true); });
  placeNow(); renderKpis(); renderLife(); renderVar(); renderRows(false, fresh.size ? fresh : null);
  if (state.view === 'register') renderRegister();
  if (state.open) renderDrawer();
}
let playId = 0, io = null, onScreen = true;
function play(on) {
  state.playing = on;
  const b = $('.' + P + '__play');
  b.setAttribute('aria-pressed', String(on));
  b.setAttribute('aria-label', on ? 'Pause' : 'Play the next twelve months');
