  const tick = (now) => {
    if (!root.isConnected || id !== playId) return;
    const dt = Math.min(64, now - last); last = now;
    if (onScreen && !document.hidden) {
      acc += dt / (reduce.matches ? 12 : 26);
      if (Math.round(acc) !== state.day) setDay(acc);
      if (state.day >= 360) { play(false); toast('Reached 1 Oct 2027 · drag the slider or press Today to go back'); return; }
    }
    requestAnimationFrame(tick);
  };
  requestAnimationFrame(tick);
}

/* ---------- views + events */
function setView(v) {
  state.view = v;
  $$('.' + P + '__nav button').forEach((b) => (b.dataset.view === v ? b.setAttribute('aria-current', 'page') : b.removeAttribute('aria-current')));
  $$('.' + P + '__view').forEach((s) => { s.hidden = s.dataset.view !== v; });
  $('[data-k=title]').textContent = v === 'runway' ? 'Renewal runway' : 'Contract register';
  tip.hidden = true;
  if (v === 'register') renderRegister(); else { renderVar(); renderRows(true); }
}
function decide(kind) {
  const c = C.find((x) => x.id === state.open); if (!c) return;
  const btn = $(`[data-do=${kind}]`, dbody);
  if (btn.getAttribute('aria-disabled') === 'true') { toast(btn.title); return; }
  if (kind === 'notice') { c.status = 'noticed'; c.sentOn = asof(); toast(`Non-renewal notice sent to ${c.cp} · ends ${dmy(c.end)}`); }
  else if (kind === 'renew') { if (c.renew) { c.status = 'renewing'; toast(`Renewal approved · ${c.cp} runs to ${dmy(addMonths(c.end, c.renew))}`); } else { c.status = 'negotiating'; toast(`Re-sourcing opened for ${c.title}`); } }
  else if (kind === 'neg') { c.status = 'negotiating'; toast(`${c.cp} moved to negotiation · owner ${c.owner.split(' · ')[1]}`); }
  else if (kind === 'undo') { c.status = c.init; c.sentOn = c.init === 'noticed' ? T('2026-10-02') : null; toast('Decision undone'); }
  prevMiss = new Set(C.filter((x) => missed(x)).map((x) => x.id));
  lastKpi = '';
  renderKpis(); renderLife(); renderVar(); renderRows(true); renderDrawer();
  if (state.view === 'register') renderRegister();
  const f = $(`[data-do=${kind}]`, dbody) || $('.' + P + '__x', dbody); f.focus({ preventScroll: true });
}
root.addEventListener('click', (e) => {
  const t = e.target;
  const nav = t.closest('.' + P + '__nav button');
  if (nav) { closeDrawer(); setView(nav.dataset.view); return; }
  const ty = t.closest('[data-type]');
  if (ty) {
    const k = ty.dataset.type;
    if (state.types.has(k) && state.types.size === 1) { toast('Keep at least one contract type in view'); return; }
    if (state.types.has(k)) state.types.delete(k); else state.types.add(k);
    ty.setAttribute('aria-pressed', String(state.types.has(k)));
    lastKpi = ''; renderKpis(); renderVar(); renderRows(true);
    if (state.view === 'register') renderRegister();
    return;
  }
  if (t.closest('.' + P + '__play')) { play(!state.playing); return; }
  if (t.closest('[data-act=today]')) { if (state.day === 0) return; play(false); prevMiss = new Set(); setDay(0, true); prevMiss = new Set(C.filter((c) => missed(c)).map((c) => c.id)); toast('Back to today'); return; }
  const st = t.closest('[data-stage]');
  if (st) { state.stage = st.dataset.stage; closeDrawer(); setView('register'); return; }
  if (t.closest('[data-act=clearstage]')) { state.stage = null; renderRegister(); return; }
  const mo = t.closest('.mo');
  if (mo) { const m = +mo.dataset.m; state.month = state.month === m ? null : m; monthChip(); renderVar(); renderRows(true); return; }
  if (t.closest('[data-act=clearmonth]')) { state.month = null; monthChip(); renderVar(); renderRows(true); return; }
  const s = t.closest('[data-sort]');
  if (s) { if (state.sort === s.dataset.sort) state.dir = -state.dir; else { state.sort = s.dataset.sort; state.dir = s.dataset.sort === 'value' ? -1 : 1; } renderRegister(); return; }
  const row = t.closest('[role=option]');
  if (row && row.dataset.id) { openDrawer(row.dataset.id, row); return; }
  const tr = t.closest('.' + P + '__table tbody tr[data-id]');
  if (tr) {
    const id = tr.dataset.id;
    if (id.startsWith('p')) { const p = PIPE.find((x) => x.id === id); toast(`${p.cp} · ${p.title} is ${STAGES.find(([k]) => k === p.stage)[1].toLowerCase()} — not yet on the runway`); tr.animate([{ background: `color-mix(in oklch, var(--${P}-saffron) 30%, transparent)` }, { background: 'transparent' }], { duration: 900 }); return; }
    setView('runway'); openDrawer(id, null); return;
  }
  if (t.closest('.' + P + '__x')) { closeDrawer(); return; }
  const d = t.closest('[data-do]');
  if (d) decide(d.dataset.do);
});
function monthChip() {
  const chip = $('[data-act=clearmonth]');
  chip.hidden = state.month == null;
  if (state.month != null) { const d = new Date(Date.UTC(2026, 9 + state.month, 1)); chip.textContent = `Due in ${MON[d.getUTCMonth()]} ${d.getUTCFullYear()}`; }
}
range.addEventListener('input', () => { play(false); setDay(+range.value); });
$('.' + P + '__search input').addEventListener('input', (e) => { state.q = e.target.value; renderRegister(); });
root.addEventListener('keydown', (e) => {
  if (e.key === 'Escape' && state.open) { e.preventDefault(); closeDrawer(); return; }
  const opt = e.target.closest && e.target.closest('[role=option]');
  if (opt) {
    const all = $$('[role=option]', rowsEl), i = all.indexOf(opt);
    let n = i;
    if (e.key === 'ArrowDown') n = Math.min(all.length - 1, i + 1);
    else if (e.key === 'ArrowUp') n = Math.max(0, i - 1);
    else if (e.key === 'Home') n = 0; else if (e.key === 'End') n = all.length - 1;
    else if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); openDrawer(opt.dataset.id, opt); return; }
