    e.preventDefault(); all.forEach((o) => { o.tabIndex = -1; }); all[n].tabIndex = 0; all[n].focus();
    return;
  }
  const tr = e.target.closest && e.target.closest('.' + P + '__table tbody tr');
  if (tr) {
    const all = $$('.' + P + '__table tbody tr'), i = all.indexOf(tr);
    if (e.key === 'ArrowDown' || e.key === 'ArrowUp') { e.preventDefault(); const n = all[Math.max(0, Math.min(all.length - 1, i + (e.key === 'ArrowDown' ? 1 : -1)))]; all.forEach((x) => { x.tabIndex = -1; }); n.tabIndex = 0; n.focus(); }
    else if (e.key === 'Enter') { e.preventDefault(); tr.click(); }
    return;
  }
  const mo = e.target.closest && e.target.closest('.mo');
  if (mo && (e.key === 'Enter' || e.key === ' ')) { e.preventDefault(); mo.dispatchEvent(new MouseEvent('click', { bubbles: true })); }
});

/* ---------- mount */
if (!reduce.matches) { root.classList.add('is-enter'); setTimeout(() => root.classList.remove('is-enter'), 1800); }
setDay(0, true);
renderRows(true);
io = new IntersectionObserver((en) => { onScreen = en[0].isIntersecting; });
io.observe(root);
let rz = 0, lastW = root.clientWidth;
const ro = new ResizeObserver(() => {
