  rz = requestAnimationFrame(() => {
    if (!root.isConnected) { ro.disconnect(); io.disconnect(); return; }
    if (root.clientWidth !== lastW) { lastW = root.clientWidth; renderVar(); }
  });
});
ro.observe(root);

css:
@property --dlo-intake-ring {
  syntax: "<percentage>";
  inherits: false;
  initial-value: 0%;
}

.dlo-intake {
  /* re-theme with these four */
  --dlo-intake-bg: oklch(0.205 0.013 118);
  --dlo-intake-ink: oklch(0.945 0.012 105);
  --dlo-intake-lime: oklch(0.88 0.165 122);
  --dlo-intake-coral: oklch(0.72 0.155 32);
  /* factor hues (urgency, exposure, regulatory, business, quick win) */
  --dlo-intake-f0: var(--dlo-intake-coral);
  --dlo-intake-f1: oklch(0.82 0.135 80);
  --dlo-intake-f2: oklch(0.73 0.13 352);
  --dlo-intake-f3: oklch(0.76 0.1 195);
  --dlo-intake-f4: var(--dlo-intake-lime);
  /* derived */
  --dlo-intake-side: color-mix(in oklch, var(--dlo-intake-bg) 82%, black);
  --dlo-intake-panel: color-mix(in oklch, var(--dlo-intake-bg) 94%, var(--dlo-intake-ink));
  --dlo-intake-raise: color-mix(in oklch, var(--dlo-intake-bg) 87%, var(--dlo-intake-ink));
  --dlo-intake-line: color-mix(in oklch, var(--dlo-intake-ink) 10%, transparent);
  --dlo-intake-soft: color-mix(in oklch, var(--dlo-intake-ink) 6%, transparent);
  --dlo-intake-mute: color-mix(in oklch, var(--dlo-intake-ink) 62%, var(--dlo-intake-bg));
  --dlo-intake-faint: color-mix(in oklch, var(--dlo-intake-ink) 40%, var(--dlo-intake-bg));
  --dlo-intake-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dlo-intake-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dlo-intake-out: cubic-bezier(.16, 1, .3, 1);
  --dlo-intake-spring: linear(0, 0.009, 0.037 2.1%, 0.153 4.6%, 0.639 12.6%, 0.871 17.2%, 0.998 21.6%, 1.054 25.3%, 1.077 29%, 1.069 32.9%, 1.016 42.9%, 0.994 50.4%, 0.996 62.6%, 1);

  width: 100%;
  height: var(--dlo-intake-h, 680px);
  container-type: inline-size; container-name: dlo-intake;
  position: relative; isolation: isolate; overflow: hidden;
  border-radius: 16px;
  background: var(--dlo-intake-bg); color: var(--dlo-intake-ink);
  font: 13px/1.45 var(--dlo-intake-sans);
  accent-color: var(--dlo-intake-lime);
  color-scheme: dark;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, h4, p, ol, dl, dd) { margin: 0; padding: 0; }
  & :where(ol) { list-style: none; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
  & :where(svg) { display: block; }
  & :focus-visible { outline: 2px solid var(--dlo-intake-lime); outline-offset: 2px; border-radius: 6px; }
  & .dlo-intake__scroll {
    overflow: auto; overscroll-behavior: contain;
    scrollbar-width: thin; scrollbar-color: color-mix(in oklch, var(--dlo-intake-ink) 18%, transparent) transparent;
  }
}
.dlo-intake__shell { height: 100%; display: grid; grid-template-columns: 236px minmax(0, 1fr); grid-template-areas: "side main"; }

/* ---------- side */
.dlo-intake__side {
  grid-area: side; min-height: 0; display: flex; flex-direction: column; gap: 18px; padding: 18px 14px 14px;
  background: var(--dlo-intake-side); border-right: 1px solid var(--dlo-intake-line); overflow: auto; scrollbar-width: none;
}
.dlo-intake__brand {
  display: flex; align-items: center; gap: 10px;
  & svg { width: 32px; height: 32px; flex: none; padding: 6px; border-radius: 9px; background: var(--dlo-intake-lime); fill: none; stroke: var(--dlo-intake-bg); stroke-width: 2; stroke-linejoin: round; }
  & b { display: block; font-size: 14px; font-weight: 720; letter-spacing: -.015em; line-height: 1.15; }
  & small { display: block; font-size: 11px; color: var(--dlo-intake-mute); }
}
.dlo-intake__nav {
  display: grid; gap: 2px;
  & button { display: flex; align-items: center; gap: 10px; padding: 8px 10px; border-radius: 9px; color: var(--dlo-intake-mute); font-weight: 580; transition: background-color .2s, color .2s; }
  & button:hover { background: var(--dlo-intake-soft); color: var(--dlo-intake-ink); }
  & button[aria-current=page] { background: var(--dlo-intake-panel); color: var(--dlo-intake-ink); box-shadow: inset 0 0 0 1px var(--dlo-intake-line); }
  & svg { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  & button[aria-current=page] svg { stroke: var(--dlo-intake-lime); }
  & span { flex: 1; }
  & em { font: 700 10.5px var(--dlo-intake-mono); font-style: normal; padding: 1px 6px; border-radius: 99px; background: var(--dlo-intake-coral); color: var(--dlo-intake-bg); }
  & em:empty { display: none; }
}
.dlo-intake__model {
  display: grid; gap: 10px; padding: 12px; border-radius: 12px; background: var(--dlo-intake-panel); box-shadow: inset 0 0 0 1px var(--dlo-intake-line);
  & h3 { font-size: 10.5px; font-weight: 650; letter-spacing: .09em; text-transform: uppercase; color: var(--dlo-intake-faint); }
}
.dlo-intake__presets {
  display: grid; grid-template-columns: 1fr 1fr; gap: 4px;
  & button { padding: 5px 6px; border-radius: 7px; font-size: 11.5px; font-weight: 620; color: var(--dlo-intake-mute); box-shadow: inset 0 0 0 1px var(--dlo-intake-line); text-align: center; transition: background-color .2s, color .2s; }
  & button:hover { color: var(--dlo-intake-ink); }
  & button[aria-checked=true] { background: var(--dlo-intake-lime); color: var(--dlo-intake-bg); box-shadow: none; }
}
.dlo-intake__weights { display: grid; gap: 8px; }
.dlo-intake__w {
  display: grid; grid-template-columns: 10px minmax(0, 1fr) auto; grid-template-rows: auto auto; align-items: center; gap: 2px 8px; font-size: 12px;
  & i { width: 10px; height: 10px; border-radius: 3px; background: var(--c); }
  & span { font-weight: 600; }
  & output { font: 650 11.5px var(--dlo-intake-mono); color: var(--dlo-intake-mute); font-variant-numeric: tabular-nums; }
  & input { grid-column: 1 / -1; width: 100%; margin: 0; height: 16px; accent-color: var(--c); cursor: ew-resize; }
}
.dlo-intake__wbtn {
  display: none; align-items: center; gap: 6px; padding: 6px 10px; border-radius: 8px; font-size: 12px; font-weight: 650; box-shadow: inset 0 0 0 1px var(--dlo-intake-line);
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; }
  &[aria-expanded=true] { background: var(--dlo-intake-lime); color: var(--dlo-intake-bg); box-shadow: none; }
}
.dlo-intake__mnote { font-size: 11px; color: var(--dlo-intake-faint); text-wrap: pretty; line-height: 1.5; }

/* ---------- main */
.dlo-intake__main { grid-area: main; min-width: 0; min-height: 0; display: grid; grid-template-columns: minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); }
.dlo-intake__head {
  display: flex; align-items: flex-end; justify-content: space-between; gap: 16px; padding: 16px 20px 10px;
  & p:first-child { font: 600 11px var(--dlo-intake-mono); color: var(--dlo-intake-lime); letter-spacing: .02em; }
  & h2 { font-size: clamp(19px, 2.3cqi, 25px); font-weight: 720; letter-spacing: -.025em; line-height: 1.1; text-wrap: balance; }
}
.dlo-intake__sum { font-size: 12px; color: var(--dlo-intake-mute); text-align: right; text-wrap: pretty; & b { color: var(--dlo-intake-ink); font-variant-numeric: tabular-nums; } & .hot { color: var(--dlo-intake-coral); } }
.dlo-intake__views { position: relative; min-height: 0; }
.dlo-intake__view { height: 100%; min-height: 0; }
.dlo-intake__view[hidden] { display: none; }

/* queue: one grid; header, list and every row are subgrids of it */
.dlo-intake__qv {
  display: grid; padding: 0 20px 14px;
  grid-template-columns: 28px minmax(0, 1fr) minmax(150px, 230px) 44px 96px 40px; column-gap: 12px;
  grid-template-rows: auto auto minmax(0, 1fr);
}
.dlo-intake__bus {
  grid-column: 1 / -1; display: flex; flex-wrap: wrap; gap: 5px; padding-bottom: 10px;
  & button { padding: 4px 11px; border-radius: 99px; font-size: 12px; font-weight: 600; color: var(--dlo-intake-mute); box-shadow: inset 0 0 0 1px var(--dlo-intake-line); transition: background-color .2s, color .2s; }
  & button:hover { color: var(--dlo-intake-ink); }
  & button[aria-checked=true] { background: var(--dlo-intake-ink); color: var(--dlo-intake-bg); box-shadow: none; }
  & small { font: 600 10.5px var(--dlo-intake-mono); opacity: .65; margin-left: 4px; }
}
.dlo-intake__qhead {
  grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; padding: 0 10px 6px; border-bottom: 1px solid var(--dlo-intake-line);
  font-size: 10.5px; font-weight: 650; letter-spacing: .07em; text-transform: uppercase; color: var(--dlo-intake-faint);
  & span:nth-child(4), & span:nth-child(5) { text-align: right; }
}
.dlo-intake__list { grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; align-content: start; padding-top: 6px; gap: 3px; }
.dlo-intake__item {
  grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; align-items: center; position: relative;
  border-radius: 10px; transition: background-color .18s;
  &:hover { background: var(--dlo-intake-soft); }
  &.is-open { background: var(--dlo-intake-raise); box-shadow: inset 0 0 0 1px var(--dlo-intake-line), inset 3px 0 0 var(--dlo-intake-lime); }
  &.is-wait { opacity: .62; }
}
.dlo-intake__rowbtn {
  grid-column: 1 / 6; display: grid; grid-template-columns: subgrid; align-items: center; padding: 8px 0 8px 10px; border-radius: 10px; min-width: 0;
  &:focus-visible { outline-offset: -2px; }
  & .rk { font: 700 12px var(--dlo-intake-mono); color: var(--dlo-intake-faint); font-variant-numeric: tabular-nums; }
  & .rq { min-width: 0; }
  & .rq b { display: block; font-size: 12.75px; font-weight: 620; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .rq small { display: block; font-size: 11px; color: var(--dlo-intake-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .sc { text-align: right; font: 700 15px var(--dlo-intake-mono); font-variant-numeric: tabular-nums; letter-spacing: -.02em; }
  & .sla { justify-self: end; font: 650 10.5px var(--dlo-intake-mono); padding: 2px 7px; border-radius: 99px; background: var(--dlo-intake-soft); color: var(--dlo-intake-mute); white-space: nowrap; font-variant-numeric: tabular-nums; }
  & .sla.hot { background: color-mix(in oklch, var(--dlo-intake-coral) 20%, transparent); color: var(--dlo-intake-coral); }
  & .sla.bad { background: var(--dlo-intake-coral); color: var(--dlo-intake-bg); }
  & .sla.wait { background: transparent; box-shadow: inset 0 0 0 1px var(--dlo-intake-line); }
}
.dlo-intake__fb {
  display: flex; height: 10px; border-radius: 3px; overflow: hidden; background: var(--dlo-intake-soft);
  & i { height: 100%; width: var(--w); background: var(--c); transition: width .55s var(--dlo-intake-out); box-shadow: inset -1px 0 0 var(--dlo-intake-bg); }
}
.dlo-intake__own {
  grid-column: 6; justify-self: center; display: grid; place-items: center; width: 30px; height: 30px; border-radius: 50%;
  font: 700 10.5px var(--dlo-intake-sans); background: var(--av, transparent); color: var(--dlo-intake-bg);
  box-shadow: inset 0 0 0 1.5px var(--dlo-intake-line); transition: transform .3s var(--dlo-intake-spring), box-shadow .2s;
  &:hover { transform: scale(1.1); box-shadow: inset 0 0 0 1.5px var(--dlo-intake-lime); }
  &.is-none { color: var(--dlo-intake-faint); border: 1.5px dashed var(--dlo-intake-faint); box-shadow: none; }
  & svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; }
  &[aria-expanded=true] { box-shadow: 0 0 0 2px var(--dlo-intake-lime); }
}
@supports (animation-timeline: view()) {
  .dlo-intake__item { animation: dlo-intake-rise linear both; animation-timeline: view(); animation-range: entry 0% entry 60%; }
}

/* ---------- assign menu */
.dlo-intake__menu {
  position: absolute; z-index: 7; left: 0; top: 0; width: 264px; padding: 6px; border-radius: 12px;
  background: var(--dlo-intake-raise); box-shadow: 0 0 0 1px var(--dlo-intake-line), 0 24px 50px -16px black;
  transform-origin: var(--ox, 100%) 0;
  transition: opacity .18s, transform .3s var(--dlo-intake-spring);
  @starting-style { opacity: 0; transform: scale(.94) translateY(-4px); }
  & h4 { font-size: 10.5px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase; color: var(--dlo-intake-faint); padding: 6px 8px 6px; }
}
.dlo-intake__menu[hidden] { display: none; }
.dlo-intake__mi {
  width: 100%; display: grid; grid-template-columns: 26px minmax(0, 1fr) auto; grid-template-rows: auto auto; align-items: center; gap: 1px 10px; padding: 7px 8px; border-radius: 8px;
  &:hover, &:focus-visible { background: var(--dlo-intake-soft); outline: none; }
  &[aria-checked=true] { background: color-mix(in oklch, var(--dlo-intake-lime) 12%, transparent); }
  & i { grid-row: span 2; display: grid; place-items: center; width: 26px; height: 26px; border-radius: 50%; font: 700 10px var(--dlo-intake-sans); font-style: normal; background: var(--av); color: var(--dlo-intake-bg); }
  & b { font-size: 12.5px; font-weight: 620; }
  & small { grid-column: 2; font-size: 11px; color: var(--dlo-intake-mute); }
  & .ld { grid-row: span 2; display: grid; justify-items: end; gap: 3px; font: 600 10.5px var(--dlo-intake-mono); color: var(--dlo-intake-mute); font-variant-numeric: tabular-nums; }
  & .ld span { width: 54px; height: 5px; border-radius: 3px; background: var(--dlo-intake-soft); overflow: hidden; display: flex; }
  & .ld span u { height: 100%; width: var(--now); background: var(--dlo-intake-mute); }
  & .ld span s { height: 100%; width: var(--add); background: var(--dlo-intake-lime); }
  &.over .ld { color: var(--dlo-intake-coral); }
  &.over .ld span s { background: var(--dlo-intake-coral); }
}

/* ---------- team lanes */
.dlo-intake__tv { padding: 0 20px 16px; }
.dlo-intake__lanes { display: grid; grid-template-columns: repeat(5, minmax(158px, 1fr)); gap: 10px; align-items: start; min-height: 100%; }
.dlo-intake__lane {
  display: grid; gap: 8px; padding: 12px; border-radius: 12px; background: var(--dlo-intake-panel); box-shadow: inset 0 0 0 1px var(--dlo-intake-line);
  & header { display: grid; grid-template-columns: 52px minmax(0, 1fr); gap: 10px; align-items: center; }
  & header b { display: block; font-size: 13px; font-weight: 680; }
  & header small { display: block; font-size: 11px; color: var(--dlo-intake-mute); }
}
.dlo-intake__cap {
  --dlo-intake-ring: 0%;
  width: 52px; height: 52px; border-radius: 50%; display: grid; place-items: center;
  background: radial-gradient(closest-side, var(--dlo-intake-panel) 74%, transparent 76%), conic-gradient(var(--rc, var(--dlo-intake-lime)) var(--dlo-intake-ring), var(--dlo-intake-soft) 0);
  transition: --dlo-intake-ring 1s var(--dlo-intake-out);
  & span { font: 700 12px var(--dlo-intake-mono); font-variant-numeric: tabular-nums; }
  &.is-on { --dlo-intake-ring: var(--p); }
}
.dlo-intake__card2 {
  display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 4px 8px; padding: 9px 10px; border-radius: 9px; background: var(--dlo-intake-soft);
  & b { font-size: 12px; font-weight: 620; line-height: 1.3; text-wrap: pretty; }
  & small { font-size: 11px; color: var(--dlo-intake-mute); font-variant-numeric: tabular-nums; }
  & .sc { font: 700 12.5px var(--dlo-intake-mono); }
  & button { grid-column: 1 / -1; justify-self: start; font-size: 11.5px; font-weight: 620; color: var(--dlo-intake-mute); padding: 2px 0; }
  & button:hover { color: var(--dlo-intake-coral); }
  @starting-style { opacity: 0; transform: translateY(6px); }
  transition: opacity .3s, transform .4s var(--dlo-intake-out);
}
.dlo-intake__empty { font-size: 12px; color: var(--dlo-intake-faint); padding: 6px 2px; }

/* ---------- stats */
.dlo-intake__sv { display: grid; grid-template-columns: minmax(0, 1fr) 240px; grid-template-rows: auto auto; gap: 12px; padding: 0 20px 16px; align-content: start; }
.dlo-intake__card { padding: 14px 16px; border-radius: 12px; background: var(--dlo-intake-panel); box-shadow: inset 0 0 0 1px var(--dlo-intake-line); min-width: 0; & h3 { font-size: 13px; font-weight: 650; } }
.dlo-intake__flow { grid-row: span 2; display: grid; grid-template-rows: auto minmax(0, 1fr); gap: 8px; }
.dlo-intake__ch { display: flex; justify-content: space-between; align-items: center; gap: 10px; flex-wrap: wrap; }
.dlo-intake__lg {
  display: flex; gap: 14px; font-size: 11px; color: var(--dlo-intake-mute);
  & span { display: inline-flex; align-items: center; gap: 6px; }
  & span::before { content: ""; width: 10px; height: 10px; border-radius: 2px; }
  & .i-in::before { background: var(--dlo-intake-f3); }
  & .i-out::before { background: var(--dlo-intake-lime); }
  & .i-bl::before { height: 2px; background: var(--dlo-intake-coral); }
}
.dlo-intake__cwrap { position: relative; min-height: 300px; }
.dlo-intake__canvas { position: absolute; inset: 0; width: 100%; height: 100%; cursor: crosshair; border-radius: 6px; }
.dlo-intake__sla { display: grid; justify-items: center; gap: 10px; text-align: center; & p { font-size: 11.5px; color: var(--dlo-intake-mute); text-wrap: pretty; } & h3 { justify-self: start; } }
.dlo-intake__ring {
  --dlo-intake-ring: 0%;
  width: 128px; height: 128px; border-radius: 50%; display: grid; place-content: center;
  background: radial-gradient(closest-side, var(--dlo-intake-panel) 80%, transparent 81%), conic-gradient(from -90deg, var(--dlo-intake-lime) var(--dlo-intake-ring), color-mix(in oklch, var(--dlo-intake-coral) 50%, transparent) 0);
  transition: --dlo-intake-ring 1.3s var(--dlo-intake-out);
  & b { font: 700 28px var(--dlo-intake-mono); letter-spacing: -.04em; font-variant-numeric: tabular-nums; }
  & small { font-size: 10.5px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase; color: var(--dlo-intake-faint); }
  &.is-on { --dlo-intake-ring: var(--p); }
}
.dlo-intake__bubars {
  width: 100%; height: 170px; overflow: visible; margin-top: 8px;
  & .lb { font: 600 11px var(--dlo-intake-sans); fill: var(--dlo-intake-ink); }
  & .vl { font: 650 11px var(--dlo-intake-mono); fill: var(--dlo-intake-mute); }
  & .tr { fill: var(--dlo-intake-soft); }
  & .br { fill: var(--dlo-intake-f3); transform-box: fill-box; transform-origin: 0 50%; animation: dlo-intake-grow .8s var(--dlo-intake-out) both; animation-delay: calc(var(--i) * 60ms); }
  & .br.hot { fill: var(--dlo-intake-coral); }
}

/* ---------- drawer */
.dlo-intake__drawer {
  position: absolute; z-index: 6; inset: 10px 10px 10px auto; width: min(370px, calc(100% - 20px)); display: flex; flex-direction: column; border-radius: 14px;
  background: var(--dlo-intake-raise); box-shadow: 0 0 0 1px var(--dlo-intake-line), 0 30px 60px -20px black;
