}
.dlo-intake__dbody { flex: 1; min-height: 0; overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; padding: 16px 18px; display: grid; align-content: start; gap: 14px; }
.dlo-intake__dtop {
  display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 10px;
  & p { font: 600 11px var(--dlo-intake-mono); color: var(--dlo-intake-lime); }
  & h3 { font-size: 18px; font-weight: 720; letter-spacing: -.02em; line-height: 1.2; text-wrap: balance; margin-top: 3px; }
}
.dlo-intake__x { display: grid; place-items: center; width: 30px; height: 30px; border-radius: 8px; color: var(--dlo-intake-mute); &:hover { background: var(--dlo-intake-soft); color: var(--dlo-intake-ink); } & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; } }
.dlo-intake__desc { font-size: 12.5px; color: var(--dlo-intake-mute); text-wrap: pretty; line-height: 1.55; }
.dlo-intake__meta { display: flex; flex-wrap: wrap; gap: 6px; & span { font-size: 11.5px; padding: 3px 9px; border-radius: 99px; background: var(--dlo-intake-soft); } }
.dlo-intake__fx {
  display: grid; gap: 7px;
  & h4 { font-size: 10.5px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase; color: var(--dlo-intake-faint); }
  & li { display: grid; grid-template-columns: 96px 1fr 52px; align-items: center; gap: 10px; font-size: 12px; }
  & .dots { display: flex; gap: 3px; }
  & .dots i { width: 14px; height: 6px; border-radius: 2px; background: var(--dlo-intake-soft); }
  & .dots i.on { background: var(--c); }
  & .pts { text-align: right; font: 650 11.5px var(--dlo-intake-mono); color: var(--dlo-intake-mute); font-variant-numeric: tabular-nums; }
  & .tot { border-top: 1px solid var(--dlo-intake-line); padding-top: 7px; font-weight: 700; }
}
.dlo-intake__acts {
  display: grid; gap: 6px;
  & button { padding: 10px 12px; border-radius: 9px; font-weight: 650; text-align: center; box-shadow: inset 0 0 0 1px var(--dlo-intake-line); transition: background-color .2s, transform .2s var(--dlo-intake-spring); }
  & button:hover { background: var(--dlo-intake-soft); }
  & button:active { transform: scale(.98); }
  & .pri { background: var(--dlo-intake-lime); color: var(--dlo-intake-bg); box-shadow: none; }
  & .pri:hover { background: color-mix(in oklch, var(--dlo-intake-lime) 85%, white); }
}

/* ---------- tooltip + toasts */
.dlo-intake__tip {
  position: absolute; z-index: 8; left: 0; top: 0; pointer-events: none; max-width: 240px; padding: 7px 10px; border-radius: 8px;
  background: var(--dlo-intake-ink); color: var(--dlo-intake-bg); font-size: 11.5px; box-shadow: 0 12px 28px -10px black;
  & b { display: block; font-weight: 700; }
  & span { display: block; opacity: .82; font-variant-numeric: tabular-nums; }
}
.dlo-intake__toasts { position: absolute; z-index: 9; left: 50%; bottom: 16px; translate: -50% 0; display: grid; gap: 6px; justify-items: center; pointer-events: none; }
.dlo-intake__toast {
  padding: 9px 14px; border-radius: 10px; background: var(--dlo-intake-ink); color: var(--dlo-intake-bg); font-size: 12px; font-weight: 650; white-space: nowrap;
  box-shadow: 0 14px 30px -12px black; transition: opacity .3s, transform .45s var(--dlo-intake-spring);
  @starting-style { opacity: 0; transform: translateY(10px) scale(.96); }
  &.is-out { opacity: 0; transform: translateY(6px); }
}

@keyframes dlo-intake-rise { from { opacity: 0; transform: translateY(8px); } }
@keyframes dlo-intake-grow { from { transform: scaleX(0); } }
@keyframes dlo-intake-in { from { opacity: 0; transform: translateX(-8px); } }
.dlo-intake.is-enter .dlo-intake__item { animation: dlo-intake-in .55s var(--dlo-intake-out) both; animation-delay: calc(var(--i) * 32ms); }

/* ---------- responsive */
@container dlo-intake (width < 960px) {
  .dlo-intake__shell { grid-template-columns: 208px minmax(0, 1fr); }
  .dlo-intake__qv { grid-template-columns: 24px minmax(0, 1fr) minmax(110px, 150px) 40px 86px 36px; column-gap: 10px; }
  .dlo-intake__sv { grid-template-columns: minmax(0, 1fr); }
  .dlo-intake__flow { grid-row: auto; }
  .dlo-intake__sum { display: none; }
}
@container dlo-intake (width < 760px) {
  .dlo-intake__shell { grid-template-columns: minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); grid-template-areas: "side" "main"; }
  .dlo-intake__side { flex-direction: row; flex-wrap: wrap; align-items: center; gap: 8px 10px; padding: 8px 12px; border-right: 0; border-bottom: 1px solid var(--dlo-intake-line); max-height: 52px; overflow: hidden; }
  .dlo-intake__side.is-expanded { max-height: none; }
  .dlo-intake__wbtn { display: inline-flex; margin-left: auto; }
  .dlo-intake__brand span, .dlo-intake__mnote { display: none; }
  .dlo-intake__nav { display: flex; & span { display: none; } & button { padding: 8px; } }
  .dlo-intake__model { order: 3; flex: 1 1 100%; padding: 8px; }
  .dlo-intake__weights { grid-template-columns: repeat(auto-fill, minmax(130px, 1fr)); }
  .dlo-intake__head { padding: 12px 14px 8px; }
  .dlo-intake__qv { padding: 0 14px 12px; grid-template-columns: 22px minmax(0, 1fr) 40px 80px 34px; }
  .dlo-intake__hb, .dlo-intake__fb { display: none; }
  .dlo-intake__qhead span:nth-child(4) { text-align: right; }
  .dlo-intake__rowbtn { grid-column: 1 / 5; }
  .dlo-intake__own { grid-column: 5; }
  .dlo-intake__tv, .dlo-intake__sv { padding: 0 14px 14px; }
  .dlo-intake__lanes { grid-template-columns: repeat(5, 220px); }
}
@container dlo-intake (width < 480px) {
  .dlo-intake__qv { grid-template-columns: minmax(0, 1fr) 28px 82px 32px; column-gap: 8px; }
  .dlo-intake__qhead span:first-child, .dlo-intake__rowbtn .rk { display: none; }
  .dlo-intake__rowbtn { grid-column: 1 / 4; }
  .dlo-intake__own { grid-column: 4; }
  .dlo-intake__bus { flex-wrap: nowrap; overflow-x: auto; scrollbar-width: none; & button { flex: none; } }
}

@media (prefers-reduced-motion: reduce) {
  .dlo-intake *, .dlo-intake *::before, .dlo-intake *::after {
    animation-duration: 1ms !important; animation-delay: 0ms !important; animation-iteration-count: 1 !important;
    transition-duration: 1ms !important; transition-delay: 0ms !important;
  }
  .dlo-intake .dlo-intake__item { animation: none; }
}

