const probe = document.createElement('i'); probe.style.cssText = 'position:absolute;width:0;height:0;visibility:hidden'; root.append(probe);
const colour = (v) => { probe.style.color = `var(--${P}-${v})`; return getComputedStyle(probe).color; };
function flow() {
  const clo = CLO.slice(); clo[13] += state.closedToday;
  let b = 10; const bl = ARR.map((a, i) => (b += a - clo[i]));
  return { arr: ARR, clo, bl };
}
function drawFlow() {
