    if (i % 2 === 0 || i === 13) { ctx.fillStyle = i === 13 ? C.ink : C.faint; ctx.fillText(i === 13 ? 'Today' : d.getUTCDate() + '/' + (d.getUTCMonth() + 1), X(i), h - 8); }
    if (wk) { ctx.fillStyle = C.line; ctx.globalAlpha = .45; ctx.fillRect(X(i) - cw / 2, padT, cw, h - padT - padB); ctx.globalAlpha = 1; }
