      `<rect class="br" style="--i:${i}" x="${L}" y="${y + 4}" width="${Math.max(0, x1)}" height="${rh - 16}" rx="3"/>${late ? `<rect class="br hot" style="--i:${i}" x="${L + x1}" y="${y + 4}" width="${x2}" height="${rh - 16}" rx="3"/>` : ''}` +
