  state.view = v; closeMenu();
  $$('.' + P + '__nav button').forEach((b) => (b.dataset.view === v ? b.setAttribute('aria-current', 'page') : b.removeAttribute('aria-current')));
  $$('.' + P + '__view').forEach((s) => { s.hidden = s.dataset.view !== v; });
  $('[data-k=title]').textContent = v === 'queue' ? 'Triage queue' : v === 'team' ? 'Workload by attorney' : 'Flow & SLA';
  tip.hidden = true;
  if (v === 'team') renderTeam();
  if (v === 'stats') { pal = null; renderSla(); renderBubars(); growFlow(); }
}
function setWeights(w, preset) {
  state.w = w.slice(); state.preset = preset;
  syncWeights(); renderPresets(); update(true);
  if (state.open) renderDrawer();
}
root.addEventListener('click', (e) => {
  const t = e.target;
  if (!menu.hidden && !t.closest('.' + P + '__menu') && !t.closest('.' + P + '__own') && !t.closest('[data-act=assign]')) closeMenu();
  const nav = t.closest('.' + P + '__nav button');
  if (nav) { closeDrawer(); setView(nav.dataset.view); return; }
  const wb = t.closest('.' + P + '__wbtn');
  if (wb) { const on = wb.getAttribute('aria-expanded') !== 'true'; wb.setAttribute('aria-expanded', String(on)); $('.' + P + '__side').classList.toggle('is-expanded', on); return; }
  const pr = t.closest('[data-preset]');
  if (pr) { const p = PRESETS.find((x) => x[0] === pr.dataset.preset); setWeights(p[2], p[0]); toast(`${p[1]} weighting · queue re-ranked`); return; }
  const bu = t.closest('[data-bu]');
  if (bu) { state.bu = bu.dataset.bu; renderBus(); buildRows(); update(); return; }
  const own = t.closest('.' + P + '__own');
  if (own) { const id = own.closest('li').dataset.id; if (state.menuFor === id) closeMenu(true); else openMenu(id, own); return; }
  const mi = t.closest('[data-assign]');
  if (mi) { assign(state.menuFor, mi.dataset.assign); return; }
  const row = t.closest('.' + P + '__rowbtn');
  if (row) { openDrawer(row.closest('li').dataset.id, row); return; }
  if (t.closest('.' + P + '__x')) { closeDrawer(); return; }
  const act = t.closest('[data-act]');
  if (act) {
    const r = REQ.find((x) => x.id === state.open);
    if (act.dataset.act === 'assign') { if (state.menuFor) closeMenu(); else openMenu(r.id, act); }
    else if (act.dataset.act === 'wait') { r.wait = !r.wait; renderDrawer(); update(true); toast(r.wait ? 'SLA paused until the requester replies' : 'SLA clock running again'); $('[data-act=wait]', dbody).focus({ preventScroll: true }); }
    else if (act.dataset.act === 'resolve') {
      r.done = true; state.closedToday++; if (sla(r).cls === 'bad') state.lateToday++;
      closeDrawer();
      const li = rows.get(r.id);
      const finish = () => { renderBus(); buildRows(); update(true); renderTeam(); renderBubars(); renderSla(); drawFlow(); };
      if (li && !reduce.matches) li.animate([{ opacity: 1, transform: 'none' }, { opacity: 0, transform: 'translateX(24px)' }], { duration: 260, easing: 'ease-in' }).onfinish = finish; else finish();
      toast(`Resolved · ${r.t.split(',')[0]}`);
    }
    return;
  }
  const un = t.closest('[data-unassign]');
  if (un) { const r = REQ.find((x) => x.id === un.dataset.unassign); const m = TM[r.owner]; r.owner = null; renderTeam(); update(); renderBubars(); toast(`${r.t.split(',')[0]} back in the pool · ${m.name} at ${Math.round(load(m) / m.cap * 100)}%`); }
});
root.addEventListener('input', (e) => {
  const i = e.target.dataset && e.target.dataset.w;
  if (i == null) return;
  const w = state.w.slice(); w[+i] = +e.target.value;
  setWeights(w, null);
});
root.addEventListener('keydown', (e) => {
  if (e.key === 'Escape') { if (!menu.hidden) { e.preventDefault(); closeMenu(true); return; } if (state.open) { e.preventDefault(); closeDrawer(); return; } }
  if (!menu.hidden && e.target.closest && e.target.closest('.' + P + '__menu')) {
    const items = $$('[data-assign]', menu), i = items.indexOf(document.activeElement);
    if (e.key === 'ArrowDown' || e.key === 'ArrowUp') { e.preventDefault(); const n = items[(i + (e.key === 'ArrowDown' ? 1 : items.length - 1)) % items.length]; items.forEach((x) => { x.tabIndex = -1; }); n.tabIndex = 0; n.focus(); }
    else if (e.key === 'Tab') closeMenu();
    return;
  }
  const row = e.target.closest && e.target.closest('.' + P + '__rowbtn');
  if (row && (e.key === 'ArrowDown' || e.key === 'ArrowUp' || e.key === 'Home' || e.key === 'End')) {
    e.preventDefault();
    const btns = ranked().map((r) => rows.get(r.id).querySelector('.' + P + '__rowbtn')), i = btns.indexOf(row);
    const n = btns[e.key === 'Home' ? 0 : e.key === 'End' ? btns.length - 1 : Math.max(0, Math.min(btns.length - 1, i + (e.key === 'ArrowDown' ? 1 : -1)))];
    btns.forEach((b) => { b.tabIndex = -1; }); n.tabIndex = 0; n.focus();
    return;
  }
  const rr = e.target.closest && e.target.closest('[role=radio]');
  if (rr && /^Arrow/.test(e.key)) {
    const all = $$('[role=radio]', rr.parentElement), i = all.indexOf(rr);
    const n = all[(i + (/Right|Down/.test(e.key) ? 1 : all.length - 1)) % all.length];
    e.preventDefault(); n.click(); n.focus();
  }
});

/* ---------- mount */
let onScreen = true;
renderPresets(); renderBus(); buildRows(); update();
if (!reduce.matches) { root.classList.add('is-enter'); setTimeout(() => root.classList.remove('is-enter'), 1400); }
const io = new IntersectionObserver((en) => { onScreen = en[0].isIntersecting; });
io.observe(root);
let rz = 0;
const ro = new ResizeObserver(() => {
  cancelAnimationFrame(rz);
  rz = requestAnimationFrame(() => {
    if (!root.isConnected) { ro.disconnect(); io.disconnect(); return; }
    if (state.view === 'stats') { drawFlow(); renderBubars(); }
    if (!menu.hidden) closeMenu();
  });
});
ro.observe(root);

