@property --dlo-esign-p {
  syntax: "<percentage>";
  inherits: false;
  initial-value: 0%;
}

.dlo-esign {
  /* re-theme with these four */
  --dlo-esign-paper: oklch(0.993 0.002 250);
  --dlo-esign-ink: oklch(0.225 0.03 262);
  --dlo-esign-blue: oklch(0.47 0.17 262);
  --dlo-esign-green: oklch(0.6 0.13 156);
  /* derived */
  --dlo-esign-amber: oklch(0.76 0.14 74);
  --dlo-esign-red: oklch(0.58 0.18 27);
  --dlo-esign-side: color-mix(in oklch, var(--dlo-esign-paper) 94%, var(--dlo-esign-blue));
  --dlo-esign-line: color-mix(in oklch, var(--dlo-esign-ink) 11%, transparent);
  --dlo-esign-hair: color-mix(in oklch, var(--dlo-esign-ink) 6%, transparent);
  --dlo-esign-wash: color-mix(in oklch, var(--dlo-esign-blue) 5%, transparent);
  --dlo-esign-mute: color-mix(in oklch, var(--dlo-esign-ink) 62%, var(--dlo-esign-paper));
  --dlo-esign-faint: color-mix(in oklch, var(--dlo-esign-ink) 38%, var(--dlo-esign-paper));
  --dlo-esign-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dlo-esign-serif: ui-serif, "Iowan Old Style", Georgia, serif;
  --dlo-esign-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dlo-esign-out: cubic-bezier(.2, .85, .25, 1);
  --dlo-esign-spring: linear(0, 0.013, 0.051 2.4%, 0.207 5.3%, 0.758 14.6%, 0.953 19.5%, 1.064 24.4%, 1.1 28.2%, 1.105 31.9%, 1.081 36.5%, 1.012 47.6%, 0.99 55.4%, 0.993 67.8%, 1);

  width: 100%;
  height: var(--dlo-esign-h, 680px);
  container-type: inline-size; container-name: dlo-esign;
  position: relative; isolation: isolate; overflow: hidden;
  border-radius: 14px;
  background: var(--dlo-esign-paper); color: var(--dlo-esign-ink);
  font: 13px/1.45 var(--dlo-esign-sans);
  accent-color: var(--dlo-esign-blue);
  color-scheme: light;
  box-shadow: inset 0 0 0 1px var(--dlo-esign-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, h4, p, ol) { margin: 0; padding: 0; }
  & :where(ol) { list-style: none; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
  & :where(svg) { display: block; }
  & :focus-visible { outline: 2px solid var(--dlo-esign-blue); outline-offset: 2px; border-radius: 6px; }
  & .dlo-esign__scroll {
    overflow: auto; overscroll-behavior: contain;
    scrollbar-width: thin; scrollbar-color: color-mix(in oklch, var(--dlo-esign-ink) 20%, transparent) transparent;
  }
}
.dlo-esign__shell { height: 100%; display: grid; grid-template-columns: 212px minmax(0, 1fr); grid-template-areas: "side main"; }

/* ---------- side */
.dlo-esign__side {
  grid-area: side; min-height: 0; display: flex; flex-direction: column; gap: 16px; padding: 18px 12px 14px;
  background: var(--dlo-esign-side); border-right: 1px solid var(--dlo-esign-line); overflow: auto; scrollbar-width: none;
}
.dlo-esign__brand {
  display: flex; align-items: center; gap: 10px; padding: 0 4px;
  & svg { width: 32px; height: 32px; flex: none; padding: 5px; border-radius: 9px; background: var(--dlo-esign-blue); fill: none; stroke: var(--dlo-esign-paper); stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
  & b { display: block; font-size: 14px; font-weight: 720; letter-spacing: -.015em; line-height: 1.15; font-family: var(--dlo-esign-serif); }
  & small { display: block; font-size: 11px; color: var(--dlo-esign-mute); }
}
.dlo-esign__deal {
  padding: 11px 12px; border-radius: 11px; background: var(--dlo-esign-paper); box-shadow: 0 0 0 1px var(--dlo-esign-line), 0 1px 2px var(--dlo-esign-hair);
  & p { font-size: 10.5px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase; color: var(--dlo-esign-blue); }
  & b { display: block; font-size: 12.5px; font-weight: 650; line-height: 1.3; margin: 2px 0 6px; text-wrap: balance; }
  & span { display: inline-block; font: 650 11px var(--dlo-esign-mono); padding: 2px 7px; border-radius: 99px; background: color-mix(in oklch, var(--dlo-esign-amber) 25%, transparent); color: color-mix(in oklab, var(--dlo-esign-amber) 40%, var(--dlo-esign-ink)); }
}
.dlo-esign__folders {
