  & button { display: flex; align-items: center; gap: 9px; padding: 7px 10px; border-radius: 8px; color: var(--dlo-esign-mute); font-weight: 580; transition: background-color .2s, color .2s; }
  & button:hover { background: var(--dlo-esign-wash); color: var(--dlo-esign-ink); }
  & button[aria-current=page] { background: var(--dlo-esign-paper); color: var(--dlo-esign-ink); box-shadow: 0 0 0 1px var(--dlo-esign-line); }
  & svg { width: 17px; height: 17px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  & button[aria-current=page] svg { stroke: var(--dlo-esign-blue); }
  & span { flex: 1; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & small { font: 600 11px var(--dlo-esign-mono); color: var(--dlo-esign-faint); font-variant-numeric: tabular-nums; }
}
.dlo-esign__legend {
  margin-top: auto; display: grid; gap: 5px; padding: 0 6px; font-size: 11.5px; color: var(--dlo-esign-mute);
  & p { font-size: 10.5px; font-weight: 650; letter-spacing: .09em; text-transform: uppercase; color: var(--dlo-esign-faint); margin-bottom: 2px; }
  & span { display: flex; align-items: center; gap: 8px; }
  & i { width: 12px; height: 12px; border-radius: 50%; flex: none; }
}
.dlo-esign .st-signed { background: var(--dlo-esign-green); }
.dlo-esign .st-viewed { background: conic-gradient(var(--dlo-esign-amber) 0 50%, transparent 0); box-shadow: inset 0 0 0 2px var(--dlo-esign-amber); }
.dlo-esign .st-sent { box-shadow: inset 0 0 0 2px var(--dlo-esign-blue); }
.dlo-esign .st-queued { box-shadow: inset 0 0 0 1.5px var(--dlo-esign-faint); opacity: .7; }
.dlo-esign .st-declined { background: var(--dlo-esign-red); }

/* ---------- main */
.dlo-esign__main { grid-area: main; min-width: 0; min-height: 0; display: grid; grid-template-columns: minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); }
.dlo-esign__head { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 14px; padding: 14px 20px 12px; border-bottom: 1px solid var(--dlo-esign-line); }
.dlo-esign__ready {
  width: 58px; height: 58px; border-radius: 50%; display: grid; place-items: center;
  background: radial-gradient(closest-side, var(--dlo-esign-paper) 78%, transparent 80%), conic-gradient(var(--dlo-esign-green) var(--dlo-esign-p), var(--dlo-esign-hair) 0);
  transition: --dlo-esign-p 1.2s var(--dlo-esign-out);
  & span { font: 700 14px var(--dlo-esign-mono); font-variant-numeric: tabular-nums; letter-spacing: -.03em; }
}
.dlo-esign__title {
  min-width: 0;
  & p:first-child { font: 600 11px var(--dlo-esign-mono); color: var(--dlo-esign-blue); }
  & h2 { font-family: var(--dlo-esign-serif); font-size: clamp(20px, 2.4cqi, 26px); font-weight: 650; letter-spacing: -.015em; line-height: 1.1; }
}
.dlo-esign__sub { font-size: 12px; color: var(--dlo-esign-mute); margin-top: 2px; text-wrap: pretty; & b { color: var(--dlo-esign-ink); font-variant-numeric: tabular-nums; } }
.dlo-esign__hctl { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; justify-content: flex-end; }
.dlo-esign__tabs {
  display: flex; gap: 2px; padding: 3px; border-radius: 10px; background: var(--dlo-esign-wash);
  & button { padding: 5px 12px; border-radius: 7px; font-size: 12px; font-weight: 620; color: var(--dlo-esign-mute); transition: background-color .2s, color .2s; white-space: nowrap; }
  & button:hover { color: var(--dlo-esign-ink); }
  & button[aria-selected=true] { background: var(--dlo-esign-paper); color: var(--dlo-esign-ink); box-shadow: 0 1px 3px var(--dlo-esign-line); }
}
.dlo-esign__sim {
  display: inline-flex; align-items: center; gap: 7px; padding: 7px 12px; border-radius: 9px; font-size: 12px; font-weight: 650;
  background: var(--dlo-esign-blue); color: var(--dlo-esign-paper); transition: background-color .2s, transform .2s var(--dlo-esign-spring);
  &:hover { background: color-mix(in oklab, var(--dlo-esign-blue) 85%, var(--dlo-esign-ink)); }
  &:active { transform: scale(.96); }
  & svg { width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 1.9; stroke-linecap: round; }
  &[aria-disabled=true] { background: var(--dlo-esign-hair); color: var(--dlo-esign-faint); cursor: not-allowed; }
  &.is-busy svg { animation: dlo-esign-spin .8s linear infinite; }
}
.dlo-esign__views { position: relative; min-height: 0; }
.dlo-esign__view { height: 100%; min-height: 0; }
.dlo-esign__view[hidden] { display: none; }

/* ---------- matrix: rows are subgrids so row hover and column hover (via :has) both work */
.dlo-esign__mx { padding: 0 8px 14px 0; }
.dlo-esign__grid {
  display: grid; grid-template-columns: minmax(230px, 1.7fr) repeat(var(--n, 8), minmax(62px, 1fr)) 76px; min-width: 860px;
  font-variant-numeric: tabular-nums;
}
.dlo-esign__r { grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; border-bottom: 1px solid var(--dlo-esign-hair); position: relative; }
.dlo-esign__r.is-head { position: sticky; top: 0; z-index: 3; background: var(--dlo-esign-paper); border-bottom: 1px solid var(--dlo-esign-line); }
.dlo-esign__r:not(.is-head):hover { background: var(--dlo-esign-wash); }
.dlo-esign__r.is-sel { background: color-mix(in oklch, var(--dlo-esign-blue) 8%, transparent); }
.dlo-esign__r.is-out { display: none; }
.dlo-esign__env {
  position: sticky; left: 0; z-index: 2; display: grid; grid-template-columns: minmax(0, 1fr); align-content: center; gap: 2px; padding: 8px 10px 8px 20px; text-align: left;
