  & small { display: flex; align-items: center; gap: 6px; font-size: 11px; color: var(--dlo-esign-faint); white-space: nowrap; overflow: hidden; }
  & em { flex: none; font: 650 10px var(--dlo-esign-sans); font-style: normal; padding: 1px 7px; border-radius: 99px; background: var(--dlo-esign-hair); color: var(--dlo-esign-mute); white-space: nowrap; }
  & em.done { background: color-mix(in oklch, var(--dlo-esign-green) 16%, transparent); color: color-mix(in oklab, var(--dlo-esign-green) 70%, var(--dlo-esign-ink)); }
  & em.bad { background: color-mix(in oklch, var(--dlo-esign-red) 13%, transparent); color: var(--dlo-esign-red); }
  & em.void { text-decoration: line-through; }
  &:hover b { color: var(--dlo-esign-blue); }
}
.dlo-esign__who {
  display: grid; justify-items: center; align-content: end; gap: 3px; padding: 10px 2px 8px; text-align: center; border-radius: 8px;
  transition: background-color .2s;
  & i { display: grid; place-items: center; width: 26px; height: 26px; border-radius: 50%; font: 700 10px var(--dlo-esign-sans); font-style: normal; color: var(--dlo-esign-paper); background: var(--av); }
  & b { font-size: 11.5px; font-weight: 650; line-height: 1.15; }
  & small { font-size: 10px; color: var(--dlo-esign-faint); line-height: 1.2; }
  & u { text-decoration: none; font: 650 10px var(--dlo-esign-mono); color: var(--dlo-esign-red); }
