.dlo-esign__hcorner { padding: 12px 10px 8px 20px; display: grid; align-content: end; font-size: 10.5px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase; color: var(--dlo-esign-faint); }
.dlo-esign__prog {
