}
button.dlo-esign__c:hover .dot { transform: scale(1.3); }
button.dlo-esign__c[aria-expanded=true] .dot { box-shadow: 0 0 0 4px color-mix(in oklch, var(--dlo-esign-blue) 22%, transparent); }
.dlo-esign__c.is-stamp .dot { animation: dlo-esign-stamp .7s var(--dlo-esign-spring) both; }
.dlo-esign__c.is-stamp::after {
  content: ""; position: absolute; inset: 50% auto auto 50%; width: 16px; height: 16px; margin: -8px 0 0 -8px; border-radius: 50%;
  box-shadow: 0 0 0 2px var(--dlo-esign-green); animation: dlo-esign-ring .8s var(--dlo-esign-out) both; pointer-events: none;
}
.dlo-esign__c .age { position: absolute; bottom: 3px; font: 600 9px var(--dlo-esign-mono); color: var(--dlo-esign-faint); }
.dlo-esign__c .age.old { color: var(--dlo-esign-red); }
/* column crosshair: hover a signer's cell or header and their whole column lights up */
.dlo-esign__grid:has([data-c="0"]:hover) [data-c="0"], .dlo-esign__grid:has([data-c="1"]:hover) [data-c="1"],
.dlo-esign__grid:has([data-c="2"]:hover) [data-c="2"], .dlo-esign__grid:has([data-c="3"]:hover) [data-c="3"],
.dlo-esign__grid:has([data-c="4"]:hover) [data-c="4"], .dlo-esign__grid:has([data-c="5"]:hover) [data-c="5"],
.dlo-esign__grid:has([data-c="6"]:hover) [data-c="6"], .dlo-esign__grid:has([data-c="7"]:hover) [data-c="7"] { background-color: var(--dlo-esign-wash); }
.dlo-esign__grid.is-focus [data-c]:not(.is-col) { opacity: .35; }
.dlo-esign.is-enter .dlo-esign__c .dot { animation: dlo-esign-pop .5s var(--dlo-esign-spring) both; animation-delay: calc(var(--i) * 9ms + 120ms); }
@supports (animation-timeline: view()) {
  .dlo-esign__r:not(.is-head) { animation: dlo-esign-fade linear both; animation-timeline: view(); animation-range: entry 0% entry 60%; }
}

/* ---------- funnel + aging */
.dlo-esign__fv { padding: 16px 20px; display: grid; grid-template-columns: minmax(0, 1.2fr) minmax(0, 1fr); gap: 14px; align-content: start; }
