const reduce = matchMedia('(prefers-reduced-motion: reduce)');
const NS = 'http://www.w3.org/2000/svg';
const P = 'dlo-esign';

/* ---------- the closing set: who signs what, in which routing order */
const HOUR = 36e5;
const T0 = Date.UTC(2026, 9, 6, 14, 0);
const CLOSING = Date.UTC(2026, 9, 8, 10, 0);
const PEOPLE = [
  ['je', 'Jonas Ekberg', 'Ostrom Capital', 'Managing director', 262], ['lf', 'Lucía Ferraro', 'Ostrom Capital', 'General counsel', 262],
  ['aw', 'Amara Wendle', 'Seller', 'Founder & CEO', 156], ['ds', 'Dmitri Sokol', 'Seller', 'Co-founder', 156],
