  ['e4', 'Written consent of the board', 4, [['km', 'aw', 'ds']], [[40, 'km', 'sent'], [40, 'aw', 'sent'], [40, 'ds', 'sent'], [40, 'km', 'viewed'], [39, 'km', 'signed'], [23, 'aw', 'viewed'], [22, 'aw', 'signed']]],
  ['e5', 'Officer’s certificate', 2, [['aw']], [[2, 'aw', 'sent']]],
  ['e6', 'Payoff letter', 6, [['es'], ['aw']], [[28, 'es', 'sent'], [8, 'es', 'viewed']]],
  ['e7', 'Employment agreement', 19, [['ia'], ['lf']], [[26, 'ia', 'sent'], [11, 'ia', 'viewed'], [10, 'ia', 'signed'], [10, 'lf', 'sent']]],
  ['e8', 'Restrictive covenant agreement', 9, [['aw', 'ds'], ['lf']], [[25, 'aw', 'sent'], [25, 'ds', 'sent'], [17, 'aw', 'viewed'], [16, 'aw', 'signed'], [5, 'ds', 'viewed'], [4, 'ds', 'declined']]],
