].map(([id, name, pages, route, hist]) => ({ id, name, pages, route, ev: hist.map(([h, who, k]) => ({ t: T0 - h * HOUR, who, k })), void: false }));
ENV.forEach((e) => { e.ev.sort((a, b) => a.t - b.t); });
ENV[7].reason = 'Asked to narrow the non-compete radius from 50 to 25 miles';
/* what happens next, two hours at a time */
const SCRIPT = [
  [['e1', 'ds', 'signed'], ['e5', 'aw', 'viewed'], ['e6', 'es', 'signed']],
  [['e4', 'ds', 'viewed'], ['e1', 'je', 'viewed'], ['e5', 'aw', 'signed'], ['e6', 'aw', 'viewed']],
  [['e4', 'ds', 'signed'], ['e10', 'ds', 'signed'], ['e2', 'je', 'viewed'], ['e2', 'je', 'signed']],
  [['e1', 'je', 'signed'], ['e3', 'aw', 'signed'], ['e7', 'lf', 'viewed'], ['e7', 'lf', 'signed']],
  [['e3', 'ap', 'viewed'], ['e6', 'aw', 'signed']],
  [['e3', 'ap', 'signed']]
];
const ENVM = Object.fromEntries(ENV.map((e) => [e.id, e]));

/* ---------- derived state */
const state = { now: T0, step: 0, folder: 'all', tab: 'matrix', open: null, pop: null, focus: null, reminded: {}, confirmVoid: false, extra: [] };
function cellState(e, who) {
  if (!e.route.flat().includes(who)) return null;
  const mine = e.ev.filter((x) => x.who === who && (x.k === 'sent' || x.k === 'viewed' || x.k === 'signed' || x.k === 'declined'));
