const complete = (e) => signedN(e) === signers(e).length;
const blocked = (e) => signers(e).some((w) => cellState(e, w).k === 'declined');
const pendingCells = () => ENV.filter((e) => !e.void).flatMap((e) => signers(e).map((w) => ({ e, w, s: cellState(e, w) }))).filter((c) => c.s.k === 'sent' || c.s.k === 'viewed');
/* when a routing stage is fully signed, the next stage is sent automatically */
function advanceRouting(e, t) {
  for (let i = 0; i < e.route.length - 1; i++) {
    const done = e.route[i].every((w) => cellState(e, w).k === 'signed');
