}
const hrs = (ms) => Math.max(0, Math.round(ms / HOUR));
const DOW = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'], MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const stamp = (t) => { const d = new Date(t); return DOW[d.getUTCDay()] + ' ' + String(d.getUTCHours()).padStart(2, '0') + ':' + String(d.getUTCMinutes()).padStart(2, '0'); };
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const avc = (p) => `oklch(0.55 0.12 ${p.hue})`;
const ST = { signed: 'Signed', viewed: 'Opened, not signed', sent: 'Sent, not opened', queued: 'Waiting on an earlier signer', declined: 'Declined', void: 'Voided' };
const ICON = { signed: '<svg viewBox="0 0 16 16"><path d="m4.5 8.3 2.3 2.2 4.7-5"/></svg>', declined: '<svg viewBox="0 0 16 16"><path d="m5.3 5.3 5.4 5.4M10.7 5.3l-5.4 5.4"/></svg>' };

const grid = $('.' + P + '__grid');
const pop = $('.' + P + '__pop');
const drawer = $('.' + P + '__drawer');
const dbody = $('.' + P + '__dbody');
const tip = $('.' + P + '__tip');
const toasts = $('.' + P + '__toasts');
function toast(msg) {
  const t = document.createElement('div');
