/* ---------- folders */
const FOLDERS = [
  ['all', 'All envelopes', () => true, '<path d="M4 7.5h16v11H4z"/><path d="m4 7.5 8 6 8-6"/>'],
  ['attn', 'Needs attention', (e) => !e.void && !complete(e) && (blocked(e) || signers(e).some((w) => { const s = cellState(e, w); return (s.k === 'sent' || s.k === 'viewed') && state.now - s.sent > 24 * HOUR; })), '<path d="M12 4 3 19.5h18z"/><path d="M12 10v4.5M12 17v.2"/>'],
