    if (e.key === 'ArrowDown') for (let k = ri + 1; k < rows.length && !n; k++) { const x = pick(rows[k], ci); if (x && x.tagName === 'BUTTON') n = x; }
    if (e.key === 'ArrowUp') for (let k = ri - 1; k >= 0 && !n; k--) { const x = pick(rows[k], ci); if (x && x.tagName === 'BUTTON') n = x; }
    if (n) n.focus();
    return;
  }
  const tb = e.target.closest && e.target.closest('[role=tab]');
  if (tb && /^Arrow(Left|Right)$/.test(e.key)) { e.preventDefault(); const o = $$('[role=tab]').find((b) => b !== tb); o.click(); o.focus(); }
});
$('.' + P + '__funnel').addEventListener('pointermove', (ev) => {
  const g = ev.target.closest('.st');
  if (!g) { tip.hidden = true; return; }
  tip.innerHTML = `<b>${g.querySelector('.lb').textContent} · ${g.querySelector('.vl').textContent}</b><span>${g.querySelector('.cv').textContent} of required signatures</span>`;
  tip.hidden = false;
  const r = root.getBoundingClientRect();
  tip.style.translate = Math.min(r.width - tip.offsetWidth - 8, ev.clientX - r.left + 14) + 'px ' + (ev.clientY - r.top + 14) + 'px';
});
$('.' + P + '__funnel').addEventListener('pointerleave', () => { tip.hidden = true; });

/* ---------- mount */
ENV.forEach((e) => advanceRouting(e, T0));
if (!reduce.matches) { root.classList.add('is-enter'); setTimeout(() => root.classList.remove('is-enter'), 1500); }
renderAll();
let rz = 0, lastW = root.clientWidth;
const ro = new ResizeObserver(() => {
  cancelAnimationFrame(rz);
  rz = requestAnimationFrame(() => {
    if (!root.isConnected) { ro.disconnect(); return; }
    if (root.clientWidth !== lastW) { lastW = root.clientWidth; closePop(); if (state.tab === 'funnel') renderFunnel(); }
  });
});
ro.observe(root);

css:
@property --dlo-matter-sweep {
  syntax: "<angle>";
  inherits: false;
  initial-value: 0deg;
}

.dlo-matter {
  /* re-theme with these four */
  --dlo-matter-bg: oklch(0.185 0.009 48);
  --dlo-matter-ink: oklch(0.945 0.012 80);
  --dlo-matter-ember: oklch(0.66 0.19 33);
  --dlo-matter-olive: oklch(0.66 0.1 128);
  /* derived: the heat ramp runs olive → amber → ember */
  --dlo-matter-amber: color-mix(in oklch, var(--dlo-matter-ember) 35%, oklch(0.82 0.15 82));
  --dlo-matter-rail: color-mix(in oklch, var(--dlo-matter-bg) 78%, black);
  --dlo-matter-panel: color-mix(in oklch, var(--dlo-matter-bg) 94%, var(--dlo-matter-ink));
  --dlo-matter-raise: color-mix(in oklch, var(--dlo-matter-bg) 87%, var(--dlo-matter-ink));
  --dlo-matter-line: color-mix(in oklch, var(--dlo-matter-ink) 10%, transparent);
  --dlo-matter-soft: color-mix(in oklch, var(--dlo-matter-ink) 6%, transparent);
  --dlo-matter-mute: color-mix(in oklch, var(--dlo-matter-ink) 62%, var(--dlo-matter-bg));
  --dlo-matter-faint: color-mix(in oklch, var(--dlo-matter-ink) 40%, var(--dlo-matter-bg));
  --dlo-matter-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dlo-matter-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dlo-matter-out: cubic-bezier(.16, 1, .3, 1);
  --dlo-matter-spring: linear(0, 0.008, 0.032 2%, 0.13 4.3%, 0.593 12.3%, 0.84 17%, 0.978 21.5%, 1.04 25.3%, 1.066 29.1%, 1.063 33.1%, 1.017 43.4%, 0.995 51.1%, 0.996 63.6%, 1);

  width: 100%;
  height: var(--dlo-matter-h, 680px);
  container-type: inline-size; container-name: dlo-matter;
  position: relative; isolation: isolate; overflow: hidden;
  border-radius: 16px;
  background: var(--dlo-matter-bg); color: var(--dlo-matter-ink);
  font: 13px/1.45 var(--dlo-matter-sans);
  accent-color: var(--dlo-matter-ember);
  color-scheme: dark;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, h4, p, ol, dl, dd, table) { margin: 0; padding: 0; }
  & :where(ol) { list-style: none; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
  & :where(svg) { display: block; }
  & :focus-visible { outline: 2px solid var(--dlo-matter-amber); outline-offset: 2px; border-radius: 6px; }
  & .dlo-matter__scroll {
    overflow: auto; overscroll-behavior: contain;
    scrollbar-width: thin; scrollbar-color: color-mix(in oklch, var(--dlo-matter-ink) 18%, transparent) transparent;
  }
}
.dlo-matter__shell { height: 100%; display: grid; grid-template-columns: 68px minmax(0, 1fr); grid-template-areas: "rail main"; }

/* ---------- rail */
.dlo-matter__rail {
  grid-area: rail; display: flex; flex-direction: column; align-items: center; gap: 4px; padding: 14px 6px;
  background: var(--dlo-matter-rail); border-right: 1px solid var(--dlo-matter-line);
  & button { width: 56px; display: grid; justify-items: center; gap: 3px; padding: 8px 0 6px; border-radius: 10px; color: var(--dlo-matter-faint); font-size: 10px; font-weight: 620; transition: background-color .2s, color .2s; }
  & button:hover { color: var(--dlo-matter-ink); background: var(--dlo-matter-soft); }
  & button[aria-current=page] { color: var(--dlo-matter-ink); background: color-mix(in oklch, var(--dlo-matter-ember) 16%, transparent); }
  & button[aria-current=page] svg { stroke: var(--dlo-matter-ember); }
  & svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
}
.dlo-matter__mark {
  display: grid; place-items: center; width: 38px; height: 38px; margin-bottom: 12px; border-radius: 11px;
  background: conic-gradient(from var(--dlo-matter-sweep), var(--dlo-matter-olive), var(--dlo-matter-amber), var(--dlo-matter-ember), var(--dlo-matter-olive));
  animation: dlo-matter-sweep 9s linear infinite paused;
  .dlo-matter.is-live & { animation-play-state: running; }
  & svg { width: 20px; height: 20px; fill: none; stroke: var(--dlo-matter-bg); stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
}

/* ---------- main + header */
.dlo-matter__main { grid-area: main; min-width: 0; min-height: 0; display: grid; grid-template-columns: minmax(0, 1fr); grid-template-rows: auto auto minmax(0, 1fr); }
.dlo-matter__head { display: flex; align-items: flex-end; justify-content: space-between; gap: 14px; padding: 16px 20px 10px; flex-wrap: wrap; }
.dlo-matter__title {
  & p { font-size: 11px; font-weight: 600; letter-spacing: .07em; text-transform: uppercase; color: var(--dlo-matter-amber); }
  & h2 { font-size: clamp(19px, 2.3cqi, 25px); font-weight: 720; letter-spacing: -.025em; line-height: 1.1; text-wrap: balance; }
}
.dlo-matter__ctl { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.dlo-matter__seg {
  display: flex; gap: 2px; padding: 3px; border-radius: 10px; background: var(--dlo-matter-soft);
  & button { padding: 5px 10px; border-radius: 7px; font: 600 12px var(--dlo-matter-mono); color: var(--dlo-matter-mute); transition: background-color .2s, color .2s; white-space: nowrap; }
  & button:hover { color: var(--dlo-matter-ink); }
  & button[aria-checked=true] { background: var(--dlo-matter-raise); color: var(--dlo-matter-ink); box-shadow: 0 1px 2px black; }
}
.dlo-matter__switch {
  display: inline-flex; align-items: center; gap: 8px; font-size: 12px; font-weight: 620; color: var(--dlo-matter-mute);
  & i { position: relative; width: 30px; height: 18px; border-radius: 9px; background: var(--dlo-matter-soft); box-shadow: inset 0 0 0 1px var(--dlo-matter-line); transition: background-color .2s; }
  & i::after { content: ""; position: absolute; top: 3px; left: 3px; width: 12px; height: 12px; border-radius: 50%; background: var(--dlo-matter-mute); transition: translate .35s var(--dlo-matter-spring), background-color .2s; }
  &[aria-checked=true] { color: var(--dlo-matter-ink); }
  &[aria-checked=true] i { background: color-mix(in oklch, var(--dlo-matter-ember) 40%, transparent); }
  &[aria-checked=true] i::after { translate: 12px 0; background: var(--dlo-matter-ink); }
}
.dlo-matter__switch[hidden] { display: none; }
.dlo-matter__kpis {
  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 1px; margin: 0 20px 12px; border-radius: 12px; overflow: hidden; background: var(--dlo-matter-line);
  & > div { padding: 10px 14px; background: var(--dlo-matter-panel); min-width: 0; }
  & dt { font-size: 11px; font-weight: 600; color: var(--dlo-matter-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & dd { font-size: clamp(18px, 2.2cqi, 24px); font-weight: 720; letter-spacing: -.03em; font-variant-numeric: tabular-nums; line-height: 1.2; }
  & small { display: block; font-size: 11.5px; color: var(--dlo-matter-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-variant-numeric: tabular-nums; }
  & .up { color: var(--dlo-matter-ember); }
  & .dn { color: var(--dlo-matter-olive); }
}
.dlo-matter__views { position: relative; min-height: 0; }
.dlo-matter__view { height: 100%; min-height: 0; }
.dlo-matter__view[hidden] { display: none; }

/* ---------- map view */
.dlo-matter__mv {
  display: grid; gap: 12px; padding: 0 20px 14px;
  grid-template-columns: minmax(0, 1fr) minmax(250px, 320px); grid-template-rows: minmax(0, 1fr) auto;
  grid-template-areas: "map side" "stages stages";
}
.dlo-matter__mapwrap {
  grid-area: map; min-height: 0; display: grid; grid-template-columns: 22px minmax(0, 1fr); grid-template-rows: minmax(0, 1fr) auto; gap: 4px 6px;
}
.dlo-matter__ylab { writing-mode: vertical-rl; rotate: 180deg; text-align: center; font-size: 10.5px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase; color: var(--dlo-matter-faint); }
.dlo-matter__xlab {
  grid-column: 2; display: grid; grid-template-columns: 56px repeat(5, minmax(0, 1fr)); text-align: center; font: 600 10.5px var(--dlo-matter-mono); color: var(--dlo-matter-faint);
  & span:last-child { grid-column: 2 / -1; font: 650 10.5px var(--dlo-matter-sans); letter-spacing: .08em; text-transform: uppercase; margin-top: 2px; }
}
.dlo-matter__map { position: relative; min-height: 0; }
.dlo-matter__cells {
  position: absolute; inset: 0; display: grid; grid-template-columns: 56px repeat(5, minmax(0, 1fr)); grid-template-rows: repeat(5, minmax(0, 1fr)); gap: 3px;
  & .yl { display: grid; place-items: center; font: 650 10.5px var(--dlo-matter-mono); color: var(--dlo-matter-faint); text-align: center; line-height: 1.1; }
  & .yl small { display: block; font: 600 8.5px var(--dlo-matter-sans); letter-spacing: .03em; text-transform: uppercase; text-wrap: balance; margin-top: 2px; }
}
.dlo-matter__cell {
  position: relative; border-radius: 8px; background: color-mix(in oklch, var(--heat) var(--a, 22%), var(--dlo-matter-bg));
  box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--heat) 30%, transparent);
  transition: background-color .3s, box-shadow .2s, opacity .3s;
  & span { position: absolute; right: 6px; bottom: 4px; font: 600 9.5px var(--dlo-matter-mono); color: color-mix(in oklch, var(--heat) 70%, var(--dlo-matter-ink)); opacity: .55; }
  &:hover { box-shadow: inset 0 0 0 1.5px var(--heat); }
  &[aria-pressed=true] { box-shadow: inset 0 0 0 2px var(--dlo-matter-ink); --a: 42%; }
  .dlo-matter__cells:has([aria-pressed=true]) &:not([aria-pressed=true]) { opacity: .45; }
}
.dlo-matter__trails {
  position: absolute; inset: 0; width: 100%; height: 100%; pointer-events: none; overflow: visible;
  & path { fill: none; stroke: var(--dlo-matter-ink); stroke-width: 1.5; stroke-linecap: round; opacity: .55; stroke-dasharray: 1; stroke-dashoffset: 1; animation: dlo-matter-draw .9s var(--dlo-matter-out) forwards; animation-delay: calc(var(--i) * 40ms + 350ms); }
  & path.up { stroke: var(--dlo-matter-ember); opacity: .9; }
  & path.dn { stroke: var(--dlo-matter-olive); opacity: .9; }
  & path.head { stroke-dasharray: none; stroke-dashoffset: 0; animation: dlo-matter-fade .3s both; animation-delay: calc(var(--i) * 40ms + 1s); }
  & circle { fill: var(--dlo-matter-ink); opacity: .35; }
}
.dlo-matter__dots { position: absolute; inset: 0; pointer-events: none; }
.dlo-matter__dot {
  position: absolute; left: 0; top: 0; width: 26px; height: 26px; margin: -13px 0 0 -13px; border-radius: 50%; pointer-events: auto;
  display: grid; place-items: center; font: 700 10.5px var(--dlo-matter-mono); color: var(--dlo-matter-bg);
  background: var(--dlo-matter-ink); box-shadow: 0 0 0 2.5px var(--ring, var(--dlo-matter-bg)), 0 4px 12px -2px black;
  translate: var(--x) var(--y);
  transition: translate .9s var(--dlo-matter-spring), opacity .3s, scale .25s var(--dlo-matter-spring);
  transition-delay: calc(var(--i) * 28ms), 0s, 0s;
  &:hover, &:focus-visible { scale: 1.22; z-index: 2; }
  &.up { --ring: var(--dlo-matter-ember); }
  &.dn { --ring: var(--dlo-matter-olive); }
  &.is-dim { opacity: .18; }
  &.is-sel { scale: 1.25; box-shadow: 0 0 0 2.5px var(--ring, var(--dlo-matter-bg)), 0 0 0 6px color-mix(in oklch, var(--dlo-matter-ink) 30%, transparent); }
  @starting-style { opacity: 0; scale: .2; }
}

.dlo-matter__side { grid-area: side; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); border-radius: 12px; background: var(--dlo-matter-panel); box-shadow: inset 0 0 0 1px var(--dlo-matter-line); overflow: hidden; }
.dlo-matter__lh { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 12px 14px 8px; & h3 { font-size: 13px; font-weight: 650; min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; } }
.dlo-matter__clear { flex: none; font-size: 11.5px; font-weight: 650; padding: 3px 9px; border-radius: 99px; background: var(--dlo-matter-ink); color: var(--dlo-matter-bg); }
.dlo-matter__clear[hidden] { display: none; }
.dlo-matter__list { padding: 0 6px 8px; display: grid; align-content: start; gap: 1px; }
.dlo-matter__li {
  width: 100%; display: grid; grid-template-columns: 24px minmax(0, 1fr) auto; grid-template-rows: auto auto; align-items: center; gap: 1px 10px; padding: 7px 8px; border-radius: 9px;
  transition: background-color .18s;
  &:hover { background: var(--dlo-matter-soft); }
  &[aria-current=true] { background: var(--dlo-matter-raise); box-shadow: inset 0 0 0 1px var(--dlo-matter-line); }
  & > i { grid-row: span 2; display: grid; place-items: center; width: 22px; height: 22px; border-radius: 50%; font: 700 10px var(--dlo-matter-mono); font-style: normal; background: var(--dlo-matter-ink); color: var(--dlo-matter-bg); box-shadow: 0 0 0 2px var(--ring, transparent); }
  &.up > i { --ring: var(--dlo-matter-ember); }
  &.dn > i { --ring: var(--dlo-matter-olive); }
  & b { font-size: 12.5px; font-weight: 620; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & small { grid-column: 2; font-size: 11px; color: var(--dlo-matter-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .sc { grid-row: span 2; display: grid; justify-items: end; font: 700 13px var(--dlo-matter-mono); font-variant-numeric: tabular-nums; }
  & .sc small { font: 600 10px var(--dlo-matter-mono); color: var(--dlo-matter-faint); }
  & .sc .up { color: var(--dlo-matter-ember); }
  & .sc .dn { color: var(--dlo-matter-olive); }
}
@supports (animation-timeline: view()) {
  .dlo-matter__li { animation: dlo-matter-rise linear both; animation-timeline: view(); animation-range: entry 0% entry 70%; }
}

.dlo-matter__stages {
  grid-area: stages; display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); gap: 6px;
  & button { display: grid; gap: 5px; padding: 8px 10px; border-radius: 10px; background: var(--dlo-matter-panel); box-shadow: inset 0 0 0 1px var(--dlo-matter-line); text-align: left; min-width: 0; transition: background-color .2s, box-shadow .2s, opacity .2s; }
  & button:hover { background: var(--dlo-matter-raise); }
  & button[aria-pressed=true] { box-shadow: inset 0 0 0 1.5px var(--dlo-matter-ink); background: var(--dlo-matter-raise); }
  &:has([aria-pressed=true]) button:not([aria-pressed=true]) { opacity: .55; }
  & b { display: flex; justify-content: space-between; align-items: baseline; gap: 6px; font-size: 11.5px; font-weight: 620; color: var(--dlo-matter-mute); white-space: nowrap; overflow: hidden; }
  & b span { font: 700 15px var(--dlo-matter-mono); color: var(--dlo-matter-ink); }
  & .bar { display: flex; height: 6px; border-radius: 3px; overflow: hidden; background: var(--dlo-matter-soft); }
  & .bar i { height: 100%; width: var(--w); transition: width .7s var(--dlo-matter-out); }
  & .t0 { background: var(--dlo-matter-olive); } & .t1 { background: var(--dlo-matter-amber); } & .t2 { background: var(--dlo-matter-ember); }
}

/* ---------- reserve bridge */
.dlo-matter__bv { padding: 0 20px 16px; display: grid; grid-template-columns: minmax(0, 1.4fr) minmax(0, 1fr); gap: 12px; align-content: start; }
.dlo-matter__card { padding: 14px 16px; border-radius: 12px; background: var(--dlo-matter-panel); box-shadow: inset 0 0 0 1px var(--dlo-matter-line); min-width: 0; & h3 { font-size: 13px; font-weight: 650; } }
.dlo-matter__ch { display: flex; justify-content: space-between; align-items: baseline; gap: 10px; flex-wrap: wrap; & p { font-size: 11.5px; color: var(--dlo-matter-mute); } }
.dlo-matter__wf {
  width: 100%; height: 300px; overflow: visible; margin-top: 10px;
  & .gl { stroke: var(--dlo-matter-line); }
  & .ax { font: 500 10px var(--dlo-matter-mono); fill: var(--dlo-matter-faint); }
  & .lb { font: 600 11px var(--dlo-matter-sans); fill: var(--dlo-matter-mute); }
  & .vl { font: 700 11.5px var(--dlo-matter-mono); fill: var(--dlo-matter-ink); font-variant-numeric: tabular-nums; }
  & .tot { fill: var(--dlo-matter-ink); }
  & .add { fill: var(--dlo-matter-ember); }
  & .sub { fill: var(--dlo-matter-olive); }
  & .cn { stroke: var(--dlo-matter-faint); stroke-dasharray: 3 3; }
  & .bar { transform-box: fill-box; transform-origin: 50% 100%; animation: dlo-matter-grow .7s var(--dlo-matter-out) both; animation-delay: calc(var(--i) * 80ms); }
  & .bar.sub { transform-origin: 50% 0; }
  & g.st:hover .bar { filter: brightness(1.2); }
}
.dlo-matter__rt {
  width: 100%; border-collapse: collapse; margin-top: 8px; font-variant-numeric: tabular-nums;
  & th { text-align: right; font-size: 10.5px; font-weight: 650; letter-spacing: .06em; text-transform: uppercase; color: var(--dlo-matter-faint); padding: 6px 6px; border-bottom: 1px solid var(--dlo-matter-line); }
  & th:first-child, & td:first-child { text-align: left; }
  & td { text-align: right; padding: 7px 6px; border-bottom: 1px solid var(--dlo-matter-soft); font-size: 12px; white-space: nowrap; }
  & td:first-child { white-space: normal; }
  & td b { font-weight: 620; }
  & td small { display: block; color: var(--dlo-matter-faint); font-size: 11px; }
  & .up { color: var(--dlo-matter-ember); } & .dn { color: var(--dlo-matter-olive); }
  & tfoot td { font-weight: 700; border-bottom: 0; }
  & tbody tr { cursor: pointer; transition: background-color .15s; }
  & tbody tr:hover { background: var(--dlo-matter-soft); }
  & tbody tr:focus-visible { outline: 2px solid var(--dlo-matter-amber); outline-offset: -2px; }
}

/* ---------- drawer */
.dlo-matter__drawer {
  position: absolute; z-index: 6; inset: 10px 10px 10px auto; width: min(380px, calc(100% - 20px)); display: flex; flex-direction: column; border-radius: 14px;
  background: var(--dlo-matter-raise); box-shadow: 0 0 0 1px var(--dlo-matter-line), 0 30px 60px -20px black;
  transform: translateX(calc(100% + 24px)); opacity: 0; visibility: hidden;
  transition: transform .5s var(--dlo-matter-out), opacity .3s, visibility 0s .5s;
  &[data-open] { transform: none; opacity: 1; visibility: visible; transition: transform .5s var(--dlo-matter-out), opacity .2s, visibility 0s; }
}
.dlo-matter__dbody { flex: 1; min-height: 0; overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; padding: 16px 18px; display: grid; align-content: start; gap: 14px; }
.dlo-matter__dtop {
  display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 10px;
  & p { font: 600 11px var(--dlo-matter-mono); color: var(--dlo-matter-amber); }
  & h3 { font-size: 18px; font-weight: 720; letter-spacing: -.02em; line-height: 1.2; text-wrap: balance; margin-top: 3px; }
}
.dlo-matter__x { display: grid; place-items: center; width: 30px; height: 30px; border-radius: 8px; color: var(--dlo-matter-mute); &:hover { background: var(--dlo-matter-soft); color: var(--dlo-matter-ink); } & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; } }
.dlo-matter__sect { display: grid; gap: 8px; & h4 { font-size: 10.5px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase; color: var(--dlo-matter-faint); } }
.dlo-matter__range {
  position: relative; height: 34px;
  & .tr { position: absolute; left: 0; right: 0; top: 12px; height: 8px; border-radius: 4px; background: var(--dlo-matter-soft); }
  & .rg { position: absolute; top: 12px; height: 8px; border-radius: 4px; background: linear-gradient(90deg, var(--dlo-matter-amber), var(--dlo-matter-ember)); }
  & .rs { position: absolute; top: 6px; width: 2px; height: 20px; border-radius: 1px; background: var(--dlo-matter-ink); }
  & span { position: absolute; top: 24px; font: 600 10.5px var(--dlo-matter-mono); color: var(--dlo-matter-mute); white-space: nowrap; }
}
.dlo-matter__steps {
  display: grid; grid-template-columns: repeat(7, 1fr); gap: 3px;
  & i { height: 6px; border-radius: 3px; background: var(--dlo-matter-soft); }
  & i.on { background: var(--dlo-matter-ink); }
  & i.now { background: var(--dlo-matter-amber); }
}
.dlo-matter__hist {
  width: 100%; height: 90px; overflow: visible;
  & .gl { stroke: var(--dlo-matter-line); }
  & .ax { font: 600 10px var(--dlo-matter-mono); fill: var(--dlo-matter-faint); }
  & path { fill: none; stroke: var(--dlo-matter-amber); stroke-width: 2; stroke-linejoin: round; }
  & circle { fill: var(--dlo-matter-raise); stroke: var(--dlo-matter-amber); stroke-width: 2; }
  & circle.now { fill: var(--dlo-matter-amber); }
  & .vl { font: 700 10.5px var(--dlo-matter-mono); fill: var(--dlo-matter-ink); }
}
.dlo-matter__facts { display: grid; grid-template-columns: 1fr 1fr; gap: 1px; margin: 0; border-radius: 10px; overflow: hidden; background: var(--dlo-matter-line); & div { background: var(--dlo-matter-panel); padding: 8px 10px; } & dt { font-size: 10.5px; color: var(--dlo-matter-mute); } & dd { margin: 0; font-weight: 650; font-size: 12.5px; } }
.dlo-matter__acts {
  display: grid; gap: 6px;
  & button { padding: 10px 12px; border-radius: 9px; font-weight: 650; text-align: center; box-shadow: inset 0 0 0 1px var(--dlo-matter-line); transition: background-color .2s, transform .2s var(--dlo-matter-spring); }
  & button:hover { background: var(--dlo-matter-soft); }
  & button:active { transform: scale(.98); }
  & .pri { background: var(--dlo-matter-ink); color: var(--dlo-matter-bg); box-shadow: none; }
  & .pri:hover { background: color-mix(in oklch, var(--dlo-matter-ink) 85%, var(--dlo-matter-ember)); }
  & .pri[aria-pressed=true] { background: var(--dlo-matter-ember); color: var(--dlo-matter-bg); }
  & button[aria-disabled=true] { opacity: .45; cursor: not-allowed; transform: none; }
}

/* ---------- tooltip + toasts */
.dlo-matter__tip {
  position: absolute; z-index: 8; left: 0; top: 0; pointer-events: none; max-width: 260px; padding: 8px 10px; border-radius: 9px;
  background: var(--dlo-matter-ink); color: var(--dlo-matter-bg); font-size: 11.5px; box-shadow: 0 12px 28px -10px black;
  & b { display: block; font-weight: 700; }
  & span { display: block; opacity: .82; font-variant-numeric: tabular-nums; }
}
.dlo-matter__toasts { position: absolute; z-index: 9; left: 50%; bottom: 16px; translate: -50% 0; display: grid; gap: 6px; justify-items: center; pointer-events: none; }
.dlo-matter__toast {
  padding: 9px 14px; border-radius: 10px; background: var(--dlo-matter-ink); color: var(--dlo-matter-bg); font-size: 12px; font-weight: 650; white-space: nowrap;
  box-shadow: 0 14px 30px -12px black; transition: opacity .3s, transform .45s var(--dlo-matter-spring);
  @starting-style { opacity: 0; transform: translateY(10px) scale(.96); }
  &.is-out { opacity: 0; transform: translateY(6px); }
}

@keyframes dlo-matter-sweep { to { --dlo-matter-sweep: 360deg; } }
@keyframes dlo-matter-draw { to { stroke-dashoffset: 0; } }
@keyframes dlo-matter-fade { from { opacity: 0; } }
@keyframes dlo-matter-rise { from { opacity: 0; transform: translateY(8px); } }
@keyframes dlo-matter-grow { from { transform: scaleY(0); } }

/* ---------- responsive */
@container dlo-matter (width < 960px) {
  .dlo-matter__mv { grid-template-columns: minmax(0, 1fr) 250px; }
  .dlo-matter__stages b { font-size: 10.5px; }
  .dlo-matter__bv { grid-template-columns: minmax(0, 1fr); }
}
@container dlo-matter (width < 760px) {
  .dlo-matter__shell { grid-template-columns: minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); grid-template-areas: "rail" "main"; }
  .dlo-matter__rail { flex-direction: row; padding: 6px 10px; border-right: 0; border-bottom: 1px solid var(--dlo-matter-line); & button { width: auto; grid-auto-flow: column; gap: 6px; padding: 7px 10px; font-size: 11.5px; } }
  .dlo-matter__mark { margin: 0 8px 0 0; width: 32px; height: 32px; }
  .dlo-matter__main { overflow: auto; scrollbar-width: thin; grid-template-rows: max-content max-content max-content; }
  .dlo-matter__head { padding: 12px 14px 8px; }
  .dlo-matter__kpis { grid-template-columns: repeat(2, minmax(0, 1fr)); margin: 0 14px 12px; }
  .dlo-matter__mv { padding: 0 14px 14px; grid-template-columns: minmax(0, 1fr); grid-template-rows: 340px max-content max-content; grid-template-areas: "map" "stages" "side"; }
  .dlo-matter__side { overflow: visible; }
  .dlo-matter .dlo-matter__list { overflow: visible; }
  .dlo-matter__stages { grid-template-columns: repeat(4, minmax(0, 1fr)); }
  .dlo-matter__bv { padding: 0 14px 14px; }
}
@container dlo-matter (width < 480px) {
  .dlo-matter__rail span { display: none; }
  .dlo-matter__mv { grid-template-rows: 300px max-content max-content; }
  .dlo-matter__dot { width: 20px; height: 20px; margin: -10px 0 0 -10px; font-size: 9px; }
  .dlo-matter__xlab { font-size: 9px; }
  .dlo-matter__stages { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

@media (prefers-reduced-motion: reduce) {
  .dlo-matter *, .dlo-matter *::before, .dlo-matter *::after {
    animation-duration: 1ms !important; animation-delay: 0ms !important; animation-iteration-count: 1 !important;
    transition-duration: 1ms !important; transition-delay: 0ms !important;
  }
  .dlo-matter .dlo-matter__li { animation: none; }
  .dlo-matter .dlo-matter__mark { animation: none; }
}

