const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => Array.from(el.querySelectorAll(s));
const reduce = matchMedia('(prefers-reduced-motion: reduce)');
const NS = 'http://www.w3.org/2000/svg';
const P = 'dlo-matter';

/* ---------- portfolio: likelihood (1-5) and exposure band (1-5) per quarter */
const Q = ['Q4 ’25', 'Q1 ’26', 'Q2 ’26', 'Q3 ’26'];
const STAGES = ['Pre-suit', 'Pleadings', 'Discovery', 'Motions', 'Trial', 'Appeal', 'Resolved'];
const BANDS = [[0.2, 1], [1, 5], [5, 20], [20, 50], [50, 150]];
const BANDLBL = ['<$1M', '$1–5M', '$5–20M', '$20–50M', '>$50M'];
const LIKE = ['Remote', 'Unlikely', 'Possible', 'Likely', 'Very likely'];
const PCT = [0.05, 0.2, 0.45, 0.7, 0.9];
const M = [
  ['Halloran Ranch v. Corvane', 'Pipeline easement trespass', 'District court, Elko County', 'Pryor Danvers LLP', [2, 3, 3, 4], [3, 3, 3, 3], [1, 2, 2, 3], [0.2, 0.7], 'Summary judgment hearing, 19 Nov'],
  ['State emissions inquiry', 'Regulatory investigation', 'State attorney general', 'Strand & Wilcox', [2, 2, 3, 3], [4, 4, 4, 4], [0, 0, 0, 0], [0.1, 0.6], 'Document production due 30 Oct'],
  ['Brightwater Utilities arbitration', 'Power purchase price dispute', 'Arbitral tribunal (3 members)', 'Halvard Kenney LLP', [3, 3, 4, 4], [4, 5, 5, 5], [1, 2, 2, 3], [0.15, 0.55], 'Merits hearing, 12–16 Jan'],
  ['Delgado royalty class action', 'Royalty underpayment', 'Federal district court', 'Pryor Danvers LLP', [3, 3, 3, 2], [4, 4, 4, 4], [2, 2, 3, 3], [0.3, 0.8], 'Class certification ruling expected'],
  ['Tern Valley wildfire claims', 'Mass tort and subrogation', 'Coordinated state proceedings', 'Benning Moss LLP', [4, 4, 4, 5], [4, 5, 5, 5], [1, 1, 2, 2], [0.1, 0.45], 'Bellwether selection, 4 Dec'],
  ['Mesa Fabricators delay claim', 'Construction delay', 'Construction arbitration', 'Halvard Kenney LLP', [2, 2, 2, 2], [2, 2, 3, 3], [1, 2, 2, 2], [0.4, 0.9], 'Expert reports due 20 Nov'],
  ['Ashworth v. Corvane', 'Employment retaliation', 'State superior court', 'Lyle & Ibarra', [2, 3, 3, 3], [1, 1, 2, 2], [1, 1, 2, 2], [0.3, 0.9], 'Plaintiff’s deposition, 28 Oct'],
  ['Sunlattice v. Corvane', 'Patent: inverter controls', 'Federal district court', 'Pell & Sato LLP', [1, 2, 2, 2], [3, 4, 4, 4], [1, 1, 2, 3], [0.2, 0.7], 'Claim construction order pending'],
  ['Kettle Rock safety citation', 'Workplace safety', 'Administrative review board', 'In-house', [3, 3, 2, 2], [1, 1, 1, 1], [0, 1, 1, 6], [0.2, 0.6], 'Informal settlement signed'],
  ['Rio Blanco water rights', 'Water adjudication', 'Water court, Division 4', 'Benning Moss LLP', [2, 2, 2, 2], [3, 3, 3, 3], [2, 2, 2, 2], [0.1, 0.5], 'Status conference, 9 Dec'],
  ['Northlake Turbines warranty', 'Warranty claim (Corvane as claimant)', 'Federal district court', 'Halvard Kenney LLP', [1, 1, 1, 1], [2, 2, 2, 2], [1, 1, 2, 2], [0.2, 0.6], 'Mediation, 3 Nov'],
  ['Shareholder derivative demand', 'Board oversight', 'Special committee of the board', 'Strand & Wilcox', [1, 1, 2, 2], [4, 4, 4, 5], [0, 0, 0, 0], [0.2, 0.7], 'Committee report due in Q4'],
  ['Pinecrest solar nuisance claims', 'Nuisance and land use', 'County court', 'Lyle & Ibarra', [3, 3, 3, 3], [2, 2, 2, 3], [1, 1, 2, 2], [0.3, 0.8], 'Site inspection, 15 Oct'],
  ['Transformer import classification', 'Customs duties', 'Customs protest', 'In-house', [2, 3, 3, 2], [2, 2, 2, 2], [0, 0, 1, 1], [0.2, 0.7], 'Protest decision expected in Nov'],
  ['Regional gas storage inquiry', 'Antitrust', 'Federal regulator', 'Strand & Wilcox', [1, 1, 1, 2], [5, 5, 5, 5], [0, 0, 0, 0], [0.05, 0.3], 'Investigative demand response, 13 Nov'],
  ['Morales v. Corvane', 'Haul-road accident', 'State superior court', 'Lyle & Ibarra', [4, 4, 3, 3], [2, 2, 2, 2], [2, 2, 3, 3], [0.2, 0.8], 'Mediation, 21 Oct']
].map(([name, type, forum, counsel, L, I, st, f, next], i) => ({ n: i + 1, name, type, forum, counsel, L, I, st, f, next, flag: false, asked: false }));
const at = (m, q) => {
  const L = m.L[q], I = m.I[q], [lo, hi] = BANDS[I - 1];
  const low = Math.round((lo + (hi - lo) * m.f[0]) * 10) / 10, high = Math.round((lo + (hi - lo) * m.f[1]) * 10) / 10;
  const probable = L >= 4, rp = L === 2 || L === 3;
  const reserve = probable ? Math.round((low + (high - low) * (L === 5 ? 0.6 : 0.4)) * 10) / 10 : 0;
  return { L, I, s: L * I, st: m.st[q], low, high, reserve, probable, rp, weighted: PCT[L - 1] * (low + high) / 2 };
};
const tier = (s) => (s >= 12 ? 2 : s >= 6 ? 1 : 0);
const money = (v) => (Math.abs(v) < 0.05 ? '$0' : v >= 100 ? '$' + Math.round(v) + 'M' : v >= 1 ? '$' + v.toFixed(1) + 'M' : '$' + Math.round(v * 1000) + 'k');
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

/* ---------- state */
const state = { view: 'map', q: 3, trails: true, cell: null, stage: null, open: null };
const tipEl = $('.' + P + '__tip');
const toasts = $('.' + P + '__toasts');
const cellsEl = $('.' + P + '__cells');
const dotsEl = $('.' + P + '__dots');
const trailsEl = $('.' + P + '__trails');
const drawer = $('.' + P + '__drawer');
const dbody = $('.' + P + '__dbody');
function toast(msg) {
  const t = document.createElement('div');
  t.className = P + '__toast'; t.textContent = msg;
  toasts.append(t);
  while (toasts.children.length > 2) toasts.firstChild.remove();
  setTimeout(() => { t.classList.add('is-out'); setTimeout(() => t.remove(), 350); }, 2500);
}
function showTip(html, x, y) {
  tipEl.innerHTML = html; tipEl.hidden = false;
  const r = root.getBoundingClientRect(), w = tipEl.offsetWidth, h = tipEl.offsetHeight;
  let lx = x - r.left + 14, ly = y - r.top + 14;
  if (lx + w > r.width - 8) lx = x - r.left - w - 14;
  if (ly + h > r.height - 8) ly = y - r.top - h - 12;
  tipEl.style.translate = Math.max(8, lx) + 'px ' + Math.max(8, ly) + 'px';
}
const trend = (m, q) => (q === 0 ? 0 : Math.sign(at(m, q).s - at(m, q - 1).s));

/* ---------- KPIs with counting numbers */
const kpiEl = $('.' + P + '__kpis');
let kpiShown = null, kpiTween = 0;
function kpiValues(q) {
  const A = M.map((m) => at(m, q));
  const prob = A.filter((a) => a.probable), rp = A.filter((a) => a.rp);
  const prev = q ? M.map((m) => at(m, q - 1)) : null;
  return {
    open: M.length, weighted: A.reduce((s, a) => s + a.weighted, 0),
    probN: prob.length, reserve: prob.reduce((s, a) => s + a.reserve, 0), prevReserve: prev ? prev.filter((a) => a.probable).reduce((s, a) => s + a.reserve, 0) : null,
    rpN: rp.length, rpLo: rp.reduce((s, a) => s + a.low, 0), rpHi: rp.reduce((s, a) => s + a.high, 0),
    up: q ? M.filter((m) => trend(m, q) > 0).length : 0, down: q ? M.filter((m) => trend(m, q) < 0).length : 0
  };
}
function paintKpis(v) {
  const dRes = v.prevReserve == null ? null : v.reserve - v.prevReserve;
  kpiEl.innerHTML =
    `<div><dt>Risk-weighted exposure</dt><dd>${money(v.weighted)}</dd><small>${v.open} open matters · likelihood × midpoint</small></div>` +
    `<div><dt>Probable · accrued reserve</dt><dd>${money(v.reserve)}</dd><small>${Math.round(v.probN)} matters${dRes == null ? '' : ` · <span class="${dRes > 0 ? 'up' : dRes < 0 ? 'dn' : ''}">${dRes >= 0 ? '+' : '−'}${money(Math.abs(dRes))} vs ${Q[state.q - 1]}</span>`}</small></div>` +
    `<div><dt>Reasonably possible · disclosed</dt><dd>${money(v.rpLo)}–${money(v.rpHi)}</dd><small>${Math.round(v.rpN)} matters, range of loss not accrued</small></div>` +
    `<div><dt>Moved this quarter</dt><dd><span class="up">▲${Math.round(v.up)}</span> <span class="dn">▼${Math.round(v.down)}</span></dd><small>${state.q ? 'by likelihood × exposure vs ' + Q[state.q - 1] : 'first quarter in the dataset'}</small></div>`;
}
function renderKpis() {
  const to = kpiValues(state.q);
  if (!kpiShown || reduce.matches) { kpiShown = to; paintKpis(to); return; }
  const from = kpiShown, id = ++kpiTween, t0 = performance.now();
  const step = (now) => {
    if (!root.isConnected || id !== kpiTween) return;
    const k = Math.min(1, (now - t0) / 650), e = 1 - Math.pow(1 - k, 3);
    const v = {};
    for (const key in to) v[key] = to[key] == null ? null : from[key] == null ? to[key] : from[key] + (to[key] - from[key]) * e;
    v.probN = to.probN; v.rpN = to.rpN; v.up = to.up; v.down = to.down; v.open = to.open; v.prevReserve = to.prevReserve;
    paintKpis(k < 1 ? v : to);
    if (k < 1) requestAnimationFrame(step); else kpiShown = to;
  };
  requestAnimationFrame(step);
}

/* ---------- risk map */
function buildCells() {
  let h = '';
  for (let L = 5; L >= 1; L--) {
    h += `<div role="row" style="display:contents"><div class="yl" role="rowheader">${L}<small>${LIKE[L - 1]}</small></div>`;
    for (let I = 1; I <= 5; I++) {
      const s = L * I, t = (s - 1) / 24;
      const heat = t < 0.5 ? `color-mix(in oklab, var(--${P}-amber) ${Math.round(t * 200)}%, var(--${P}-olive))` : `color-mix(in oklab, var(--${P}-ember) ${Math.round((t - 0.5) * 200)}%, var(--${P}-amber))`;
      h += `<button type="button" class="${P}__cell" role="gridcell" data-l="${L}" data-i="${I}" aria-pressed="false" style="--heat:${heat};--a:${Math.round(14 + t * 26)}%"><span>${s}</span></button>`;
    }
    h += '</div>';
  }
  cellsEl.innerHTML = h;
  $('.' + P + '__xlab').innerHTML = '<span></span>' + BANDLBL.map((b) => `<span>${b}</span>`).join('') + '<span>Exposure if it goes wrong</span>';
}
function geom() {
  const W = cellsEl.clientWidth, H = cellsEl.clientHeight, g = 3, lw = 56;
  const cw = (W - lw - g * 5) / 5, rh = (H - g * 4) / 5;
  return { cx: (I) => lw + g + (I - 1) * (cw + g) + cw / 2, cy: (L) => (5 - L) * (rh + g) + rh / 2, cw, rh };
}
function positions(q) {
  const G = geom(), pos = {}, byCell = {};
  M.forEach((m) => { const a = at(m, q); (byCell[a.L + ':' + a.I] = byCell[a.L + ':' + a.I] || []).push(m); });
  Object.entries(byCell).forEach(([k, list]) => {
    const [L, I] = k.split(':').map(Number), n = list.length;
    const per = n <= 2 ? n : n <= 4 ? 2 : 3, rows = Math.ceil(n / per), sx = Math.min(30, G.cw / (per + 0.6)), sy = Math.min(30, G.rh / (rows + 0.6));
    list.forEach((m, j) => {
      const r = Math.floor(j / per), c = j % per, inRow = Math.min(per, n - r * per);
      pos[m.n] = [G.cx(I) + (c - (inRow - 1) / 2) * sx, G.cy(L) + (r - (rows - 1) / 2) * sy];
    });
  });
  return pos;
}
function visibleMatter(m) {
  const a = at(m, state.q);
  return (!state.cell || (a.L === state.cell[0] && a.I === state.cell[1])) && (state.stage == null || a.st === state.stage);
}
function renderDots() {
  const pos = positions(state.q);
  if (!dotsEl.children.length) {
    dotsEl.innerHTML = M.map((m, i) => `<button type="button" class="${P}__dot" data-n="${m.n}" style="--i:${i}">${m.n}</button>`).join('');
  }
  M.forEach((m) => {
    const d = $(`[data-n="${m.n}"]`, dotsEl), a = at(m, state.q), tr = trend(m, state.q);
    d.style.setProperty('--x', pos[m.n][0].toFixed(1) + 'px');
    d.style.setProperty('--y', pos[m.n][1].toFixed(1) + 'px');
    d.className = `${P}__dot${tr > 0 ? ' up' : tr < 0 ? ' dn' : ''}${visibleMatter(m) ? '' : ' is-dim'}${state.open === m.n ? ' is-sel' : ''}`;
    d.setAttribute('aria-label', `${m.n}. ${m.name}: ${LIKE[a.L - 1]}, ${BANDLBL[a.I - 1]}, ${STAGES[a.st]}${tr ? (tr > 0 ? ', risk up' : ', risk down') + ' since ' + Q[state.q - 1] : ''}`);
  });
  renderTrails(pos);
  $$('.' + P + '__cell', cellsEl).forEach((c) => {
    const L = +c.dataset.l, I = +c.dataset.i, n = M.filter((m) => { const a = at(m, state.q); return a.L === L && a.I === I; }).length;
    c.setAttribute('aria-label', `Likelihood ${L} (${LIKE[L - 1]}), exposure ${BANDLBL[I - 1]}: ${n} matter${n === 1 ? '' : 's'}. Filters the list.`);
    c.setAttribute('aria-pressed', String(!!state.cell && state.cell[0] === L && state.cell[1] === I));
  });
}
let trailSig = '';
function renderTrails(pos) {
  const sig = state.q + ':' + state.trails + ':' + cellsEl.clientWidth + 'x' + cellsEl.clientHeight;
  if (sig === trailSig) return;
  trailSig = sig;
  trailsEl.innerHTML = '';
  if (!state.trails || state.q === 0) return;
  const prev = positions(state.q - 1);
  let i = 0, s = '';
  M.forEach((m) => {
    const [x1, y1] = prev[m.n], [x2, y2] = pos[m.n];
    if (Math.hypot(x2 - x1, y2 - y1) < 4) return;
    const tr = trend(m, state.q), cls = tr > 0 ? 'up' : tr < 0 ? 'dn' : '';
    const mx = (x1 + x2) / 2 + (y2 - y1) * 0.18, my = (y1 + y2) / 2 - (x2 - x1) * 0.18;
    /* stop short of the dot and add a hand-built arrowhead */
    const ang = Math.atan2(y2 - my, x2 - mx), ex = x2 - Math.cos(ang) * 15, ey = y2 - Math.sin(ang) * 15;
    const h1 = [ex - Math.cos(ang - 0.5) * 7, ey - Math.sin(ang - 0.5) * 7], h2 = [ex - Math.cos(ang + 0.5) * 7, ey - Math.sin(ang + 0.5) * 7];
    s += `<circle cx="${x1}" cy="${y1}" r="3"/><path class="${cls}" pathLength="1" style="--i:${i}" d="M${x1} ${y1}Q${mx} ${my} ${ex} ${ey}"/><path class="${cls} head" style="--i:${i++}" d="M${h1[0]} ${h1[1]}L${ex} ${ey}L${h2[0]} ${h2[1]}"/>`;
  });
  trailsEl.innerHTML = s;
}
dotsEl.addEventListener('pointermove', (e) => {
  const d = e.target.closest('.' + P + '__dot');
  if (!d) { tipEl.hidden = true; return; }
  const m = M[+d.dataset.n - 1], a = at(m, state.q), tr = trend(m, state.q);
  const p = state.q ? at(m, state.q - 1) : null;
  showTip(`<b>${m.n}. ${esc(m.name)}</b><span>${LIKE[a.L - 1]} · ${money(a.low)}–${money(a.high)} · ${STAGES[a.st]}</span><span>Score ${a.s}${p ? ` (was ${p.s} in ${Q[state.q - 1]}${tr > 0 ? ', up' : tr < 0 ? ', down' : ''})` : ''}</span>${a.probable ? `<span>Accrued ${money(a.reserve)}</span>` : ''}`, e.clientX, e.clientY);
});
dotsEl.addEventListener('pointerleave', () => { tipEl.hidden = true; });

/* ---------- list + stages */
function renderList() {
  const rows = M.filter(visibleMatter).map((m) => ({ m, a: at(m, state.q), tr: trend(m, state.q), d: state.q ? at(m, state.q).s - at(m, state.q - 1).s : 0 })).sort((x, y) => y.a.s - x.a.s || y.a.high - x.a.high);
  $('.' + P + '__list').innerHTML = rows.map(({ m, a, tr, d }) => `<li><button type="button" class="${P}__li${tr > 0 ? ' up' : tr < 0 ? ' dn' : ''}" data-open="${m.n}" aria-current="${state.open === m.n}"><i>${m.n}</i><b>${esc(m.name)}</b><span class="sc">${a.s}<small class="${tr > 0 ? 'up' : tr < 0 ? 'dn' : ''}">${tr ? (tr > 0 ? '▲' : '▼') + Math.abs(d) : '—'}</small></span><small>${STAGES[a.st]} · ${money(a.low)}–${money(a.high)}${a.probable ? ' · accrued ' + money(a.reserve) : ''}</small></button></li>`).join('') ||
    `<li style="padding:16px;color:var(--${P}-mute);font-size:12px">No matters sit here in ${Q[state.q]}.</li>`;
  const f = [];
  if (state.cell) f.push(`${LIKE[state.cell[0] - 1]} × ${BANDLBL[state.cell[1] - 1]}`);
  if (state.stage != null) f.push(STAGES[state.stage]);
  $('[data-k=listh]').textContent = f.length ? f.join(' · ') + ` (${rows.length})` : `All ${M.length} open matters`;
  $('[data-act=clear]').hidden = !f.length;
}
function renderStages() {
  const A = M.map((m) => at(m, state.q));
  const maxN = Math.max(1, ...STAGES.map((_, k) => A.filter((a) => a.st === k).length));
  $('.' + P + '__stages').innerHTML = STAGES.map((s, k) => {
    const l = A.filter((a) => a.st === k), n = l.length, t = [0, 1, 2].map((x) => l.filter((a) => tier(a.s) === x).length);
    return `<button type="button" data-stage="${k}" aria-pressed="${state.stage === k}" aria-label="${s}: ${n} matters, ${t[2]} high risk. Filters the map."><b>${s}<span>${n}</span></b><span class="bar">${t.map((c, x) => `<i class="t${x}" style="--w:${(c / maxN * 100).toFixed(1)}%"></i>`).join('')}</span></button>`;
  }).join('');
}

/* ---------- reserve bridge */
function bridge(q) {
  if (q === 0) return null;
  const now = M.map((m) => [m, at(m, q), at(m, q - 1)]);
  const start = now.reduce((s, [, , p]) => s + p.reserve, 0), end = now.reduce((s, [, a]) => s + a.reserve, 0);
  const pick = (f) => now.filter(f);
  const nw = pick(([, a, p]) => a.probable && !p.probable), inc = pick(([, a, p]) => a.probable && p.probable && a.reserve > p.reserve);
  const dec = pick(([, a, p]) => a.probable && p.probable && a.reserve < p.reserve), rel = pick(([, a, p]) => !a.probable && p.probable);
  return [
    ['Opening', start, 'tot', []], ['New accruals', nw.reduce((s, [, a]) => s + a.reserve, 0), 'add', nw],
    ['Increases', inc.reduce((s, [, a, p]) => s + a.reserve - p.reserve, 0), 'add', inc], ['Decreases', -dec.reduce((s, [, a, p]) => s + p.reserve - a.reserve, 0), 'sub', dec],
    ['Released', -rel.reduce((s, [, , p]) => s + p.reserve, 0), 'sub', rel], ['Closing', end, 'tot', []]
  ];
}
function renderBridge() {
  const svg = $('.' + P + '__wf'), W = svg.clientWidth || 600, H = 300, pl = 48, pb = 40, pt = 22;
  const B = bridge(state.q);
  $('[data-k=bridgeh]').textContent = state.q ? `Accrued reserve bridge · ${Q[state.q - 1]} → ${Q[state.q]}` : `Accrued reserve · ${Q[0]}`;
  if (!B) {
    const tot = M.reduce((s, m) => s + at(m, 0).reserve, 0);
    $('[data-k=bridges]').textContent = 'The dataset starts here, so there is nothing to bridge from.';
    svg.setAttribute('viewBox', `0 0 ${W} ${H}`);
    svg.innerHTML = `<text class="lb" x="${W / 2}" y="${H / 2 - 10}" text-anchor="middle">Opening reserve ${money(tot)}</text><text class="ax" x="${W / 2}" y="${H / 2 + 10}" text-anchor="middle">Pick ${Q[1]} or later to see what moved it</text>`;
  } else {
    const end = B[5][1], start = B[0][1], diff = end - start;
    $('[data-k=bridges]').textContent = `${diff >= 0 ? '+' : '−'}${money(Math.abs(diff))} over the quarter`;
    let run = 0, peak = 0;
    B.forEach(([, v, k]) => { if (k === 'tot') run = v; else run += v; peak = Math.max(peak, run, k === 'tot' ? v : 0); });
    const step = peak > 120 ? 50 : peak > 60 ? 25 : 10, top = Math.ceil(peak * 1.08 / step) * step;
    const y = (v) => pt + (1 - v / top) * (H - pt - pb), bw = (W - pl) / B.length;
    let s = '';
    for (let v = 0; v <= top; v += step) s += `<line class="gl" x1="${pl}" x2="${W}" y1="${y(v)}" y2="${y(v)}"/><text class="ax" x="${pl - 8}" y="${y(v) + 3}" text-anchor="end">${v ? '$' + v + 'M' : '0'}</text>`;
    run = 0;
    B.forEach(([n, v, k, who], i) => {
      const x = pl + i * bw + bw * 0.18, w = bw * 0.64;
      let y0, y1;
      if (k === 'tot') { y0 = 0; y1 = v; run = v; } else { y0 = run; y1 = run + v; run = y1; }
      const lo = Math.min(y0, y1), hi = Math.max(y0, y1);
      const ht = Math.max(v ? 2 : 0, y(lo) - y(hi));
      s += `<g class="st" data-b="${i}"><rect class="bar ${k}" style="--i:${i}" x="${x}" y="${y(hi)}" width="${w}" height="${ht}" rx="3"/>` +
        `<text class="vl" x="${x + w / 2}" y="${y(hi) - 6}" text-anchor="middle">${k === 'tot' ? money(v) : (v >= 0 ? '+' : '−') + money(Math.abs(v))}</text>` +
        `<text class="lb" x="${x + w / 2}" y="${H - 22}" text-anchor="middle">${n}</text><text class="ax" x="${x + w / 2}" y="${H - 8}" text-anchor="middle">${k === 'tot' ? (i ? Q[state.q] : Q[state.q - 1]) : who.length + ' matter' + (who.length === 1 ? '' : 's')}</text></g>`;
      if (i < B.length - 1) s += `<line class="cn" x1="${x + w}" x2="${x + bw}" y1="${y(run)}" y2="${y(run)}"/>`;
    });
    svg.setAttribute('viewBox', `0 0 ${W} ${H}`);
    svg.innerHTML = s;
    svg._b = B;
  }
  /* table of accrued matters */
  const rows = M.map((m) => [m, at(m, state.q), state.q ? at(m, state.q - 1) : null]).filter(([, a, p]) => a.probable || (p && p.probable));
  $('.' + P + '__rt tbody').innerHTML = rows.map(([m, a, p]) => {
    const d = a.reserve - (p ? p.reserve : 0);
    return `<tr data-open="${m.n}" tabindex="0"><td><b>${m.n}. ${esc(m.name)}</b><small>${LIKE[a.L - 1]} · ${STAGES[a.st]}</small></td><td>${p ? (p.reserve ? money(p.reserve) : '—') : '—'}</td><td>${a.reserve ? money(a.reserve) : '—'}</td><td class="${d > 0 ? 'up' : d < 0 ? 'dn' : ''}">${p ? (d ? (d > 0 ? '+' : '−') + money(Math.abs(d)) : '—') : 'n/a'}</td></tr>`;
  }).join('');
  const tp = rows.reduce((s, [, , p]) => s + (p ? p.reserve : 0), 0), tn = rows.reduce((s, [, a]) => s + a.reserve, 0);
  $('.' + P + '__rt tfoot').innerHTML = `<tr><td>Total accrued</td><td>${state.q ? money(tp) : '—'}</td><td>${money(tn)}</td><td class="${tn - tp > 0 ? 'up' : 'dn'}">${state.q ? (tn - tp >= 0 ? '+' : '−') + money(Math.abs(tn - tp)) : 'n/a'}</td></tr>`;
}
$('.' + P + '__wf').addEventListener('pointermove', (e) => {
  const g = e.target.closest('.st'), B = $('.' + P + '__wf')._b;
  if (!g || !B) { tipEl.hidden = true; return; }
  const [n, v, k, who] = B[+g.dataset.b];
  showTip(`<b>${n} · ${k === 'tot' ? money(v) : (v >= 0 ? '+' : '−') + money(Math.abs(v))}</b>` + (who.length ? who.map(([m, a, p]) => `<span>${m.n}. ${esc(m.name)} · ${money(p.reserve)} → ${money(a.reserve)}</span>`).join('') : `<span>${k === 'tot' ? 'Total accrued for probable matters' : 'No matters in this step'}</span>`), e.clientX, e.clientY);
});
$('.' + P + '__wf').addEventListener('pointerleave', () => { tipEl.hidden = true; });

/* ---------- drawer */
let lastFocus = null;
function renderDrawer() {
  const m = M[state.open - 1]; if (!m) return;
  const a = at(m, state.q), [blo, bhi] = BANDS[a.I - 1];
  const scale = Math.max(bhi, a.high) * 1.05, pct = (v) => (v / scale * 100).toFixed(1) + '%';
  const hist = Q.map((_, q) => at(m, q).s), W = 330, H = 90;
  const x = (i) => 24 + i * (W - 48) / 3, y = (v) => 12 + (1 - v / 25) * (H - 34);
  const cls = a.probable ? 'Probable — accrued' : a.rp ? 'Reasonably possible — disclosed' : 'Remote — no disclosure';
  dbody.innerHTML =
    `<div class="${P}__dtop"><div><p>Matter ${m.n} · ${esc(m.type)}</p><h3 id="${P}-dt">${esc(m.name)}</h3></div><button type="button" class="${P}__x" aria-label="Close matter"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 6l12 12M18 6 6 18"/></svg></button></div>` +
    `<dl class="${P}__facts"><div><dt>Forum</dt><dd>${esc(m.forum)}</dd></div><div><dt>Counsel</dt><dd>${esc(m.counsel)}</dd></div><div><dt>Likelihood · ${Q[state.q]}</dt><dd>${LIKE[a.L - 1]} (${Math.round(PCT[a.L - 1] * 100)}%)</dd></div><div><dt>Treatment</dt><dd>${cls}</dd></div></dl>` +
    `<section class="${P}__sect"><h4>Range of loss</h4><div class="${P}__range" aria-label="Range ${money(a.low)} to ${money(a.high)}${a.probable ? ', accrued ' + money(a.reserve) : ''}"><span class="tr"></span><span class="rg" style="left:${pct(a.low)};width:calc(${pct(a.high)} - ${pct(a.low)})"></span>${a.probable ? `<span class="rs" style="left:${pct(a.reserve)}" title="Accrued ${money(a.reserve)}"></span>` : ''}<span style="left:${pct(a.low)};translate:-50% 0">${money(a.low)}</span><span style="left:${pct(a.high)};translate:-50% 0">${money(a.high)}</span></div></section>` +
    `<section class="${P}__sect"><h4>Stage · ${STAGES[a.st]}</h4><div class="${P}__steps" aria-hidden="true">${STAGES.map((_, k) => `<i class="${k < a.st ? 'on' : k === a.st ? 'now' : ''}" title="${STAGES[k]}"></i>`).join('')}</div><p style="font-size:12px;color:var(--${P}-mute)">Next: ${esc(m.next)}</p></section>` +
    `<section class="${P}__sect"><h4>Risk score by quarter</h4><svg class="${P}__hist" viewBox="0 0 ${W} ${H}" role="img" aria-label="Risk score ${hist.join(', ')}">` +
    [5, 15, 25].map((v) => `<line class="gl" x1="18" x2="${W - 18}" y1="${y(v)}" y2="${y(v)}"/>`).join('') +
    `<path d="M${hist.map((v, i) => x(i) + ' ' + y(v)).join('L')}"/>` + hist.map((v, i) => `<circle class="${i === state.q ? 'now' : ''}" cx="${x(i)}" cy="${y(v)}" r="4.5"/><text class="vl" x="${x(i)}" y="${y(v) - 9}" text-anchor="middle">${v}</text><text class="ax" x="${x(i)}" y="${H - 4}" text-anchor="middle">${Q[i]}</text>`).join('') + `</svg></section>` +
    `<div class="${P}__acts"><button type="button" class="pri" data-act="flag" aria-pressed="${m.flag}">${m.flag ? 'On the board report · remove' : 'Flag for the board report'}</button>` +
    `<button type="button" data-act="ask" ${m.asked ? `aria-disabled="true" title="${esc(m.counsel)} already has the request — due in 5 business days"` : ''}>${m.asked ? 'Assessment requested' : 'Request updated assessment from counsel'}</button></div>`;
}
function openDrawer(n, from) {
  if (!state.open) lastFocus = from || document.activeElement;
  state.open = n; renderDrawer(); renderDots(); renderList();
  drawer.setAttribute('data-open', ''); drawer.removeAttribute('inert'); drawer.setAttribute('aria-hidden', 'false'); drawer.setAttribute('aria-labelledby', P + '-dt');
  $('.' + P + '__x', dbody).focus({ preventScroll: true });
}
function closeDrawer() {
  if (!state.open) return;
  state.open = null; renderDots(); renderList();
  drawer.removeAttribute('data-open'); drawer.setAttribute('inert', ''); drawer.setAttribute('aria-hidden', 'true');
  if (lastFocus && lastFocus.isConnected) lastFocus.focus({ preventScroll: true });
  lastFocus = null;
}

/* ---------- render + events */
function render() {
  renderKpis();
  if (state.view === 'map') { renderDots(); renderList(); renderStages(); }
  else renderBridge();
  if (state.open) renderDrawer();
}
function setView(v) {
  state.view = v;
  $$('.' + P + '__rail button').forEach((b) => (b.dataset.view === v ? b.setAttribute('aria-current', 'page') : b.removeAttribute('aria-current')));
  $$('.' + P + '__view').forEach((s) => { s.hidden = s.dataset.view !== v; });
  $('[data-k=title]').textContent = v === 'map' ? 'Portfolio risk map' : 'Reserves and disclosure';
  $('[data-act=trails]').hidden = v !== 'map';
  tipEl.hidden = true;
  render();
}
root.addEventListener('click', (e) => {
  const t = e.target;
  const nav = t.closest('.' + P + '__rail button');
  if (nav) { closeDrawer(); setView(nav.dataset.view); return; }
  const q = t.closest('[data-q]');
  if (q) {
    state.q = +q.dataset.q;
    $$('[data-q]').forEach((b) => { const on = b === q; b.setAttribute('aria-checked', String(on)); b.tabIndex = on ? 0 : -1; });
    render(); return;
  }
  const tr = t.closest('[data-act=trails]');
  if (tr) { state.trails = !state.trails; tr.setAttribute('aria-checked', String(state.trails)); renderDots(); return; }
  const cell = t.closest('.' + P + '__cell');
  if (cell) {
    const L = +cell.dataset.l, I = +cell.dataset.i;
    state.cell = state.cell && state.cell[0] === L && state.cell[1] === I ? null : [L, I];
    renderDots(); renderList(); return;
  }
  const st = t.closest('[data-stage]');
  if (st) { const k = +st.dataset.stage; state.stage = state.stage === k ? null : k; renderStages(); renderDots(); renderList(); return; }
  if (t.closest('[data-act=clear]')) { state.cell = null; state.stage = null; renderStages(); renderDots(); renderList(); return; }
  const dot = t.closest('.' + P + '__dot');
  if (dot) { openDrawer(+dot.dataset.n, dot); return; }
  const op = t.closest('[data-open]');
  if (op) { openDrawer(+op.dataset.open, op); return; }
  if (t.closest('.' + P + '__x')) { closeDrawer(); return; }
  const act = t.closest('[data-act=flag], [data-act=ask]');
  if (act) {
    const m = M[state.open - 1];
    if (act.dataset.act === 'flag') { m.flag = !m.flag; toast(m.flag ? `Matter ${m.n} added to the Q4 board report` : `Matter ${m.n} removed from the board report`); }
    else if (act.getAttribute('aria-disabled') === 'true') { toast(act.title); return; }
    else { m.asked = true; toast(`Assessment requested from ${m.counsel}`); }
    renderDrawer();
    const f = $(`[data-act=${act.dataset.act}]`, dbody); if (f) f.focus({ preventScroll: true });
  }
});
root.addEventListener('keydown', (e) => {
  if (e.key === 'Escape' && state.open) { e.preventDefault(); closeDrawer(); return; }
  const r = e.target.closest && e.target.closest('[role=radio]');
  if (r && /^Arrow/.test(e.key)) {
    const all = $$('[role=radio]', r.parentElement), i = all.indexOf(r);
    const n = all[Math.max(0, Math.min(all.length - 1, i + (/Right|Down/.test(e.key) ? 1 : -1)))];
    e.preventDefault(); if (n !== r) { n.click(); n.focus(); }
    return;
  }
  const c = e.target.closest && e.target.closest('.' + P + '__cell');
  if (c && /^Arrow/.test(e.key)) {
    e.preventDefault();
    let L = +c.dataset.l, I = +c.dataset.i;
    if (e.key === 'ArrowUp') L = Math.min(5, L + 1); if (e.key === 'ArrowDown') L = Math.max(1, L - 1);
    if (e.key === 'ArrowLeft') I = Math.max(1, I - 1); if (e.key === 'ArrowRight') I = Math.min(5, I + 1);
    const n = $(`.${P}__cell[data-l="${L}"][data-i="${I}"]`); if (n) n.focus();
    return;
  }
  const li = e.target.closest && e.target.closest('.' + P + '__li, .' + P + '__rt tbody tr');
  if (li && (e.key === 'ArrowDown' || e.key === 'ArrowUp')) {
    e.preventDefault();
    const all = $$(li.tagName === 'TR' ? '.' + P + '__rt tbody tr' : '.' + P + '__li'), i = all.indexOf(li);
    const n = all[Math.max(0, Math.min(all.length - 1, i + (e.key === 'ArrowDown' ? 1 : -1)))]; n.focus();
  } else if (li && li.tagName === 'TR' && e.key === 'Enter') { e.preventDefault(); openDrawer(+li.dataset.open, li); }
});

/* ---------- mount */
buildCells();
render();
const io = new IntersectionObserver((en) => { root.classList.toggle('is-live', en[0].isIntersecting); });
io.observe(root);
let rz = 0, lastW = 0, lastH = 0;
const ro = new ResizeObserver(() => {
  cancelAnimationFrame(rz);
  rz = requestAnimationFrame(() => {
    if (!root.isConnected) { ro.disconnect(); io.disconnect(); return; }
    const w = cellsEl.clientWidth, h = cellsEl.clientHeight;
    if ((w !== lastW || h !== lastH) && state.view === 'map') { lastW = w; lastH = h; renderDots(); }
    if (state.view === 'bridge') renderBridge();
  });
});
ro.observe(root);
